window.PV_BANK=[{"id":"licensing-001","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age for a regular Class E license.","h2":"You can get a Florida learner license when you are 15 years old, one year before you can get a Class E license at 16.","p":"Right. The learner license starts at age 15."},"es":{"q":"En Florida, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad para la licencia Clase E normal.","h2":"Usted puede obtener la licencia de aprendiz en Florida a los 15 años, un año antes de poder obtener la licencia Clase E a los 16.","p":"Correcto. La licencia de aprendiz empieza a los 15 años."},"ref":{"doc":"FL","page":8}},{"id":"licensing-002","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver with a learner license must have someone with them. How old must that person be?","o":["At least 16 years old","At least 18 years old","At least 25 years old","At least 21 years old"],"h1":"The helper must be an experienced adult, older than a new 18-year-old driver.","h2":"A learner must always drive with a licensed driver who is at least 21 years old, because that person needs adult experience to guide them.","p":"Right. The person with you must be a licensed driver age 21 or older."},"es":{"q":"En Florida, quien tiene licencia de aprendiz debe ir acompañado. ¿Qué edad debe tener esa persona?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 25 años","Por lo menos 21 años"],"h1":"El acompañante debe ser un adulto con experiencia, mayor que un conductor nuevo de 18 años.","h2":"El aprendiz siempre debe manejar con un conductor con licencia que tenga por lo menos 21 años, porque esa persona necesita experiencia de adulto para guiarlo.","p":"Correcto. Su acompañante debe tener licencia y 21 años o más."},"ref":{"doc":"FL","page":25}},{"id":"licensing-003","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, where must the licensed adult sit when a learner is driving?","o":["In the front passenger seat","In any back seat","Behind the driver","Anywhere in the car"],"h1":"The adult must be able to see the road and help right away.","h2":"The licensed adult must sit in the front passenger seat, next to the learner, so they can watch the road and help quickly.","p":"Right. The adult sits in the front seat, next to you."},"es":{"q":"En Florida, ¿dónde debe sentarse el adulto con licencia cuando maneja un aprendiz?","o":["En el asiento delantero del pasajero","En cualquier asiento de atrás","Detrás del conductor","En cualquier lugar del carro"],"h1":"El adulto debe poder ver la calle y ayudar enseguida.","h2":"El adulto con licencia debe sentarse en el asiento delantero del pasajero, al lado del aprendiz, para ver la calle y ayudar rápido.","p":"Correcto. El adulto va en el asiento de adelante, a su lado."},"ref":{"doc":"FL","page":null}},{"id":"licensing-004","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, during the first 3 months with a learner license, when may you drive?","o":["Any time of day or night","Only until midnight","Only during daylight hours","Only on weekends"],"h1":"New learners start with the easiest light conditions.","h2":"For the first 3 months, a learner may drive only during daylight, because seeing well makes it easier to learn safely.","p":"Right. The first 3 months are daylight only."},"es":{"q":"En Florida, durante los primeros 3 meses con licencia de aprendiz, ¿cuándo puede manejar?","o":["A cualquier hora del día o de la noche","Solo hasta la medianoche","Solo durante las horas de luz del día","Solo los fines de semana"],"h1":"Los aprendices nuevos empiezan con la luz más fácil.","h2":"Durante los primeros 3 meses, el aprendiz solo puede manejar de día, porque ver bien hace más fácil aprender con seguridad.","p":"Correcto. Los primeros 3 meses son solo de día."},"ref":{"doc":"FL","page":25}},{"id":"licensing-005","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after 3 months with a learner license, until what time may you drive?","o":["Until 8 p.m.","Until 10 p.m.","Until midnight","Until 1 a.m."],"h1":"After 3 months, you may drive later, but not late into the night.","h2":"After the first 3 months, a learner may drive until 10 p.m., still with a licensed driver age 21 or older.","p":"Right. After 3 months, a learner may drive until 10 p.m."},"es":{"q":"En Florida, después de 3 meses con licencia de aprendiz, ¿hasta qué hora puede manejar?","o":["Hasta las 8 p.m.","Hasta las 10 p.m.","Hasta la medianoche","Hasta la 1 a.m."],"h1":"Después de 3 meses puede manejar más tarde, pero no hasta muy tarde en la noche.","h2":"Después de los primeros 3 meses, el aprendiz puede manejar hasta las 10 p.m., siempre con un conductor con licencia de 21 años o más.","p":"Correcto. Después de 3 meses, el aprendiz puede manejar hasta las 10 p.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-006","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what course must a first-time driver finish before getting a license?","o":["A defensive driving course for truck drivers","A first aid and CPR course","A motorcycle safety course","The Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"The course covers traffic laws and the danger of alcohol and drugs.","h2":"First-time drivers must finish the Traffic Law and Substance Abuse Education course, called TLSAE, which teaches traffic laws and how alcohol and drugs affect driving.","p":"Right. First-time drivers must take the TLSAE course."},"es":{"q":"En Florida, ¿qué curso debe terminar una persona que saca su primera licencia?","o":["Un curso de manejo defensivo para camioneros","Un curso de primeros auxilios y RCP","Un curso de seguridad en motocicleta","El curso de Ley de Tránsito y Educación sobre Abuso de Sustancias (TLSAE)"],"h1":"El curso trata de las leyes de tránsito y del peligro del alcohol y las drogas.","h2":"Quien saca su primera licencia debe terminar el curso de Ley de Tránsito y Educación sobre Abuso de Sustancias, llamado TLSAE, que enseña las leyes de tránsito y cómo el alcohol y las drogas afectan al manejar.","p":"Correcto. Los conductores nuevos deben tomar el curso TLSAE."},"ref":{"doc":"FL","page":17}},{"id":"licensing-007","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, the learner license knowledge test has 50 questions. How many must you answer correctly to pass?","o":["At least 40","At least 30","At least 35","All 50"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 40 of the 50 questions correctly, which is 80 percent, to pass the knowledge test.","p":"Right. You need 40 correct answers out of 50."},"es":{"q":"En Florida, el examen de conocimientos para la licencia de aprendiz tiene 50 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["Por lo menos 40","Por lo menos 30","Por lo menos 35","Las 50"],"h1":"Necesita el 80 por ciento de las preguntas correctas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas, que es el 80 por ciento, para aprobar el examen de conocimientos.","p":"Correcto. Necesita 40 respuestas correctas de 50."},"ref":{"doc":"FL","page":null}},{"id":"licensing-008","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old wants a Class E license. How long must they first hold a learner license?","o":["3 months, with no traffic convictions","6 months, even with traffic convictions","12 months, or until age 18, with no traffic convictions","24 months, with no traffic convictions"],"h1":"Think about one full year of practice without breaking traffic laws.","h2":"A teen must hold the learner license for 12 months, or until turning 18, with no traffic convictions before getting a Class E license.","p":"Right. Hold the learner license 12 months with a clean record."},"es":{"q":"En Florida, una persona de 16 años quiere la licencia Clase E. ¿Cuánto tiempo debe tener antes la licencia de aprendiz?","o":["3 meses, sin condenas de tránsito","6 meses, aunque tenga condenas de tránsito","12 meses, o hasta cumplir 18, sin condenas de tránsito","24 meses, sin condenas de tránsito"],"h1":"Piense en un año completo de práctica sin violar las leyes de tránsito.","h2":"Un joven debe tener la licencia de aprendiz por 12 meses, o hasta cumplir 18 años, sin condenas de tránsito antes de obtener la licencia Clase E.","p":"Correcto. Tenga la licencia de aprendiz 12 meses con un récord limpio."},"ref":{"doc":"FL","page":8}},{"id":"licensing-009","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how many hours of supervised driving must a teen complete before getting a Class E license?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is a large number, with some of the hours at night.","h2":"A teen must complete 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Teens need 50 hours of supervised driving."},"es":{"q":"En Florida, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener la licencia Clase E?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es un número grande, y algunas de las horas son de noche.","h2":"Un joven debe completar 50 horas de manejo supervisado, y 10 de esas horas deben ser de noche.","p":"Correcto. Los jóvenes necesitan 50 horas de manejo supervisado."},"ref":{"doc":"FL","page":8}},{"id":"licensing-010","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, of the supervised driving hours a teen needs, how many must be at night?","o":["5 hours","25 hours","50 hours","10 hours"],"h1":"It is a small part of the total supervised hours.","h2":"Of the 50 supervised hours, at least 10 must be at night, so the teen learns to drive in the dark before driving alone.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Florida, de las horas de manejo supervisado que necesita un joven, ¿cuántas deben ser de noche?","o":["5 horas","25 horas","50 horas","10 horas"],"h1":"Es una parte pequeña del total de horas supervisadas.","h2":"De las 50 horas supervisadas, por lo menos 10 deben ser de noche, para que el joven aprenda a manejar en la oscuridad antes de manejar solo.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"ref":{"doc":"FL","page":8}},{"id":"licensing-011","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who certifies that a teen under 18 completed the supervised driving hours?","o":["A parent, legal guardian, or responsible adult","The teen alone","A police officer","The school principal"],"h1":"Think about the adult who is legally responsible for the teen.","h2":"A parent, legal guardian, or responsible adult must certify that the teen completed the supervised driving hours.","p":"Right. A parent or guardian certifies the driving hours."},"es":{"q":"En Florida, ¿quién certifica que un joven menor de 18 completó las horas de manejo supervisado?","o":["Un padre, tutor legal o adulto responsable","El joven solo","Un oficial de policía","El director de la escuela"],"h1":"Piense en el adulto que es legalmente responsable del joven.","h2":"Un padre, tutor legal o adulto responsable debe certificar que el joven completó las horas de manejo supervisado.","p":"Correcto. Un padre o tutor certifica las horas de manejo."},"ref":{"doc":"FL","page":8}},{"id":"licensing-012","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old with a Class E license may not drive alone during which hours?","o":["From 9 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 8 a.m."],"h1":"The younger the driver, the longer the night hours they cannot drive alone.","h2":"A 16-year-old may not drive from 11 p.m. to 6 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 16, no driving alone from 11 p.m. to 6 a.m."},"es":{"q":"En Florida, una persona de 16 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 9 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 8 a.m."],"h1":"Mientras más joven es el conductor, más largas son las horas de la noche en que no puede manejar solo.","h2":"Una persona de 16 años no puede manejar de 11 p.m. a 6 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 16, no se maneja solo de 11 p.m. a 6 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-013","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, a 17-year-old with a Class E license may not drive alone during which hours?","o":["From 11 p.m. to 6 a.m.","From 1 a.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 2 a.m. to 7 a.m."],"h1":"A 17-year-old gets a shorter limit than a 16-year-old.","h2":"A 17-year-old may not drive from 1 a.m. to 5 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 17, no driving alone from 1 a.m. to 5 a.m."},"es":{"q":"En Florida, una persona de 17 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 2 a.m. a 7 a.m."],"h1":"A los 17 años el límite es más corto que a los 16.","h2":"Una persona de 17 años no puede manejar de 1 a.m. a 5 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 17, no se maneja solo de 1 a.m. a 5 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-014","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, when may a 16-year-old drive alone during curfew hours?","o":["When driving to a friend's house","When the roads are empty","When the trip is under 5 miles","When driving to or from work"],"h1":"The law makes an exception for a job.","h2":"A 16-year-old may drive alone during curfew hours only when driving to or from work, or when a licensed driver age 21 or older is with them.","p":"Right. Driving to or from work is allowed during curfew."},"es":{"q":"En Florida, ¿cuándo puede una persona de 16 años manejar sola en las horas restringidas?","o":["Cuando va a la casa de un amigo","Cuando las calles están vacías","Cuando el viaje es de menos de 5 millas","Cuando maneja hacia o desde el trabajo"],"h1":"La ley hace una excepción por el empleo.","h2":"Una persona de 16 años puede manejar sola en las horas restringidas solo cuando va hacia o desde el trabajo, o cuando la acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Se permite manejar hacia o desde el trabajo en esas horas."},"ref":{"doc":"FL","page":25}},{"id":"licensing-015","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what happens if you get 12 points on your driving record within 12 months?","o":["Your license is suspended for 30 days","You get a warning letter only","Your license is suspended for 1 year","Nothing happens"],"h1":"This is the first and shortest point suspension.","h2":"If you get 12 points within 12 months, your license is suspended for 30 days.","p":"Right. 12 points in 12 months means a 30-day suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 12 puntos en su récord de manejo dentro de 12 meses?","o":["Le suspenden la licencia por 30 días","Solo recibe una carta de advertencia","Le suspenden la licencia por 1 año","No pasa nada"],"h1":"Es la primera suspensión por puntos y la más corta.","h2":"Si acumula 12 puntos dentro de 12 meses, le suspenden la licencia por 30 días.","p":"Correcto. 12 puntos en 12 meses significa 30 días de suspensión."},"ref":{"doc":"FL","page":29}},{"id":"licensing-016","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what happens if you get 18 points on your driving record within 18 months?","o":["Your license is suspended for 30 days","Your license is suspended for 5 years","Your license is suspended for 3 months","You must only pay a fine"],"h1":"It is longer than the 30-day suspension, but shorter than one year.","h2":"If you get 18 points within 18 months, your license is suspended for 3 months.","p":"Right. 18 points in 18 months means a 3-month suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 18 puntos en su récord de manejo dentro de 18 meses?","o":["Le suspenden la licencia por 30 días","Le suspenden la licencia por 5 años","Le suspenden la licencia por 3 meses","Solo tiene que pagar una multa"],"h1":"Es más larga que la suspensión de 30 días, pero más corta que un año.","h2":"Si acumula 18 puntos dentro de 18 meses, le suspenden la licencia por 3 meses.","p":"Correcto. 18 puntos en 18 meses significa 3 meses de suspensión."},"ref":{"doc":"FL","page":29}},{"id":"licensing-017","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens if you get 24 points on your driving record within 36 months?","o":["Your license is suspended for 3 months","Your license is suspended for 1 year","Your license is suspended for 30 days","You must retake only the vision test"],"h1":"This is the most points, so it brings the longest point suspension.","h2":"If you get 24 points within 36 months, your license is suspended for 1 year.","p":"Right. 24 points in 36 months means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 24 puntos en su récord de manejo dentro de 36 meses?","o":["Le suspenden la licencia por 3 meses","Le suspenden la licencia por 1 año","Le suspenden la licencia por 30 días","Solo tiene que repetir el examen de la vista"],"h1":"Son la mayor cantidad de puntos, así que traen la suspensión más larga.","h2":"Si acumula 24 puntos dentro de 36 meses, le suspenden la licencia por 1 año.","p":"Correcto. 24 puntos en 36 meses significa 1 año de suspensión."},"ref":{"doc":"FL","page":29}},{"id":"licensing-018","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 18 gets 6 points within 12 months. What happens?","o":["Nothing until they reach 12 points","They get a free extra license","They must only write a letter","Driving is limited to business purposes only"],"h1":"Young drivers face limits sooner than adults.","h2":"A driver under 18 who gets 6 points within 12 months may drive only for business purposes, such as school or work, for one year.","p":"Right. Six points before 18 limits driving to business purposes only."},"es":{"q":"En Florida, un conductor menor de 18 acumula 6 puntos dentro de 12 meses. ¿Qué pasa?","o":["Nada hasta que llegue a 12 puntos","Recibe una licencia extra gratis","Solo tiene que escribir una carta","Solo puede manejar por motivos de negocio"],"h1":"Los conductores jóvenes tienen límites antes que los adultos.","h2":"Un conductor menor de 18 que acumula 6 puntos dentro de 12 meses solo puede manejar por motivos de negocio, como ir a la escuela o al trabajo, durante un año.","p":"Correcto. Seis puntos antes de los 18 limitan el manejo a motivos de negocio."},"ref":{"doc":"FL","page":29}},{"id":"licensing-019","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is the minimum Personal Injury Protection (PIP) insurance a car owner must carry?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"It is the same amount as the minimum property damage coverage.","h2":"A Florida car owner must carry at least $10,000 of Personal Injury Protection, which helps pay for your own injuries after a crash.","p":"Right. The PIP minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Protección contra Lesiones Personales (PIP) que debe tener el dueño de un carro?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Es la misma cantidad que la cobertura mínima de daños a la propiedad.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Protección contra Lesiones Personales, que ayuda a pagar sus propias lesiones después de un choque.","p":"Correcto. El mínimo de PIP es $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-020","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what is the minimum Property Damage Liability (PDL) insurance a car owner must carry?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"It is the same amount as the minimum PIP coverage.","h2":"A Florida car owner must carry at least $10,000 of Property Damage Liability, which pays for damage you cause to other people's property.","p":"Right. The PDL minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Responsabilidad por Daños a la Propiedad (PDL) que debe tener el dueño de un carro?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Es la misma cantidad que la cobertura mínima de PIP.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Responsabilidad por Daños a la Propiedad, que paga los daños que usted causa a la propiedad de otras personas.","p":"Correcto. El mínimo de PDL es $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-021","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what should you do with your proof of insurance?","o":["Keep it at home in a safe place","Keep it in the car and show it when an officer asks","Show it only when you renew your license","Mail it to the police every year"],"h1":"An officer may ask for it at a traffic stop or after a crash.","h2":"You must keep proof of insurance with you in the car and show it when a law enforcement officer asks for it.","p":"Right. Keep proof of insurance in the car and show it when asked."},"es":{"q":"En Florida, ¿qué debe hacer con su comprobante de seguro?","o":["Guardarlo en casa en un lugar seguro","Tenerlo en el carro y mostrarlo cuando un oficial lo pida","Mostrarlo solo cuando renueve la licencia","Enviarlo por correo a la policía cada año"],"h1":"Un oficial se lo puede pedir en una parada de tránsito o después de un choque.","h2":"Usted debe tener el comprobante de seguro en el carro y mostrarlo cuando un oficial de la ley se lo pida.","p":"Correcto. Tenga el comprobante de seguro en el carro y muéstrelo cuando se lo pidan."},"ref":{"doc":"FL","page":23}},{"id":"licensing-022","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you are in a crash and someone is hurt. What must you do?","o":["Leave and call your insurance later","Drive the injured person home","Wait until the next day to report it","Stay at the scene and call the police"],"h1":"When someone is injured, the law requires an official report right away.","h2":"When a crash injures someone, you must stay at the scene, call the police, and help the injured person get medical care.","p":"Right. If someone is hurt, stay and call the police."},"es":{"q":"En Florida, usted tiene un choque y alguien está herido. ¿Qué debe hacer?","o":["Irse y llamar a su seguro después","Llevar al herido a su casa","Esperar al día siguiente para reportarlo","Quedarse en el lugar y llamar a la policía"],"h1":"Cuando alguien está herido, la ley exige un reporte oficial enseguida.","h2":"Cuando un choque deja a alguien herido, usted debe quedarse en el lugar, llamar a la policía y ayudar a que el herido reciba atención médica.","p":"Correcto. Si alguien está herido, quédese y llame a la policía."},"ref":{"doc":"FL","page":77}},{"id":"licensing-023","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is true about leaving the scene of a crash where someone was hurt?","o":["It is a serious crime and can be a felony","It is allowed if you were not at fault","It is allowed if you are late for work","It is only a small parking fine"],"h1":"Think about how serious the law treats leaving a hurt person behind.","h2":"Leaving the scene of a crash where someone was hurt is a serious crime in Florida and can be a felony, with jail time and loss of your license.","p":"Right. Leaving a crash with injuries is a serious crime."},"es":{"q":"En Florida, ¿qué es cierto sobre irse del lugar de un choque donde alguien resultó herido?","o":["Es un delito grave y puede ser un delito mayor (felony)","Está permitido si usted no tuvo la culpa","Está permitido si va tarde al trabajo","Es solo una multa pequeña de estacionamiento"],"h1":"Piense en lo grave que la ley considera dejar atrás a una persona herida.","h2":"Irse del lugar de un choque donde alguien resultó herido es un delito grave en Florida y puede ser un delito mayor, con cárcel y pérdida de la licencia.","p":"Correcto. Irse de un choque con heridos es un delito grave."},"ref":{"doc":"FL","page":77}},{"id":"licensing-024","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you hit a parked car and no one is around. What must you do?","o":["Drive away because no one saw it","Wait one hour, then leave","Find the owner or leave a note with your name and address, and report it to police","Report it only if the damage is large"],"h1":"The owner needs a way to contact you.","h2":"If you hit an unattended car, you must find the owner or leave a note with your name and address in a safe place on the car, and report the crash to the police.","p":"Right. Leave your name and address, and tell the police."},"es":{"q":"En Florida, usted choca un carro estacionado y no hay nadie. ¿Qué debe hacer?","o":["Irse porque nadie lo vio","Esperar una hora y luego irse","Buscar al dueño o dejar una nota con su nombre y dirección, y reportarlo a la policía","Reportarlo solo si el daño es grande"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"Si choca un carro sin nadie adentro, debe buscar al dueño o dejar una nota con su nombre y dirección en un lugar seguro del carro, y reportar el choque a la policía.","p":"Correcto. Deje su nombre y dirección, y avise a la policía."},"ref":{"doc":"FL","page":77}},{"id":"licensing-025","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after a minor crash with no injuries, the cars can still be driven. What should you do?","o":["Leave the cars where they stopped","Move the cars out of the travel lanes","Drive home without talking to anyone","Stand in the road to direct traffic"],"h1":"Blocking traffic can cause a second crash.","h2":"If no one is hurt and the cars can be driven, move them out of the travel lanes to a safe place, then exchange information.","p":"Right. Move the cars out of traffic if no one is hurt."},"es":{"q":"En Florida, después de un choque leve sin heridos, los carros todavía pueden andar. ¿Qué debe hacer?","o":["Dejar los carros donde quedaron","Sacar los carros de los carriles de tránsito","Irse a casa sin hablar con nadie","Pararse en la calle para dirigir el tráfico"],"h1":"Bloquear el tráfico puede causar un segundo choque.","h2":"Si nadie está herido y los carros pueden andar, sáquelos de los carriles de tránsito a un lugar seguro y después intercambie información.","p":"Correcto. Si nadie está herido, saque los carros del tráfico."},"ref":{"doc":"FL","page":77}},{"id":"licensing-026","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, after a crash, what information must you give to the other driver?","o":["Only your phone number","Your bank account number","Nothing, unless they are hurt","Your name, address, and vehicle registration, and show your license"],"h1":"The other driver needs to know who you are and which car was involved.","h2":"After a crash, you must give your name, address, and vehicle registration number, and show your driver license to the other driver.","p":"Right. Share your name, address, registration, and license."},"es":{"q":"En Florida, después de un choque, ¿qué información debe darle al otro conductor?","o":["Solo su número de teléfono","Su número de cuenta bancaria","Nada, a menos que esté herido","Su nombre, dirección y registro del vehículo, y mostrar su licencia"],"h1":"El otro conductor necesita saber quién es usted y qué carro estuvo involucrado.","h2":"Después de un choque, usted debe dar su nombre, dirección y número de registro del vehículo, y mostrar su licencia de conducir al otro conductor.","p":"Correcto. Dé su nombre, dirección, registro y licencia."},"ref":{"doc":"FL","page":77}},{"id":"licensing-027","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you had a crash, and the law did not require a police report. What must you do?","o":["Send a written crash report to the state within 10 days","Do nothing at all","Report it only when you renew your license","Wait a year, then report it"],"h1":"When no officer writes a report, the job falls to you, and there is a short deadline.","h2":"If no police report was required for your crash, you must send your own written crash report to the state within 10 days.","p":"Right. Send your own crash report within 10 days."},"es":{"q":"En Florida, usted tuvo un choque y la ley no exigía un reporte de la policía. ¿Qué debe hacer?","o":["Enviar un reporte escrito del choque al estado dentro de 10 días","No hacer nada","Reportarlo solo cuando renueve la licencia","Esperar un año y luego reportarlo"],"h1":"Cuando ningún oficial hace el reporte, la tarea es suya, y el plazo es corto.","h2":"Si su choque no necesitaba un reporte de la policía, usted debe enviar su propio reporte escrito del choque al estado dentro de 10 días.","p":"Correcto. Envíe su propio reporte del choque dentro de 10 días."},"ref":{"doc":"FL","page":77}},{"id":"licensing-028","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what does the implied consent law mean?","o":["You must agree to let police search your phone","You agree to pay any ticket without going to court","By driving, you agree to be tested for alcohol or drugs if lawfully arrested","Your passengers agree to be tested too"],"h1":"You gave this agreement when you accepted your driver license.","h2":"Implied consent means that by driving in Florida, you agree to take a breath, blood, or urine test if you are lawfully arrested for impaired driving.","p":"Right. Driving means you agree to alcohol and drug testing."},"es":{"q":"En Florida, ¿qué significa la ley de consentimiento implícito?","o":["Debe permitir que la policía revise su teléfono","Acepta pagar cualquier multa sin ir a la corte","Al manejar, usted acepta hacerse pruebas de alcohol o drogas si lo arrestan legalmente","Sus pasajeros también aceptan hacerse pruebas"],"h1":"Usted dio este acuerdo cuando aceptó su licencia de conducir.","h2":"Consentimiento implícito significa que, al manejar en Florida, usted acepta hacerse una prueba de aliento, sangre u orina si lo arrestan legalmente por manejar bajo los efectos.","p":"Correcto. Manejar significa aceptar las pruebas de alcohol y drogas."},"ref":{"doc":"FL","page":25}},{"id":"licensing-029","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens the first time you refuse a lawful breath, blood, or urine test?","o":["Nothing, refusing is your right","Your license is suspended for 1 year","Your license is suspended for 10 days","You get a warning only"],"h1":"Refusing has a cost, even if you were not proven drunk.","h2":"If you refuse a lawful test for the first time, your license is suspended for 1 year.","p":"Right. A first refusal means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa la primera vez que se niega a una prueba legal de aliento, sangre u orina?","o":["Nada, negarse es su derecho","Le suspenden la licencia por 1 año","Le suspenden la licencia por 10 días","Solo recibe una advertencia"],"h1":"Negarse tiene un costo, aunque no se pruebe que estaba borracho.","h2":"Si se niega por primera vez a una prueba legal, le suspenden la licencia por 1 año.","p":"Correcto. La primera negativa significa 1 año de suspensión."},"ref":{"doc":"FL","page":25}},{"id":"licensing-030","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you already refused a test once before. What happens if you refuse again?","o":["A 30-day suspension only","Nothing more than the first time","A small fine only","An 18-month suspension, and the refusal is a crime"],"h1":"A second refusal is treated more harshly than the first.","h2":"If your license was suspended before for refusing, a second refusal brings an 18-month suspension, and the refusal itself is a misdemeanor crime.","p":"Right. A second refusal means 18 months and a criminal charge."},"es":{"q":"En Florida, usted ya se negó a una prueba antes. ¿Qué pasa si se niega otra vez?","o":["Solo una suspensión de 30 días","Nada más que la primera vez","Solo una multa pequeña","Una suspensión de 18 meses, y negarse es un delito"],"h1":"La segunda negativa se castiga más fuerte que la primera.","h2":"Si antes le suspendieron la licencia por negarse, una segunda negativa trae una suspensión de 18 meses, y negarse es en sí un delito menor.","p":"Correcto. La segunda negativa significa 18 meses y un cargo criminal."},"ref":{"doc":"FL","page":26}},{"id":"licensing-031","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.08 or higher","0.02 or higher","0.04 or higher","0.15 or higher"],"h1":"This is the standard limit for adult drivers of regular cars.","h2":"A driver age 21 or older is driving under the influence with a blood alcohol level of 0.08 or higher, and can also be charged with less if impaired.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Florida, ¿a qué nivel de alcohol en la sangre se considera legalmente borracho a un conductor de 21 años o más?","o":["0.08 o más","0.02 o más","0.04 o más","0.15 o más"],"h1":"Es el límite normal para adultos que manejan carros comunes.","h2":"Un conductor de 21 años o más maneja bajo los efectos del alcohol con un nivel de 0.08 o más, y también puede recibir un cargo con menos si está afectado.","p":"Correcto. Para adultos, el límite es 0.08."},"ref":{"doc":"FL","page":25}},{"id":"licensing-032","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a driver under 21 can lose their license at what blood alcohol level?","o":["0.08 or higher","0.10 or higher","0.02 or higher","0.05 or higher"],"h1":"Drivers under 21 may not legally drink, so the limit is very low.","h2":"A driver under 21 with a blood alcohol level of 0.02 or higher will have their license suspended, because people under 21 may not drink at all.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Florida, ¿con qué nivel de alcohol en la sangre puede perder la licencia un conductor menor de 21?","o":["0.08 o más","0.10 o más","0.02 o más","0.05 o más"],"h1":"Los menores de 21 no pueden tomar alcohol legalmente, así que el límite es muy bajo.","h2":"A un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia, porque los menores de 21 no pueden tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02."},"ref":{"doc":"FL","page":26}},{"id":"licensing-033","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the blood alcohol limit for someone driving a commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Commercial drivers have a stricter limit than regular adult drivers.","h2":"A person driving a commercial motor vehicle is over the limit at a blood alcohol level of 0.04, which is half the limit for regular adult drivers.","p":"Right. For commercial drivers, the limit is 0.04."},"es":{"q":"En Florida, ¿cuál es el límite de alcohol en la sangre para quien maneja un vehículo comercial?","o":["0.08","0.04","0.10","0.02"],"h1":"Los conductores comerciales tienen un límite más estricto que los adultos comunes.","h2":"Una persona que maneja un vehículo motorizado comercial pasa el límite con un nivel de alcohol de 0.04, que es la mitad del límite para adultos comunes.","p":"Correcto. Para conductores comerciales, el límite es 0.04."},"ref":{"doc":"FL","page":null}},{"id":"licensing-034","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 21 is found with a blood alcohol level of 0.02. What happens to the license the first time?","o":["It is suspended for 5 years","It is not affected","It is suspended for 1 week","It is suspended for 6 months"],"h1":"It is a real suspension, longer than a few weeks but shorter than a year.","h2":"For a first offense, a driver under 21 with a blood alcohol level of 0.02 or higher has the license suspended for 6 months.","p":"Right. The first time, the license is suspended for 6 months."},"es":{"q":"En Florida, un conductor menor de 21 tiene un nivel de alcohol de 0.02. ¿Qué pasa con su licencia la primera vez?","o":["Se la suspenden por 5 años","No le pasa nada","Se la suspenden por 1 semana","Se la suspenden por 6 meses"],"h1":"Es una suspensión real, más larga que unas semanas pero más corta que un año.","h2":"La primera vez, a un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia por 6 meses.","p":"Correcto. La primera vez, la licencia se suspende por 6 meses."},"ref":{"doc":"FL","page":26}},{"id":"licensing-035","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who may have an open container of alcohol in a moving car?","o":["No one, not the driver and not the passengers","Only the passengers","Only the driver","Anyone over 21"],"h1":"The rule covers everyone inside a regular car.","h2":"In a regular car, neither the driver nor the passengers may have an open container of alcohol while the car is on the road.","p":"Right. No one in the car may have an open container."},"es":{"q":"En Florida, ¿quién puede tener un envase abierto de alcohol en un carro en movimiento?","o":["Nadie, ni el conductor ni los pasajeros","Solo los pasajeros","Solo el conductor","Cualquier persona mayor de 21"],"h1":"La regla aplica a todos los que van en un carro común.","h2":"En un carro común, ni el conductor ni los pasajeros pueden tener un envase abierto de alcohol mientras el carro está en la calle.","p":"Correcto. Nadie en el carro puede tener un envase abierto."},"ref":{"doc":"FL","page":null}},{"id":"licensing-036","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, who must wear a seat belt?","o":["Only the driver","Only children under 5","The driver, front-seat passengers, and all passengers under 18","Only people on the highway"],"h1":"Think about the front of the car and about young people anywhere in the car.","h2":"The driver and all front-seat passengers must wear seat belts, and every passenger under 18 must be buckled in any seat.","p":"Right. Driver, front seat, and everyone under 18 must buckle up."},"es":{"q":"En Florida, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los niños menores de 5","El conductor, los pasajeros de adelante y todos los pasajeros menores de 18","Solo las personas en la autopista"],"h1":"Piense en la parte de adelante del carro y en los jóvenes en cualquier asiento.","h2":"El conductor y todos los pasajeros del asiento de adelante deben usar el cinturón, y todo pasajero menor de 18 debe ir abrochado en cualquier asiento.","p":"Correcto. El conductor, los de adelante y todos los menores de 18 deben abrocharse."},"ref":{"doc":"FL","page":27}},{"id":"licensing-037","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how must a child age 3 or younger ride in a car?","o":["On an adult's lap","In a separate child carrier or a car's built-in child seat","With only a regular seat belt","In any seat without a belt"],"h1":"The youngest children need the most protection.","h2":"A child age 3 or younger must ride in a separate crash-tested child carrier or in a child seat built into the car.","p":"Right. Children 3 and under need a child carrier or built-in seat."},"es":{"q":"En Florida, ¿cómo debe viajar en el carro un niño de 3 años o menos?","o":["En las piernas de un adulto","En un asiento para niños aparte o en un asiento para niños integrado al carro","Solo con un cinturón de seguridad normal","En cualquier asiento sin cinturón"],"h1":"Los niños más pequeños necesitan la mayor protección.","h2":"Un niño de 3 años o menos debe viajar en un asiento para niños aparte, probado contra choques, o en un asiento para niños integrado al carro.","p":"Correcto. Los niños de 3 años o menos necesitan un asiento para niños."},"ref":{"doc":"FL","page":28}},{"id":"licensing-038","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what may a child age 4 or 5 use in a car?","o":["Nothing, they may ride free","Only an adult's lap","Only the front seat with no belt","A child carrier, a built-in child seat, or a booster seat"],"h1":"Children this age have one more choice than younger children.","h2":"A child age 4 or 5 must use a separate child carrier, a built-in child seat, or a booster seat.","p":"Right. Ages 4 and 5 may use a car seat or a booster seat."},"es":{"q":"En Florida, ¿qué puede usar en el carro un niño de 4 o 5 años?","o":["Nada, puede ir suelto","Solo las piernas de un adulto","Solo el asiento de adelante sin cinturón","Un asiento para niños, un asiento integrado o un asiento elevador (booster)"],"h1":"Los niños de esta edad tienen una opción más que los niños más pequeños.","h2":"Un niño de 4 o 5 años debe usar un asiento para niños aparte, un asiento para niños integrado al carro o un asiento elevador.","p":"Correcto. A los 4 y 5 años se usa un asiento para niños o un asiento elevador."},"ref":{"doc":"FL","page":28}},{"id":"licensing-039","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, can a police officer stop you just for texting while driving?","o":["Yes, texting while driving is a primary offense","No, only if you also break another law","No, texting while driving is legal","Only on interstate highways"],"h1":"Think about whether the officer needs a second reason to stop you.","h2":"Texting while driving is a primary offense in Florida, so an officer can stop you for texting alone.","p":"Right. You can be stopped just for texting."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo por enviar mensajes de texto mientras maneja?","o":["Sí, enviar textos mientras maneja es una infracción primaria","No, solo si también viola otra ley","No, enviar textos mientras maneja es legal","Solo en las autopistas interestatales"],"h1":"Piense si el oficial necesita una segunda razón para detenerlo.","h2":"Enviar textos mientras maneja es una infracción primaria en Florida, así que un oficial puede detenerlo solo por eso.","p":"Correcto. Lo pueden detener solo por enviar textos."},"ref":{"doc":"FL","page":null}},{"id":"licensing-040","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, how may you use a phone while driving in a school zone or an active work zone?","o":["Holding it in your hand","Only to read texts","Only hands-free","Any way you want"],"h1":"In these zones, your hands must stay off the phone.","h2":"In a school zone or an active work zone, you may not hold a phone in your hand, so you may use it only in hands-free mode.","p":"Right. In school and work zones, phones must be hands-free."},"es":{"q":"En Florida, ¿cómo puede usar el teléfono mientras maneja en una zona escolar o en una zona de construcción activa?","o":["Sosteniéndolo en la mano","Solo para leer mensajes","Solo con manos libres","Como usted quiera"],"h1":"En estas zonas, sus manos no deben tocar el teléfono.","h2":"En una zona escolar o en una zona de construcción activa, no puede tener el teléfono en la mano, así que solo puede usarlo con manos libres.","p":"Correcto. En zonas escolares y de construcción, el teléfono debe ser de manos libres."},"ref":{"doc":"FL","page":34}},{"id":"licensing-041","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, you move to a new home. How soon must you update the address on your license?","o":["Within 1 year","Within 30 days","Only at your next renewal","Within 6 months"],"h1":"There is a deadline of about one month.","h2":"When you move, you must update the address on your driver license within 30 days.","p":"Right. Update your address within 30 days."},"es":{"q":"En Florida, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar la dirección de su licencia?","o":["Dentro de 1 año","Dentro de 30 días","Solo en la próxima renovación","Dentro de 6 meses"],"h1":"Hay un plazo de más o menos un mes.","h2":"Cuando se muda, usted debe actualizar la dirección de su licencia de conducir dentro de 30 días.","p":"Correcto. Actualice su dirección dentro de 30 días."},"ref":{"doc":"FL","page":12}},{"id":"licensing-042","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, how long is a Class E license valid?","o":["2 years","4 years","20 years","6 to 8 years"],"h1":"It lasts many years, but not for life.","h2":"A Florida Class E license is valid for six to eight years, and then you must renew it.","p":"Right. A Class E license lasts six to eight years."},"es":{"q":"En Florida, ¿por cuánto tiempo es válida la licencia Clase E?","o":["2 años","4 años","20 años","De 6 a 8 años"],"h1":"Dura muchos años, pero no toda la vida.","h2":"La licencia Clase E de Florida es válida de seis a ocho años, y después usted debe renovarla.","p":"Correcto. La licencia Clase E dura de seis a ocho años."},"ref":{"doc":"FL","page":13}},{"id":"licensing-043","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what must a driver age 80 or older pass when renewing a license?","o":["A vision test","A new road test every time","A written essay","A physical fitness test"],"h1":"Think about the sense you use most to drive safely.","h2":"Drivers age 80 or older must pass a vision test each time they renew their license, because good eyesight is needed to drive safely.","p":"Right. Drivers 80 and older must pass a vision test to renew."},"es":{"q":"En Florida, ¿qué debe aprobar un conductor de 80 años o más al renovar la licencia?","o":["Un examen de la vista","Un nuevo examen de manejo cada vez","Un ensayo escrito","Una prueba de condición física"],"h1":"Piense en el sentido que más usa para manejar con seguridad.","h2":"Los conductores de 80 años o más deben aprobar un examen de la vista cada vez que renuevan la licencia, porque se necesita buena vista para manejar con seguridad.","p":"Correcto. Los conductores de 80 años o más deben aprobar el examen de la vista para renovar."},"ref":{"doc":"FL","page":14}},{"id":"licensing-044","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you just moved here and became a resident. How soon must you get a Florida driver license?","o":["Within 1 year","Only when your old license expires","Within 30 days","Within 90 days"],"h1":"New residents have about one month.","h2":"A new Florida resident must get a Florida driver license within 30 days of becoming a resident.","p":"Right. New residents must get a Florida license within 30 days."},"es":{"q":"En Florida, usted se acaba de mudar y ya es residente. ¿En cuánto tiempo debe obtener una licencia de conducir de Florida?","o":["Dentro de 1 año","Solo cuando se venza su licencia anterior","Dentro de 30 días","Dentro de 90 días"],"h1":"Los residentes nuevos tienen más o menos un mes.","h2":"Un nuevo residente de Florida debe obtener una licencia de conducir de Florida dentro de 30 días después de hacerse residente.","p":"Correcto. Los residentes nuevos deben obtener la licencia de Florida dentro de 30 días."},"ref":{"doc":"FL","page":3}},{"id":"licensing-045","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what kind of license do most people need to drive a regular car?","o":["A Class A license","A Class E license","A Class B license","A motorcycle endorsement"],"h1":"Classes A and B are for large commercial vehicles.","h2":"Most people need a Class E license to drive a regular car, because Classes A, B, and C are for commercial vehicles.","p":"Right. A regular car needs a Class E license."},"es":{"q":"En Florida, ¿qué tipo de licencia necesita la mayoría de las personas para manejar un carro común?","o":["Una licencia Clase A","Una licencia Clase E","Una licencia Clase B","Un endoso de motocicleta"],"h1":"Las Clases A y B son para vehículos comerciales grandes.","h2":"La mayoría de las personas necesita una licencia Clase E para manejar un carro común, porque las Clases A, B y C son para vehículos comerciales.","p":"Correcto. Un carro común requiere una licencia Clase E."},"ref":{"doc":"FL","page":4}},{"id":"right-of-way-001","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, at a four-way stop, which car goes first?","o":["The car that came to a full stop first","The largest vehicle at the stop","The car on the far left","The car that is going straight"],"h1":"Think about the order in which the cars arrived.","h2":"At a four-way stop, the driver who stopped first goes first, and the others follow in the order they arrived.","p":"Right. At a four-way stop, the first car to stop goes first."},"es":{"q":"En Florida, en un pare de cuatro vías, ¿qué carro sigue primero?","o":["El carro que hizo el alto total primero","El vehículo más grande en el pare","El carro que está más a la izquierda","El carro que va derecho"],"h1":"Piense en el orden en que llegaron los carros.","h2":"En un pare de cuatro vías, el conductor que paró primero sigue primero, y los demás siguen en el orden en que llegaron.","p":"Correcto. En un pare de cuatro vías, el primer carro en parar sigue primero."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-002","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, two cars stop at a four-way stop at the same time. Who goes first?","o":["The driver who honks first","The driver on the left","The driver on the right","The driver who is in a hurry"],"h1":"Look at where the other car is, to your left or to your right.","h2":"When two cars stop at the same time, the driver on the left lets the driver on the right go first.","p":"Right. When you arrive together, the car on the right goes first."},"es":{"q":"En Florida, dos carros paran al mismo tiempo en un pare de cuatro vías. ¿Quién sigue primero?","o":["El conductor que toca la bocina primero","El conductor de la izquierda","El conductor de la derecha","El conductor que tiene prisa"],"h1":"Fíjese dónde está el otro carro, a su izquierda o a su derecha.","h2":"Cuando dos carros paran al mismo tiempo, el conductor de la izquierda deja pasar primero al conductor de la derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-003","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you reach an intersection with no signs or lights. A car is already crossing it. What do you do?","o":["Go first, because you are on the wider road","Let the car that is already in the intersection go first","Honk and go at the same time","Speed up to cross before it"],"h1":"Think about who is already using the space.","h2":"At an intersection with no signs or lights, you must yield to a vehicle that is already in the intersection.","p":"Right. Yield to the car that is already in the intersection."},"es":{"q":"En Florida, usted llega a una intersección sin señales ni semáforos. Un carro ya la está cruzando. ¿Qué hace?","o":["Sigue primero, porque usted va por la calle más ancha","Deja pasar primero al carro que ya está en la intersección","Toca la bocina y sigue al mismo tiempo","Acelera para cruzar antes que él"],"h1":"Piense en quién ya está usando ese espacio.","h2":"En una intersección sin señales ni semáforos, usted debe ceder el paso al vehículo que ya está dentro de la intersección.","p":"Correcto. Ceda el paso al carro que ya está en la intersección."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-004","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you and another car reach an intersection with no signs at the same time. The other car is on your right. Who goes first?","o":["You go first, because you are on the left","The faster car goes first","Both cars go at the same time","The car on your right goes first"],"h1":"The rule is the same as when two cars stop together at a stop sign.","h2":"When two cars reach an open intersection at the same time, the driver on the left yields, so the car on your right goes first.","p":"Right. At the same time, the car on the right goes first."},"es":{"q":"En Florida, usted y otro carro llegan al mismo tiempo a una intersección sin señales. El otro carro está a su derecha. ¿Quién sigue primero?","o":["Usted sigue primero, porque está a la izquierda","Sigue primero el carro más rápido","Los dos carros siguen al mismo tiempo","Sigue primero el carro que está a su derecha"],"h1":"La regla es igual que cuando dos carros paran juntos en un pare.","h2":"Cuando dos carros llegan al mismo tiempo a una intersección sin control, cede el paso el conductor de la izquierda, así que sigue primero el carro de su derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-006","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you want to turn left at a green light. A car is coming toward you. What do you do?","o":["Turn quickly before it gets close","Turn, because a green light gives you the right of way","Wait and let the oncoming car pass first","Flash your lights and turn"],"h1":"A green light lets you go, but it does not clear the road in front of you.","h2":"When you turn left, you must yield to oncoming traffic, so you wait until the car passes and the way is clear.","p":"Right. When turning left, let oncoming traffic go first."},"es":{"q":"En Florida, usted quiere doblar a la izquierda con luz verde. Viene un carro de frente. ¿Qué hace?","o":["Dobla rápido antes de que se acerque","Dobla, porque la luz verde le da el derecho de paso","Espera y deja pasar primero al carro que viene de frente","Hace cambio de luces y dobla"],"h1":"La luz verde le permite seguir, pero no despeja la calle delante de usted.","h2":"Cuando usted dobla a la izquierda, debe ceder el paso al tráfico que viene de frente, así que espera hasta que el carro pase y el camino esté libre.","p":"Correcto. Al doblar a la izquierda, deje pasar primero al tráfico de frente."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-007","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you are pulling out of a driveway onto a street. Who must you yield to?","o":["Only to large trucks","No one, if you use your signal","Only to cars on your left","All cars on the street and all people walking"],"h1":"You are joining a road that others are already using.","h2":"When you enter a street from a driveway or alley, you must yield to every vehicle on the street and to every pedestrian.","p":"Right. Coming out of a driveway, yield to cars and people walking."},"es":{"q":"En Florida, usted sale de una entrada de casa hacia la calle. ¿A quién debe ceder el paso?","o":["Solo a los camiones grandes","A nadie, si usa la direccional","Solo a los carros de su izquierda","A todos los carros de la calle y a todas las personas que caminan"],"h1":"Usted entra a una calle que otros ya están usando.","h2":"Cuando usted entra a una calle desde una entrada de casa o un callejón, debe ceder el paso a todos los vehículos de la calle y a todos los peatones.","p":"Correcto. Al salir de una entrada de casa, ceda el paso a carros y peatones."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-008","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you drive out of an alley. There is a sidewalk before the street. Where must you stop?","o":["Before you cross the sidewalk","In the middle of the sidewalk","At the edge of the street, past the sidewalk","You do not need to stop"],"h1":"Think about people who may be walking on the sidewalk.","h2":"When you come out of an alley or driveway, you must stop before the sidewalk, so you do not hit someone walking there.","p":"Right. Stop before the sidewalk when you leave an alley or driveway."},"es":{"q":"En Florida, usted sale de un callejón. Hay una acera antes de la calle. ¿Dónde debe parar?","o":["Antes de cruzar la acera","En medio de la acera","En el borde de la calle, después de la acera","No necesita parar"],"h1":"Piense en las personas que pueden ir caminando por la acera.","h2":"Cuando usted sale de un callejón o de una entrada de casa, debe parar antes de la acera, para no golpear a alguien que camina por ahí.","p":"Correcto. Pare antes de la acera al salir de un callejón o entrada."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-009","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a person is crossing at a corner with no painted crosswalk lines. Must you yield?","o":["No, only painted crosswalks count","Yes, the corner of an intersection is a crosswalk even without lines","Only if the person is a child","Only if a police officer is there"],"h1":"A crosswalk does not always have paint.","h2":"Every corner of an intersection has a crosswalk even when no lines are painted, so you must yield to the person crossing.","p":"Right. Yield to people crossing at a corner, with or without lines."},"es":{"q":"En Florida, una persona cruza en una esquina sin líneas pintadas de cruce peatonal. ¿Debe usted ceder el paso?","o":["No, solo cuentan los cruces pintados","Sí, la esquina de una intersección es un cruce peatonal aunque no tenga líneas","Solo si la persona es un niño","Solo si hay un policía"],"h1":"Un cruce peatonal no siempre tiene pintura.","h2":"Cada esquina de una intersección tiene un cruce peatonal aunque no tenga líneas pintadas, así que usted debe ceder el paso a la persona que cruza.","p":"Correcto. Ceda el paso a quien cruza en la esquina, con o sin líneas."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-010","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you turn right on a green light. People are crossing the street you are turning into. What do you do?","o":["Drive slowly between them","Honk so they move faster","Stop and let them finish crossing","Turn, because your light is green"],"h1":"Your path crosses their path.","h2":"When you turn, you must yield to people walking in the crosswalk, so you stop and wait until they are out of your way.","p":"Right. When you turn, let people in the crosswalk cross first."},"es":{"q":"En Florida, usted dobla a la derecha con luz verde. Hay personas cruzando la calle a la que usted va a entrar. ¿Qué hace?","o":["Pasa despacio entre ellas","Toca la bocina para que caminen más rápido","Para y las deja terminar de cruzar","Dobla, porque su luz está en verde"],"h1":"Su camino se cruza con el camino de ellas.","h2":"Cuando usted dobla, debe ceder el paso a las personas que caminan en el cruce peatonal, así que para y espera hasta que salgan de su camino.","p":"Correcto. Al doblar, deje cruzar primero a las personas en el cruce peatonal."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-011","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a person with a white cane or a guide dog is crossing the street. What must you do?","o":["Honk to let the person know you are there","Drive around the person carefully","Go if your light is green","Stop and let the person cross"],"h1":"A white cane or guide dog tells you the person may not be able to see you.","h2":"A person who is blind and uses a white cane or a guide dog always has the right of way, so you must stop and let them cross.","p":"Right. Always stop for a person with a white cane or guide dog."},"es":{"q":"En Florida, una persona con bastón blanco o con perro guía está cruzando la calle. ¿Qué debe hacer usted?","o":["Tocar la bocina para avisar que usted está ahí","Pasar alrededor de la persona con cuidado","Seguir si su luz está en verde","Parar y dejar que la persona cruce"],"h1":"Un bastón blanco o un perro guía le indican que la persona tal vez no puede verlo.","h2":"Una persona ciega que usa bastón blanco o perro guía siempre tiene el derecho de paso, así que usted debe parar y dejarla cruzar.","p":"Correcto. Siempre pare por una persona con bastón blanco o perro guía."},"ref":{"doc":"FL","page":88}},{"id":"right-of-way-012","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are about to enter a roundabout. Who has the right of way?","o":["Traffic already moving inside the roundabout","You, because you are entering","The car on your right that is also entering","The driver who honks first"],"h1":"Think about who is already driving in the circle.","h2":"When you enter a roundabout, you must yield to traffic that is already in the circle, then enter when there is a safe gap.","p":"Right. Yield to cars already in the roundabout."},"es":{"q":"En Florida, usted va a entrar a una rotonda. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va dentro de la rotonda","Usted, porque está entrando","El carro de su derecha que también está entrando","El conductor que toca la bocina primero"],"h1":"Piense en quién ya va manejando dentro del círculo.","h2":"Cuando usted entra a una rotonda, debe ceder el paso al tráfico que ya está en el círculo, y luego entrar cuando haya un espacio seguro.","p":"Correcto. Ceda el paso a los carros que ya están en la rotonda."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-013","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"Which way do cars travel in a roundabout in the United States?","o":["Clockwise, to the left","Counterclockwise, to the right","Either way the driver picks","Straight across the middle"],"h1":"In the United States, you drive on the right side of the road.","h2":"In a roundabout in the United States, you enter to the right and travel counterclockwise around the center.","p":"Right. In a roundabout, go to the right, counterclockwise."},"es":{"q":"¿Hacia qué lado van los carros en una rotonda en los Estados Unidos?","o":["En el sentido del reloj, hacia la izquierda","En contra del reloj, hacia la derecha","Hacia el lado que el conductor escoja","Derecho por el centro"],"h1":"En los Estados Unidos se maneja por el lado derecho de la calle.","h2":"En una rotonda en los Estados Unidos, usted entra hacia la derecha y da la vuelta en contra del sentido del reloj alrededor del centro.","p":"Correcto. En una rotonda, vaya hacia la derecha, en contra del reloj."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-014","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, an ambulance with a siren and flashing lights is coming behind you. What do you do?","o":["Speed up to stay ahead of it","Stop right where you are, in your lane","Pull to the nearest edge of the road and stop","Move to the left lane and keep driving"],"h1":"The ambulance needs a clear path. Think about where you can get out of its way.","h2":"When an emergency vehicle comes with a siren and flashing lights, you pull to the nearest edge of the road and stop until it passes.","p":"Right. Pull to the nearest edge and stop for emergency vehicles."},"es":{"q":"En Florida, una ambulancia con sirena y luces intermitentes viene detrás de usted. ¿Qué hace?","o":["Acelera para mantenerse delante","Para donde está, en su carril","Se orilla al borde más cercano de la calle y para","Se pasa al carril izquierdo y sigue manejando"],"h1":"La ambulancia necesita el camino libre. Piense dónde puede quitarse de su camino.","h2":"Cuando viene un vehículo de emergencia con sirena y luces intermitentes, usted se orilla al borde más cercano de la calle y para hasta que pase.","p":"Correcto. Oríllese al borde más cercano y pare para los vehículos de emergencia."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-015","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are in the middle of an intersection when you hear a fire truck siren behind you. What do you do?","o":["Drive through the intersection, then pull to the nearest edge and stop","Stop in the middle of the intersection","Back up out of the intersection","Turn left right away"],"h1":"Stopping inside the intersection can block the fire truck.","h2":"If you are already in an intersection, you keep going through it and then pull to the nearest edge and stop, so you do not block the emergency vehicle.","p":"Right. Clear the intersection first, then pull over and stop."},"es":{"q":"En Florida, usted está en medio de una intersección cuando oye la sirena de un camión de bomberos detrás. ¿Qué hace?","o":["Cruza la intersección y luego se orilla al borde más cercano y para","Para en medio de la intersección","Da reversa para salir de la intersección","Dobla a la izquierda de inmediato"],"h1":"Parar dentro de la intersección puede bloquear al camión de bomberos.","h2":"Si usted ya está en una intersección, sigue hasta cruzarla y luego se orilla al borde más cercano y para, para no bloquear al vehículo de emergencia.","p":"Correcto. Primero salga de la intersección, luego oríllese y pare."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-016","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a funeral procession is passing through an intersection. What should you do?","o":["Drive between the cars when there is a gap","Join the end of the line","Honk so they move faster","Yield and wait until the whole procession passes"],"h1":"The cars in the procession are traveling together as one group.","h2":"You must yield to a funeral procession and must not cut through it or join it, so you wait until all of it has passed.","p":"Right. Yield to a funeral procession and let it pass."},"es":{"q":"En Florida, un cortejo fúnebre está pasando por una intersección. ¿Qué debe hacer?","o":["Pasar entre los carros cuando haya un espacio","Unirse al final de la fila","Tocar la bocina para que avancen más rápido","Ceder el paso y esperar hasta que pase todo el cortejo"],"h1":"Los carros del cortejo viajan juntos como un solo grupo.","h2":"Usted debe ceder el paso a un cortejo fúnebre y no debe cruzarlo ni unirse a él, así que espera hasta que pase completo.","p":"Correcto. Ceda el paso al cortejo fúnebre y déjelo pasar."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-017","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a road with two lanes going your way. What must you do?","o":["Keep your speed and stay in your lane","Move out of the lane closest to the police car if it is safe","Stop next to the police car","Honk as you pass"],"h1":"Florida's Move Over law asks you to give stopped workers more space.","h2":"Under Florida's Move Over law, you must leave the lane closest to the stopped emergency vehicle when it is safe to change lanes.","p":"Right. Move over a lane for a stopped emergency vehicle."},"es":{"q":"En Florida, una patrulla de policía está parada en el acotamiento con las luces intermitentes. Usted va por una calle con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y seguir en su carril","Salir del carril más cercano a la patrulla si es seguro","Parar al lado de la patrulla","Tocar la bocina al pasar"],"h1":"La ley Move Over de Florida le pide dar más espacio a quienes están parados trabajando.","h2":"Según la ley Move Over de Florida, usted debe salir del carril más cercano al vehículo de emergencia parado cuando sea seguro cambiar de carril.","p":"Correcto. Cámbiese de carril para un vehículo de emergencia parado."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-018","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you cannot safely move over for a stopped emergency vehicle. The speed limit is 55 mph. What must you do?","o":["Keep driving at 55 mph","Stop in your lane","Slow to 20 mph below the limit, so 35 mph","Speed up to pass it quickly"],"h1":"If you cannot move over, the law asks for a big cut in speed.","h2":"When you cannot move over, Florida law says you must slow to 20 mph below the posted speed limit, so on a 55 mph road you slow to 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril con seguridad para un vehículo de emergencia parado. El límite de velocidad es 55 mph. ¿Qué debe hacer?","o":["Seguir manejando a 55 mph","Parar en su carril","Bajar a 20 mph menos que el límite, o sea 35 mph","Acelerar para pasarlo rápido"],"h1":"Si no puede cambiarse de carril, la ley le pide bajar mucho la velocidad.","h2":"Cuando usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 20 mph menos que el límite marcado, así que en una calle de 55 mph baja a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph del límite."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-019","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, the speed limit is 20 mph. A tow truck is stopped with its lights flashing, and you cannot move over. How fast may you pass it?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Twenty below the limit would be zero, so the law gives a special number.","h2":"When the speed limit is 20 mph or less and you cannot move over, Florida law says you must slow to 5 mph.","p":"Right. On a road of 20 mph or less, slow to 5 mph."},"es":{"q":"En Florida, el límite de velocidad es 20 mph. Una grúa está parada con las luces intermitentes y usted no puede cambiarse de carril. ¿A qué velocidad puede pasarla?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Veinte menos que el límite sería cero, así que la ley da un número especial.","h2":"Cuando el límite es 20 mph o menos y usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 5 mph.","p":"Correcto. En una calle de 20 mph o menos, baje a 5 mph."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-020","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, which of these stopped vehicles is covered by the Move Over law?","o":["A parked car with no lights on","A city bus at a bus stop","A delivery van at a store","A garbage truck with its warning lights flashing"],"h1":"The law covers workers on the road who show flashing warning lights.","h2":"Florida's Move Over law covers sanitation trucks, utility trucks, tow trucks, and road crews when they are stopped with warning lights flashing, so you must move over or slow down.","p":"Right. Move over for a stopped garbage truck with flashing lights."},"es":{"q":"En Florida, ¿cuál de estos vehículos parados está cubierto por la ley Move Over?","o":["Un carro estacionado sin luces encendidas","Un autobús de la ciudad en una parada","Una camioneta de reparto frente a una tienda","Un camión de basura con las luces de advertencia intermitentes"],"h1":"La ley cubre a trabajadores en la vía que muestran luces de advertencia intermitentes.","h2":"La ley Move Over de Florida cubre camiones de basura, de servicios públicos, grúas y equipos de carretera cuando están parados con luces de advertencia intermitentes, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril por un camión de basura parado con luces intermitentes."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-021","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a car is stopped on the shoulder with its hazard lights flashing. Does the Move Over law apply?","o":["No, it is only for police and ambulances","Yes, move over or slow down as you would for an emergency vehicle","Only at night","Only on toll roads"],"h1":"Florida widened the Move Over law to protect more people stopped by the road.","h2":"Florida's Move Over law also covers a disabled vehicle that is stopped and showing hazard lights or other warning signs, so you must move over or slow down.","p":"Right. Move over or slow down for a stopped car with hazard lights."},"es":{"q":"En Florida, un carro está parado en el acotamiento con las luces de emergencia encendidas. ¿Se aplica la ley Move Over?","o":["No, es solo para policías y ambulancias","Sí, cámbiese de carril o baje la velocidad como para un vehículo de emergencia","Solo de noche","Solo en carreteras de peaje"],"h1":"Florida amplió la ley Move Over para proteger a más personas paradas en la orilla.","h2":"La ley Move Over de Florida también cubre a un vehículo descompuesto que está parado y muestra luces de emergencia u otras señales de advertencia, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril o baje la velocidad por un carro parado con luces de emergencia."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-022","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, on a two-way road, a school bus ahead is stopped with its stop arm out. You are coming from the other direction. What do you do?","o":["Slow down and pass with care","Keep going, because you are on the other side","Stop and stay stopped","Honk and pass"],"h1":"On a two-way road with no median, the rule is the same for both directions.","h2":"On a two-way road, traffic going both ways must stop for a school bus that shows its stop signal, so you stop even when coming from the other side.","p":"Right. On a two-way road, both directions stop for a stopped school bus."},"es":{"q":"En Florida, en una calle de doble sentido, un autobús escolar adelante está parado con el brazo de pare afuera. Usted viene en la dirección contraria. ¿Qué hace?","o":["Baja la velocidad y pasa con cuidado","Sigue, porque usted va del otro lado","Para y se queda parado","Toca la bocina y pasa"],"h1":"En una calle de doble sentido sin división, la regla es igual para las dos direcciones.","h2":"En una calle de doble sentido, el tráfico de las dos direcciones debe parar ante un autobús escolar que muestra su señal de pare, así que usted para aunque venga del otro lado.","p":"Correcto. En calle de doble sentido, las dos direcciones paran por el autobús escolar."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-023","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, a school bus is stopped across a raised concrete median, on the other side of a divided highway. Must you stop?","o":["No, you may keep going, with care","Yes, you must always stop","Only if children are on your side","Only if the bus honks"],"h1":"A raised barrier keeps the two directions apart.","h2":"On a divided highway with a raised median, you do not have to stop when the school bus is on the other side, but you should still watch for children.","p":"Right. With a raised median, the opposite side does not have to stop."},"es":{"q":"En Florida, un autobús escolar está parado del otro lado de una división de concreto elevada en una carretera dividida. ¿Debe usted parar?","o":["No, puede seguir con cuidado","Sí, siempre debe parar","Solo si hay niños de su lado","Solo si el autobús toca la bocina"],"h1":"Una división elevada separa las dos direcciones.","h2":"En una carretera dividida con una división elevada, usted no tiene que parar cuando el autobús escolar está del otro lado, pero igual debe estar atento a los niños.","p":"Correcto. Con división elevada, el lado contrario no tiene que parar."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-024","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a highway has an unpaved grass median. How wide must it be so that traffic on the other side does not have to stop for a school bus?","o":["At least 2 feet","At least 10 feet","At least 20 feet","At least 5 feet"],"h1":"The number is small, about the length of a sofa.","h2":"Florida law says that if an unpaved median is at least 5 feet wide, traffic going the other way does not have to stop for a stopped school bus.","p":"Right. An unpaved median of at least 5 feet means the other side does not stop."},"es":{"q":"En Florida, una carretera tiene una división de césped sin pavimentar. ¿Qué ancho debe tener para que el tráfico del otro lado no tenga que parar por un autobús escolar?","o":["Por lo menos 2 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 5 pies"],"h1":"El número es pequeño, más o menos el largo de un sofá.","h2":"La ley de Florida dice que si una división sin pavimentar mide por lo menos 5 pies de ancho, el tráfico que va en la otra dirección no tiene que parar por un autobús escolar parado.","p":"Correcto. Con una división sin pavimentar de por lo menos 5 pies, el otro lado no para."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-025","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a road has a paved center turn lane. A school bus is stopped on the other side with its stop arm out. What do you do?","o":["Keep going, because a turn lane divides the road","Stop, because a paved turn lane does not count as a divider","Pass using the turn lane","Slow down only"],"h1":"Only a raised barrier or a wide unpaved median lets the other side keep going.","h2":"A paved center turn lane is not a raised barrier or an unpaved median, so traffic in both directions must stop for the school bus.","p":"Right. A paved turn lane does not excuse you. Stop for the bus."},"es":{"q":"En Florida, una calle tiene un carril central pavimentado para doblar. Un autobús escolar está parado del otro lado con el brazo de pare afuera. ¿Qué hace?","o":["Sigue, porque el carril para doblar divide la calle","Para, porque un carril pavimentado para doblar no cuenta como división","Pasa usando el carril para doblar","Solo baja la velocidad"],"h1":"Solo una división elevada o una división ancha sin pavimentar permite que el otro lado siga.","h2":"Un carril central pavimentado para doblar no es una división elevada ni una división sin pavimentar, así que el tráfico de las dos direcciones debe parar por el autobús escolar.","p":"Correcto. Un carril para doblar no lo exime. Pare por el autobús."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-026","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind a school bus on a divided highway. The bus stops and shows its stop arm. What do you do?","o":["Pass on the left","Keep going, because the highway is divided","Stop behind the bus","Pass on the right shoulder"],"h1":"The median only helps traffic on the other side.","h2":"Traffic going the same way as a stopped school bus must always stop, even on a divided highway.","p":"Right. If you are behind a stopped school bus, you always stop."},"es":{"q":"En Florida, usted maneja detrás de un autobús escolar en una carretera dividida. El autobús para y saca el brazo de pare. ¿Qué hace?","o":["Lo rebasa por la izquierda","Sigue, porque la carretera está dividida","Para detrás del autobús","Lo rebasa por el acotamiento derecho"],"h1":"La división solo ayuda al tráfico del otro lado.","h2":"El tráfico que va en la misma dirección que un autobús escolar parado siempre debe parar, aunque la carretera esté dividida.","p":"Correcto. Si va detrás de un autobús escolar parado, siempre para."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-027","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you stopped for a school bus. When may you start driving again?","o":["When the stop arm is pulled back and the children are clear","As soon as the door closes","After you count to ten","When the driver waves at you"],"h1":"Watch the bus signal and the children, not a timer.","h2":"You must stay stopped until the bus pulls back its stop signal and the children are out of the road.","p":"Right. Wait until the stop arm is back in and the children are clear."},"es":{"q":"En Florida, usted paró por un autobús escolar. ¿Cuándo puede volver a manejar?","o":["Cuando el brazo de pare se recoge y los niños están fuera del camino","Apenas se cierra la puerta","Después de contar hasta diez","Cuando el chofer le hace una seña"],"h1":"Fíjese en la señal del autobús y en los niños, no en el tiempo.","h2":"Usted debe quedarse parado hasta que el autobús recoja su señal de pare y los niños estén fuera de la calle.","p":"Correcto. Espere a que se recoja el brazo de pare y los niños estén a salvo."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-028","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the tracks","Between 15 and 50 feet from the nearest rail","More than 100 feet away","Within 5 feet of the nearest rail"],"h1":"You need a safe gap from the train, but not so far that you block the road behind you.","h2":"Florida law says you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail when a train is coming.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, las luces están intermitentes en un cruce de tren. ¿Dónde debe parar?","o":["Encima de las vías","Entre 15 y 50 pies del riel más cercano","A más de 100 pies","A menos de 5 pies del riel más cercano"],"h1":"Necesita una distancia segura del tren, pero no tan lejos que bloquee la calle detrás de usted.","h2":"La ley de Florida dice que usted debe parar a no menos de 15 pies y no más de 50 pies del riel más cercano cuando viene un tren.","p":"Correcto. Pare entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-029","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, the gates at a railroad crossing are down, but you do not see a train. What do you do?","o":["Drive around the gates carefully","Honk and cross slowly","Back up and look for another way, then cross","Wait until the gates go up and the lights stop"],"h1":"Trains can be closer and faster than they look.","h2":"You must never drive around lowered railroad gates, so you wait until the gates are all the way up and the lights stop flashing.","p":"Right. Never go around railroad gates. Wait until they go up."},"es":{"q":"En Florida, las barreras de un cruce de tren están abajo, pero usted no ve ningún tren. ¿Qué hace?","o":["Pasa alrededor de las barreras con cuidado","Toca la bocina y cruza despacio","Da reversa, busca otro camino y cruza","Espera hasta que suban las barreras y se apaguen las luces"],"h1":"Los trenes pueden estar más cerca y ser más rápidos de lo que parece.","h2":"Usted nunca debe pasar alrededor de las barreras bajas del tren, así que espera hasta que las barreras suban por completo y las luces dejen de parpadear.","p":"Correcto. Nunca pase alrededor de las barreras del tren. Espere a que suban."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-030","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, traffic is backed up past a railroad crossing. When may you start across the tracks?","o":["When the car in front of you moves","Right away, if no train is in sight","Only when there is room for your whole car on the other side","When the driver behind you honks"],"h1":"Think about where your car will be if traffic stops again.","h2":"You may start across the tracks only when there is room for your whole vehicle on the other side, so you never get stuck on the rails.","p":"Right. Do not cross until your whole car fits on the other side."},"es":{"q":"En Florida, el tráfico está detenido más allá de un cruce de tren. ¿Cuándo puede empezar a cruzar las vías?","o":["Cuando avance el carro de adelante","De inmediato, si no se ve ningún tren","Solo cuando haya espacio para todo su carro del otro lado","Cuando el conductor de atrás toque la bocina"],"h1":"Piense dónde quedará su carro si el tráfico se detiene otra vez.","h2":"Usted puede empezar a cruzar las vías solo cuando haya espacio para todo su vehículo del otro lado, para nunca quedar atrapado sobre los rieles.","p":"Correcto. No cruce hasta que todo su carro quepa del otro lado."},"ref":{"doc":"FL","page":57}},{"id":"right-of-way-031","scope":"US","cat":"right-of-way","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"What does this white X-shaped sign mean?","o":["A railroad crossing. Yield to trains.","An intersection with four roads","A hospital is nearby","No parking in this area"],"h1":"This sign stands where a road meets something that cannot stop or swerve to miss you.","h2":"The white X-shaped sign, called a crossbuck, marks a railroad crossing, and you must yield to any train.","p":"Right. The crossbuck marks a railroad crossing. Yield to trains."},"es":{"q":"¿Qué significa esta señal blanca en forma de X?","o":["Un cruce de tren. Ceda el paso a los trenes.","Una intersección de cuatro calles","Hay un hospital cerca","No se permite estacionar en esta área"],"h1":"Esta señal está donde una calle se cruza con algo que no puede parar ni desviarse para no chocar con usted.","h2":"La señal blanca en forma de X, llamada crossbuck, marca un cruce de tren, y usted debe ceder el paso a cualquier tren.","p":"Correcto. La señal en X marca un cruce de tren. Ceda el paso a los trenes."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-032","scope":"US","cat":"right-of-way","sign":{"shape":"rr-advance","text":"RR"},"c":2,"en":{"q":"What does this round yellow sign with an X and the letters RR mean?","o":["A rest area is ahead","A road repair zone is ahead","A railroad crossing is ahead","You must turn right"],"h1":"This sign gives you a warning before you reach something.","h2":"The round yellow sign with an X and RR warns you that a railroad crossing is ahead, so you slow down, look, and listen.","p":"Right. The round yellow RR sign means a railroad crossing is ahead."},"es":{"q":"¿Qué significa esta señal amarilla redonda con una X y las letras RR?","o":["Hay un área de descanso adelante","Hay una zona de reparación de la calle adelante","Hay un cruce de tren adelante","Debe doblar a la derecha"],"h1":"Esta señal le avisa antes de que usted llegue a algo.","h2":"La señal amarilla redonda con una X y RR le avisa que hay un cruce de tren adelante, así que baje la velocidad, mire y escuche.","p":"Correcto. La señal amarilla redonda con RR significa cruce de tren adelante."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-033","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. Which lane should you be in?","o":["The left lane","The right lane, close to the curb","The center lane","Any lane, if you signal"],"h1":"Pick the lane on the same side as your turn.","h2":"To turn right, you get into the right lane near the curb and turn into the right lane of the new street.","p":"Right. Turn right from the right lane, near the curb."},"es":{"q":"En Florida, usted quiere doblar a la derecha. ¿En qué carril debe estar?","o":["En el carril izquierdo","En el carril derecho, cerca de la orilla","En el carril del centro","En cualquier carril, si pone la direccional"],"h1":"Escoja el carril del mismo lado de su vuelta.","h2":"Para doblar a la derecha, usted se coloca en el carril derecho cerca de la orilla y dobla al carril derecho de la nueva calle.","p":"Correcto. Doble a la derecha desde el carril derecho, cerca de la orilla."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-034","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you turn left from a two-way street onto another two-way street. Which lane do you turn into?","o":["The bike lane","The lane for oncoming traffic","The center turn lane","Any lane going your way that you may legally use"],"h1":"Think about which lanes carry traffic in your direction.","h2":"When you turn left, you may finish in any lane going your way that you are allowed to use, and you never enter a lane for oncoming traffic.","p":"Right. Turn left into a lane going your way that you may legally use."},"es":{"q":"En Florida, usted dobla a la izquierda de una calle de doble sentido a otra calle de doble sentido. ¿A qué carril dobla?","o":["Al carril de bicicletas","Al carril del tráfico que viene de frente","Al carril central de vuelta","A cualquier carril en su misma dirección que usted pueda usar legalmente"],"h1":"Piense en qué carriles llevan el tráfico en su misma dirección.","h2":"Cuando usted dobla a la izquierda, puede terminar en cualquier carril en su misma dirección que tenga permitido usar, y nunca entra a un carril del tráfico que viene de frente.","p":"Correcto. Doble a la izquierda a un carril en su misma dirección que usted pueda usar legalmente."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-035","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn should you turn on your signal?","o":["Only as you start to turn","At least 10 feet before","At least 25 feet before","At least 100 feet before"],"h1":"Other drivers need time to see what you plan to do.","h2":"In Florida you should signal at least 100 feet before you turn, so drivers and people walking know what you will do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de doblar?","o":["Solo cuando empieza a doblar","Por lo menos 10 pies antes","Por lo menos 25 pies antes","Por lo menos 100 pies antes"],"h1":"Los otros conductores necesitan tiempo para ver lo que usted va a hacer.","h2":"En Florida usted debe poner la direccional por lo menos 100 pies antes de doblar, para que los conductores y los peatones sepan lo que va a hacer.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes de doblar."},"ref":{"doc":"FL","page":69}},{"id":"right-of-way-036","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, when may you make a U-turn?","o":["Any time you miss your street","Only when it is safe and no sign forbids it","Only on a highway","Only at a railroad crossing"],"h1":"Think about signs and about traffic around you.","h2":"You may make a U-turn only where no sign forbids it and only when you can do it safely without getting in the way of other traffic.","p":"Right. Make a U-turn only when it is safe and allowed."},"es":{"q":"En Florida, ¿cuándo puede dar una vuelta en U?","o":["Cada vez que se pase de su calle","Solo cuando es seguro y ninguna señal lo prohíbe","Solo en la autopista","Solo en un cruce de tren"],"h1":"Piense en las señales y en el tráfico a su alrededor.","h2":"Usted puede dar una vuelta en U solo donde ninguna señal lo prohíba y solo cuando pueda hacerla con seguridad, sin estorbar a otros vehículos.","p":"Correcto. Dé vuelta en U solo cuando sea seguro y permitido."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-037","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you stopped at a red light and want to turn right. A person is crossing in front of you. What do you do?","o":["Turn now, because right on red is allowed","Honk and turn","Wait for the person to cross, then turn when traffic is clear","Turn into the far lane to go around the person"],"h1":"A right turn on red is allowed only after you yield.","h2":"When you turn right on red, you must first stop and yield to people crossing and to traffic, so you wait until the way is clear.","p":"Right. On red, yield to people and traffic before you turn right."},"es":{"q":"En Florida, usted paró en una luz roja y quiere doblar a la derecha. Una persona está cruzando delante de usted. ¿Qué hace?","o":["Dobla ahora, porque se permite doblar a la derecha en rojo","Toca la bocina y dobla","Espera que la persona cruce y luego dobla cuando el tráfico esté libre","Dobla al carril lejano para pasar alrededor de la persona"],"h1":"Doblar a la derecha en rojo se permite solo después de ceder el paso.","h2":"Cuando usted dobla a la derecha en rojo, primero debe parar y ceder el paso a las personas que cruzan y al tráfico, así que espera hasta que el camino esté libre.","p":"Correcto. En rojo, ceda el paso a peatones y tráfico antes de doblar a la derecha."},"ref":{"doc":"FL","page":51}},{"id":"right-of-way-038","scope":"US","cat":"right-of-way","sign":{"shape":"yield","text":"YIELD"},"c":2,"en":{"q":"What does this red and white upside-down triangle sign tell you to do?","o":["Stop fully every time","Speed up and merge","Slow down and let other traffic go first, stopping if needed","Turn around"],"h1":"This sign does not always mean a full stop.","h2":"A yield sign means you slow down and let other traffic and people go first, and you stop only if you need to.","p":"Right. A yield sign means slow down and let others go first."},"es":{"q":"¿Qué le indica esta señal de triángulo rojo y blanco con la punta hacia abajo?","o":["Pare por completo siempre","Acelere y únase al tráfico","Baje la velocidad y deje pasar primero a los demás, parando si hace falta","Dé la vuelta"],"h1":"Esta señal no siempre significa un alto total.","h2":"Una señal de ceda el paso significa que usted baja la velocidad y deja pasar primero a otros vehículos y personas, y para solo si es necesario.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a los demás."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-039","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are on a ramp joining a highway. Who has the right of way?","o":["Traffic already on the highway","You, because you are on the ramp","The faster car","Whoever signals first"],"h1":"Think about who is already on the main road.","h2":"When you merge onto a highway, you must yield to the traffic already on it and find a safe gap.","p":"Right. When merging, yield to traffic already on the highway."},"es":{"q":"En Florida, usted va por una rampa para entrar a una carretera. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va por la carretera","Usted, porque va por la rampa","El carro más rápido","El que pone la direccional primero"],"h1":"Piense en quién ya está en la vía principal.","h2":"Cuando usted entra a una carretera, debe ceder el paso al tráfico que ya va por ella y buscar un espacio seguro.","p":"Correcto. Al entrar a la carretera, ceda el paso al tráfico que ya va por ella."},"ref":{"doc":"FL","page":63}},{"id":"safe-driving-001","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"Think about a safe gap between your car and the rider.","h2":"Florida law says you must leave at least 3 feet between your car and a bicycle when you pass it.","p":"Right. Give a bicycle at least 3 feet when you pass."},"es":{"q":"En Florida, ¿cuánto espacio debe dejar al rebasar una bicicleta?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 10 pies"],"h1":"Piense en un espacio seguro entre su carro y el ciclista.","h2":"La ley de Florida dice que debe dejar al menos 3 pies entre su carro y una bicicleta cuando la rebasa.","p":"Correcto. Deje al menos 3 pies al rebasar una bicicleta."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-002","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. A bicycle is in the bike lane next to you. What should you do?","o":["Speed up and turn in front of it","Let the bicycle go by, then turn","Honk so the rider will stop","Turn from the left lane instead"],"h1":"Think about who is already moving straight in that lane.","h2":"The bicycle is going straight in its own lane, so you must let it pass before you turn right across the bike lane.","p":"Right. Let the bicycle go by first, then turn."},"es":{"q":"En Florida, usted quiere girar a la derecha. Hay una bicicleta en el carril de bicicletas a su lado. ¿Qué debe hacer?","o":["Acelerar y girar delante de ella","Dejar pasar la bicicleta y luego girar","Tocar la bocina para que pare","Girar desde el carril izquierdo"],"h1":"Piense en quién ya va derecho en ese carril.","h2":"La bicicleta va derecho en su propio carril, así que debe dejarla pasar antes de girar a la derecha y cruzar el carril de bicicletas.","p":"Correcto. Deje pasar la bicicleta primero y luego gire."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-003","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you parked on a busy street. What should you do before you open your door on the traffic side?","o":["Open it fast so you are quick","Turn on your wipers first","Honk the horn one time","Look back for bikes and cars"],"h1":"Think about who might be coming up beside your car.","h2":"A door that opens suddenly can hit a cyclist or a car, so you must look back and wait until it is safe to open it.","p":"Right. Look back for bikes and cars before you open your door."},"es":{"q":"En Florida, usted se estacionó en una calle con mucho tráfico. ¿Qué debe hacer antes de abrir la puerta del lado del tráfico?","o":["Abrirla rápido para no tardar","Encender los limpiaparabrisas","Tocar la bocina una vez","Mirar atrás por bicicletas y carros"],"h1":"Piense en quién podría venir al lado de su carro.","h2":"Una puerta que se abre de repente puede golpear a un ciclista o a un carro, así que debe mirar atrás y esperar hasta que sea seguro abrirla.","p":"Correcto. Mire atrás por bicicletas y carros antes de abrir la puerta."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-004","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, a person is walking across the street in a crosswalk in front of you. What must you do?","o":["Stop and let the person cross","Drive slowly around the person","Honk so the person hurries","Keep going if you have a green light"],"h1":"Think about who has the right to use the crosswalk first.","h2":"A person in a crosswalk has the right of way, so you must stop and wait until the person has crossed.","p":"Right. Stop and let people in the crosswalk cross."},"es":{"q":"En Florida, una persona cruza la calle por el paso peatonal frente a usted. ¿Qué debe hacer?","o":["Parar y dejar que la persona cruce","Pasar despacio alrededor de la persona","Tocar la bocina para que se apure","Seguir si tiene luz verde"],"h1":"Piense en quién tiene primero el derecho de usar el paso peatonal.","h2":"Una persona en el paso peatonal tiene el derecho de paso, así que debe parar y esperar a que termine de cruzar.","p":"Correcto. Pare y deje cruzar a las personas en el paso peatonal."},"ref":{"doc":"FL","page":87}},{"id":"safe-driving-005","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a person with a white cane or a guide dog is starting to cross the street. What should you do?","o":["Honk to warn the person","Drive around the person slowly","Stop and wait until the person crosses","Wave the person back to the curb"],"h1":"Think about a person who may not be able to see your car.","h2":"A white cane or a guide dog shows that the person may be blind, so you must stop and wait until the person is safely across.","p":"Right. Stop for a person with a white cane or a guide dog."},"es":{"q":"En Florida, una persona con un bastón blanco o un perro guía empieza a cruzar la calle. ¿Qué debe hacer?","o":["Tocar la bocina para avisarle","Pasar despacio alrededor de la persona","Parar y esperar a que la persona cruce","Hacerle señas para que vuelva a la acera"],"h1":"Piense en una persona que tal vez no puede ver su carro.","h2":"Un bastón blanco o un perro guía indica que la persona puede ser ciega, así que debe parar y esperar a que cruce con seguridad.","p":"Correcto. Pare para una persona con bastón blanco o perro guía."},"ref":{"doc":"FL","page":88}},{"id":"safe-driving-006","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why should you look twice for motorcycles before you turn or change lanes?","o":["Motorcycles must always use the right lane","Motorcycles are small and easy to miss","Motorcycles cannot use turn signals","Motorcycles always drive faster than cars"],"h1":"Think about how big a motorcycle looks next to a car.","h2":"A motorcycle is much smaller than a car, so it can hide in a blind spot or be easy to miss, and you should look twice.","p":"Right. Motorcycles are small and easy to miss, so look twice."},"es":{"q":"¿Por qué debe mirar dos veces por motocicletas antes de girar o cambiar de carril?","o":["Las motos siempre deben ir por la derecha","Las motos son pequeñas y fáciles de no ver","Las motos no pueden usar direccionales","Las motos siempre van más rápido que los carros"],"h1":"Piense en el tamaño de una moto al lado de un carro.","h2":"Una motocicleta es mucho más pequeña que un carro, así que puede esconderse en un punto ciego o pasar desapercibida, y debe mirar dos veces.","p":"Correcto. Las motos son pequeñas y fáciles de no ver; mire dos veces."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-007","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, may you share a lane side by side with a motorcycle?","o":["Yes, if the motorcycle is slow","Yes, on any multi-lane road","Yes, if you signal first","No, a motorcycle gets the full lane"],"h1":"Think about how much room a motorcycle needs to move safely.","h2":"In Florida a motorcycle has the right to use the full width of a lane, so you may not drive next to it in the same lane.","p":"Right. A motorcycle gets the full lane, so do not share it."},"es":{"q":"En Florida, ¿puede compartir un carril lado a lado con una motocicleta?","o":["Sí, si la moto va despacio","Sí, en cualquier vía de varios carriles","Sí, si pone la direccional antes","No, la moto tiene derecho a todo el carril"],"h1":"Piense en cuánto espacio necesita una moto para moverse con seguridad.","h2":"En Florida una motocicleta tiene derecho a usar todo el ancho del carril, así que usted no puede manejar a su lado en el mismo carril.","p":"Correcto. La moto tiene derecho a todo el carril; no lo comparta."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-008","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving next to a large truck. You cannot see the driver's face in the truck's side mirror. What does this mean?","o":["The driver probably cannot see you","The driver is not paying attention","The mirror is broken","You are at a safe distance"],"h1":"Think about how mirrors work in both directions.","h2":"If you cannot see the truck driver in the mirror, the driver cannot see you either, so you are in a blind spot and should move out of it.","p":"Right. If you cannot see the driver in the mirror, the driver cannot see you."},"es":{"q":"Usted maneja al lado de un camión grande. No puede ver la cara del chofer en el espejo lateral del camión. ¿Qué significa?","o":["El chofer probablemente no lo ve a usted","El chofer no está prestando atención","El espejo está roto","Usted está a una distancia segura"],"h1":"Piense en cómo funcionan los espejos en las dos direcciones.","h2":"Si usted no ve al chofer en el espejo, el chofer tampoco lo ve a usted, así que está en un punto ciego y debe salir de ahí.","p":"Correcto. Si no ve al chofer en el espejo, él no lo ve a usted."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-009","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"A large truck ahead has its right turn signal on. It moves a little to the left first. What should you do?","o":["Pass it on the right side","Honk to tell the driver to hurry","Stay back and wait for it to turn","Move up close behind the truck"],"h1":"Think about how much room a long truck needs to turn a corner.","h2":"Large trucks often swing left to make a wide right turn, so you should stay back and never squeeze in between the truck and the curb.","p":"Right. Stay back and let the truck make its wide right turn."},"es":{"q":"Un camión grande adelante tiene puesta la direccional derecha. Primero se mueve un poco a la izquierda. ¿Qué debe hacer?","o":["Rebasarlo por el lado derecho","Tocar la bocina para que se apure","Quedarse atrás y esperar a que gire","Acercarse mucho detrás del camión"],"h1":"Piense en cuánto espacio necesita un camión largo para doblar una esquina.","h2":"Los camiones grandes a menudo se abren a la izquierda para hacer un giro amplio a la derecha, así que debe quedarse atrás y nunca meterse entre el camión y la acera.","p":"Correcto. Quédese atrás y deje que el camión haga su giro amplio."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-010","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You just passed a large truck. When should you move back in front of it?","o":["Right away, as soon as you pass its bumper","When you can see the whole truck front in your mirror","After you slow down a little","Only after the truck flashes its lights"],"h1":"Think about how long it takes a heavy truck to stop.","h2":"A heavy truck needs a long distance to stop, so you should wait until you can see its whole front in your rearview mirror before you move in.","p":"Right. Move in only when you can see the whole truck front in your mirror."},"es":{"q":"Usted acaba de rebasar un camión grande. ¿Cuándo debe volver a ponerse delante de él?","o":["De inmediato, al pasar su parachoques","Cuando vea todo el frente del camión en su espejo","Después de bajar un poco la velocidad","Solo cuando el camión le haga cambio de luces"],"h1":"Piense en cuánto le toma a un camión pesado frenar.","h2":"Un camión pesado necesita mucha distancia para frenar, así que debe esperar hasta ver todo su frente en el espejo retrovisor antes de ponerse delante.","p":"Correcto. Póngase delante solo cuando vea todo el frente del camión en el espejo."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-011","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a school bus on a two-lane road stops. Its red lights flash and its stop arm is out. You are coming from the other direction. What must you do?","o":["Slow down and pass with care","Keep going because you are on the other side","Honk and then pass slowly","Stop and wait until the stop arm is pulled in"],"h1":"Think about children who may cross the road to reach the bus.","h2":"On a road without a divider, drivers in both directions must stop for a school bus with its stop arm out, and wait until the arm is pulled back in.","p":"Right. Stop for the school bus, even from the other direction."},"es":{"q":"En Florida, un autobús escolar para en una carretera de dos carriles. Sus luces rojas parpadean y tiene el brazo de pare afuera. Usted viene en dirección contraria. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir porque va del otro lado","Tocar la bocina y pasar despacio","Parar y esperar a que recojan el brazo de pare"],"h1":"Piense en los niños que pueden cruzar la calle para llegar al autobús.","h2":"En una vía sin división, los conductores de las dos direcciones deben parar ante un autobús escolar con el brazo de pare afuera, y esperar hasta que lo recojan.","p":"Correcto. Pare ante el autobús escolar, aunque venga en dirección contraria."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-012","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you are on a divided highway with a raised median. A school bus stops on the other side of the median. What should you do?","o":["You do not have to stop, but drive with care","Stop until the bus drives away","Stop, then pass at walking speed","Change to the lane closest to the bus"],"h1":"Think about what the raised median does between you and the bus.","h2":"When a raised barrier or wide median separates you from the bus, you do not have to stop, but you should still watch for children.","p":"Right. With a raised median between you, you do not have to stop, but stay alert."},"es":{"q":"En Florida, usted va por una carretera dividida con una mediana elevada. Un autobús escolar para del otro lado de la mediana. ¿Qué debe hacer?","o":["No tiene que parar, pero maneje con cuidado","Parar hasta que el autobús se vaya","Parar y luego pasar muy despacio","Cambiarse al carril más cerca del autobús"],"h1":"Piense en lo que hace la mediana elevada entre usted y el autobús.","h2":"Cuando una barrera elevada o una mediana ancha lo separa del autobús, no tiene que parar, pero debe seguir atento a los niños.","p":"Correcto. Con una mediana elevada entre ustedes, no tiene que parar, pero esté atento."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-013","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, what is the rule for holding a phone while driving in an active school zone?","o":["You may hold it for short calls","You may hold it if you drive slowly","You may not hold it; hands-free only","You may hold it only at a red light"],"h1":"Think about the extra danger near schools when children are present.","h2":"In Florida you may not hold a phone while driving in an active school zone, so you may only use it hands-free.","p":"Right. In an active school zone, no handheld phone, hands-free only."},"es":{"q":"En Florida, ¿cuál es la regla para sostener el teléfono mientras maneja en una zona escolar activa?","o":["Puede sostenerlo para llamadas cortas","Puede sostenerlo si maneja despacio","No puede sostenerlo; solo manos libres","Puede sostenerlo solo en luz roja"],"h1":"Piense en el peligro extra cerca de las escuelas cuando hay niños.","h2":"En Florida no puede sostener el teléfono mientras maneja en una zona escolar activa, así que solo puede usarlo con manos libres.","p":"Correcto. En una zona escolar activa, nada de teléfono en la mano; solo manos libres."},"ref":{"doc":"FL","page":34}},{"id":"safe-driving-014","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, can a police officer stop you only because you are texting while driving?","o":["No, only if you also break another rule","Yes, texting while driving is enough","No, texting is only a warning","Yes, but only on the interstate"],"h1":"Think about how serious Florida treats texting at the wheel.","h2":"In Florida, texting while driving is a primary offense, so an officer may stop you for that reason alone.","p":"Right. In Florida you can be stopped just for texting while driving."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo porque está enviando mensajes de texto mientras maneja?","o":["No, solo si también rompe otra regla","Sí, enviar mensajes al manejar es suficiente","No, los mensajes solo reciben una advertencia","Sí, pero solo en la autopista interestatal"],"h1":"Piense en qué tan en serio toma Florida los mensajes de texto al volante.","h2":"En Florida, enviar mensajes de texto mientras maneja es una infracción principal, así que un policía puede detenerlo solo por eso.","p":"Correcto. En Florida lo pueden detener solo por enviar mensajes al manejar."},"ref":{"doc":"FL","page":null}},{"id":"safe-driving-015","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are present?","o":["The fine is doubled","The fine is cut in half","There is no fine, only a warning","The fine is the same as anywhere else"],"h1":"Think about how the law protects people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, to protect the people working there.","p":"Right. Speeding fines in a work zone are doubled when workers are present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de construcción cuando hay trabajadores?","o":["La multa se duplica","La multa se reduce a la mitad","No hay multa, solo una advertencia","La multa es igual que en otro lugar"],"h1":"Piense en cómo la ley protege a las personas que trabajan en la carretera.","h2":"En Florida, la multa por exceso de velocidad en una zona de construcción se duplica cuando hay trabajadores presentes, para proteger a quienes trabajan ahí.","p":"Correcto. Las multas por exceso de velocidad en zona de construcción se duplican cuando hay trabajadores."},"ref":{"doc":"FL","page":29}},{"id":"safe-driving-016","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds up a sign and signals you. What should you do?","o":["Follow the posted speed sign instead","Drive past if the lane looks clear","Honk so the flagger lets you go","Follow the flagger's signals"],"h1":"Think about who controls traffic in a work zone right now.","h2":"A flagger directs traffic in a work zone, so you must follow the flagger's signals even if other signs say something else.","p":"Right. In a work zone, follow the flagger's signals."},"es":{"q":"En una zona de construcción, un abanderado muestra una señal y le hace indicaciones. ¿Qué debe hacer?","o":["Seguir la señal de velocidad en su lugar","Pasar si el carril parece libre","Tocar la bocina para que lo deje pasar","Seguir las indicaciones del abanderado"],"h1":"Piense en quién controla el tráfico en la zona de construcción en este momento.","h2":"Un abanderado dirige el tráfico en una zona de construcción, así que debe seguir sus indicaciones aunque otras señales digan otra cosa.","p":"Correcto. En una zona de construcción, siga las indicaciones del abanderado."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-017","scope":"US","cat":"safe-driving","sign":{"shape":"diamond-orange"},"c":1,"en":{"q":"What does an orange diamond-shaped sign usually warn you about?","o":["A school zone ahead","A work zone ahead","A railroad crossing ahead","A hospital ahead"],"h1":"Think about the color used for road work.","h2":"Orange warning signs are used for work zones, so an orange diamond tells you that road work is ahead.","p":"Right. An orange diamond sign warns of a work zone ahead."},"es":{"q":"¿Sobre qué le advierte normalmente una señal anaranjada en forma de rombo?","o":["Una zona escolar adelante","Una zona de construcción adelante","Un cruce de tren adelante","Un hospital adelante"],"h1":"Piense en el color que se usa para trabajos en la vía.","h2":"Las señales de advertencia anaranjadas se usan para zonas de construcción, así que un rombo anaranjado le dice que hay trabajos en la vía adelante.","p":"Correcto. Un rombo anaranjado advierte una zona de construcción adelante."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-018","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a highway with two lanes going your way. What should you do?","o":["Keep your speed and stay in your lane","Stop next to the police car","Move over a lane if safe; if not, slow down","Speed up to pass the area quickly"],"h1":"Think about giving space to people working beside the road.","h2":"Florida's Move Over law says you must move out of the lane next to the stopped vehicle when it is safe, and if you cannot, you must slow down.","p":"Right. Move over a lane if you safely can, or slow down."},"es":{"q":"En Florida, un carro de policía está parado en el acotamiento con las luces encendidas. Usted va por una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y su carril","Parar al lado del carro de policía","Cambiarse de carril si es seguro; si no, bajar la velocidad","Acelerar para pasar rápido"],"h1":"Piense en dar espacio a las personas que trabajan al lado de la vía.","h2":"La ley Move Over de Florida dice que debe salir del carril junto al vehículo detenido cuando sea seguro, y si no puede, debe bajar la velocidad.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-019","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you cannot move over for a stopped emergency vehicle on a road with a 55 mph limit. How slow must you go?","o":["20 mph below the limit","5 mph below the limit","10 mph below the limit","Exactly 25 mph"],"h1":"Think about a big drop in speed, not a small one.","h2":"Under Florida's Move Over law, if you cannot change lanes you must slow to 20 mph below the posted limit, so on a 55 mph road you go 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril ante un vehículo de emergencia detenido en una vía con límite de 55 mph. ¿A qué velocidad debe ir?","o":["20 mph por debajo del límite","5 mph por debajo del límite","10 mph por debajo del límite","Exactamente 25 mph"],"h1":"Piense en una reducción grande de velocidad, no pequeña.","h2":"Según la ley Move Over de Florida, si no puede cambiarse de carril debe bajar a 20 mph por debajo del límite, así que en una vía de 55 mph va a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph por debajo del límite."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-020","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car starts to skid on a slippery road. What should you do?","o":["Slam on the brakes hard","Turn the wheel sharply the other way","Press the gas to get control back","Ease off the gas and steer where you want to go"],"h1":"Think about gentle moves, not sudden ones.","h2":"In a skid, sudden braking or sharp steering makes it worse, so you should ease off the gas and gently steer in the direction you want the car to go.","p":"Right. Ease off the gas and steer where you want to go."},"es":{"q":"Su carro empieza a patinar en una vía resbalosa. ¿Qué debe hacer?","o":["Frenar de golpe con fuerza","Girar el volante bruscamente al otro lado","Acelerar para recuperar el control","Soltar el acelerador y dirigir hacia donde quiere ir"],"h1":"Piense en movimientos suaves, no bruscos.","h2":"Al patinar, frenar de golpe o girar bruscamente lo empeora, así que debe soltar el acelerador y dirigir suavemente hacia donde quiere que vaya el carro.","p":"Correcto. Suelte el acelerador y dirija hacia donde quiere ir."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-021","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your tires start to ride on top of water on a wet road (hydroplaning). What should you do?","o":["Brake hard right away","Ease off the gas and steer where you want to go","Speed up to get through the water","Turn the wheel quickly left and right"],"h1":"Think about letting the tires touch the road again.","h2":"When you hydroplane, the tires lose their grip on the road, so you should ease off the gas, stay off the brakes, and gently steer where you want to go.","p":"Right. Ease off the gas, avoid the brakes, and steer where you want to go."},"es":{"q":"Sus llantas empiezan a deslizarse sobre el agua en una vía mojada (hidroplaneo). ¿Qué debe hacer?","o":["Frenar fuerte de inmediato","Soltar el acelerador y dirigir hacia donde quiere ir","Acelerar para pasar el agua","Mover el volante rápido a los lados"],"h1":"Piense en dejar que las llantas vuelvan a tocar la vía.","h2":"En el hidroplaneo las llantas pierden el agarre con la vía, así que debe soltar el acelerador, no usar los frenos y dirigir suavemente hacia donde quiere ir.","p":"Correcto. Suelte el acelerador, no frene y dirija hacia donde quiere ir."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-022","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"A front tire suddenly blows out while you are driving. What should you do first?","o":["Hold the wheel firmly and ease off the gas","Brake hard to stop right away","Steer quickly onto the shoulder","Speed up to keep the car straight"],"h1":"Think about keeping control of the car before you stop.","h2":"A blowout can pull the car to one side, so you should hold the wheel firmly, ease off the gas, and brake gently only after the car is under control.","p":"Right. Hold the wheel firmly and ease off the gas."},"es":{"q":"Una llanta delantera revienta de repente mientras maneja. ¿Qué debe hacer primero?","o":["Sostener firme el volante y soltar el acelerador","Frenar fuerte para parar de inmediato","Girar rápido hacia el acotamiento","Acelerar para mantener el carro derecho"],"h1":"Piense en mantener el control del carro antes de parar.","h2":"Una llanta reventada puede jalar el carro hacia un lado, así que debe sostener firme el volante, soltar el acelerador y frenar suave solo cuando tenga el control.","p":"Correcto. Sostenga firme el volante y suelte el acelerador."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-023","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You press the brake pedal and your brakes do not work. What should you try first?","o":["Turn off the engine right away","Open the door and drag your foot","Pump the brake pedal fast","Shift into reverse"],"h1":"Think about trying to build up brake pressure again.","h2":"Pumping the brake pedal may build up pressure again, and if that fails you can use the parking brake slowly and shift to a lower gear.","p":"Right. Pump the brake pedal first, then use the parking brake."},"es":{"q":"Usted pisa el freno y los frenos no funcionan. ¿Qué debe intentar primero?","o":["Apagar el motor de inmediato","Abrir la puerta y arrastrar el pie","Bombear el pedal del freno rápido","Poner la reversa"],"h1":"Piense en volver a crear presión en los frenos.","h2":"Bombear el pedal del freno puede volver a crear presión, y si no funciona, puede usar el freno de mano poco a poco y cambiar a una velocidad más baja.","p":"Correcto. Bombee el pedal primero y luego use el freno de mano."}},{"id":"safe-driving-024","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your gas pedal gets stuck and the car keeps speeding up. What should you do?","o":["Pull the key out while moving","Turn the wheel hard to the side","Pump the gas pedal many times","Shift to neutral and brake"],"h1":"Think about how to stop the engine from pushing the wheels.","h2":"Shifting to neutral stops the engine from driving the wheels, so you can brake, pull off the road, and then turn off the engine.","p":"Right. Shift to neutral and brake to a safe stop."},"es":{"q":"Su pedal del acelerador se traba y el carro sigue acelerando. ¿Qué debe hacer?","o":["Sacar la llave mientras se mueve","Girar el volante fuerte hacia un lado","Bombear el acelerador muchas veces","Poner neutro y frenar"],"h1":"Piense en cómo impedir que el motor siga empujando las ruedas.","h2":"Al poner neutro el motor deja de mover las ruedas, así que puede frenar, salir de la vía y luego apagar el motor.","p":"Correcto. Ponga neutro y frene hasta parar con seguridad."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-025","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your right wheels drift off the pavement onto the dirt edge. What should you do?","o":["Jerk the wheel back onto the road","Ease off the gas, slow down, then steer back gently","Brake hard right away","Speed up and steer back fast"],"h1":"Think about slowing down before you return to the road.","h2":"Turning back too fast can make you lose control, so ease off the gas, slow down, and then steer gently back onto the pavement when it is safe.","p":"Right. Slow down first, then steer back gently."},"es":{"q":"Sus ruedas derechas se salen del pavimento a la orilla de tierra. ¿Qué debe hacer?","o":["Jalar el volante de golpe hacia la vía","Soltar el acelerador, bajar la velocidad y volver suavemente","Frenar fuerte de inmediato","Acelerar y volver rápido a la vía"],"h1":"Piense en bajar la velocidad antes de volver a la vía.","h2":"Volver demasiado rápido puede hacerle perder el control, así que suelte el acelerador, baje la velocidad y vuelva suavemente al pavimento cuando sea seguro.","p":"Correcto. Primero baje la velocidad y luego vuelva suavemente."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-026","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your car stalls on railroad tracks and a train is coming. What should you do?","o":["Stay in the car and keep trying to start it","Get out and stand next to the car","Get everyone out and move away from the tracks toward the train at an angle","Get out and run straight down the tracks"],"h1":"Think about where pieces of the car could fly if the train hits it.","h2":"Get everyone out right away and move away from the tracks at an angle toward the train, so flying parts from the crash do not hit you.","p":"Right. Get out fast and move away at an angle toward the train."},"es":{"q":"Su carro se apaga sobre las vías del tren y viene un tren. ¿Qué debe hacer?","o":["Quedarse en el carro y tratar de encenderlo","Salir y quedarse al lado del carro","Sacar a todos y alejarse de las vías en diagonal hacia el tren","Salir y correr por encima de las vías"],"h1":"Piense en hacia dónde podrían volar las piezas del carro si el tren lo golpea.","h2":"Saque a todos de inmediato y aléjense de las vías en diagonal hacia donde viene el tren, para que las piezas que vuelen en el choque no los golpeen.","p":"Correcto. Salga rápido y aléjese en diagonal hacia el tren."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-027","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Your car is stuck on railroad tracks, and no train is in sight. After everyone is out, who should you call?","o":["The number on the blue sign at the crossing, or 911","Your car insurance company","A tow truck, then wait in the car","Nobody, just keep trying to start the car"],"h1":"Think about who can warn the train before it arrives.","h2":"Get everyone out, then call the number on the blue emergency sign at the crossing or 911, so the railroad can stop or slow trains.","p":"Right. Call the number on the blue sign at the crossing, or 911."},"es":{"q":"Su carro está atascado en las vías del tren y no se ve ningún tren. Después de que todos salen, ¿a quién debe llamar?","o":["Al número del letrero azul del cruce, o al 911","A su compañía de seguros","A una grúa, y esperar dentro del carro","A nadie, solo seguir tratando de encenderlo"],"h1":"Piense en quién puede avisar al tren antes de que llegue.","h2":"Saque a todos y luego llame al número del letrero azul de emergencia del cruce o al 911, para que el ferrocarril pueda parar o frenar los trenes.","p":"Correcto. Llame al número del letrero azul del cruce, o al 911."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-028","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car goes into a canal or lake. What should you do first?","o":["Call for help and wait inside","Wait until the car fills with water","Turn on the hazard lights","Unbuckle, open a window and get out"],"h1":"Think about how fast you need to leave the car.","h2":"You should act right away: unbuckle your seat belt, open or break a window, and get out before the water gets too high.","p":"Right. Unbuckle, open a window and get out fast."},"es":{"q":"Su carro cae a un canal o a un lago. ¿Qué debe hacer primero?","o":["Pedir ayuda y esperar adentro","Esperar a que el carro se llene de agua","Encender las luces de emergencia","Quitarse el cinturón, abrir una ventana y salir"],"h1":"Piense en qué tan rápido debe salir del carro.","h2":"Debe actuar de inmediato: quítese el cinturón, abra o rompa una ventana y salga antes de que el agua suba demasiado.","p":"Correcto. Quítese el cinturón, abra una ventana y salga rápido."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-029","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"After a hurricane, water covers the road ahead and you cannot see how deep it is. What should you do?","o":["Drive through it slowly","Turn around and find another way","Drive through it fast","Follow the car in front of you"],"h1":"Think about how little moving water it takes to move a car.","h2":"Even shallow moving water can sweep a car away, and you cannot see what is under it, so turn around and find another way.","p":"Right. Turn around and do not drive into flooded roads."},"es":{"q":"Después de un huracán, el agua cubre la calle adelante y no puede ver qué tan profunda es. ¿Qué debe hacer?","o":["Pasar despacio por el agua","Dar la vuelta y buscar otro camino","Pasar rápido por el agua","Seguir al carro de adelante"],"h1":"Piense en qué poca agua en movimiento basta para mover un carro.","h2":"Aun el agua poco profunda en movimiento puede arrastrar un carro, y usted no ve lo que hay debajo, así que dé la vuelta y busque otro camino.","p":"Correcto. Dé la vuelta y no maneje por calles inundadas."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-030","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, after a storm, you reach an intersection where the traffic light is dark because the power is out. What should you do?","o":["Drive through without stopping","Stop only if a car is coming","Treat it like a four-way stop","Wait until the light works again"],"h1":"Think about how drivers take turns when there is no signal.","h2":"In Florida, a traffic light that is out works like a four-way stop, so you stop fully and take turns with the other drivers.","p":"Right. A dark traffic light works like a four-way stop."},"es":{"q":"En Florida, después de una tormenta, llega a un cruce donde el semáforo está apagado porque no hay luz. ¿Qué debe hacer?","o":["Pasar sin parar","Parar solo si viene un carro","Tratarlo como un pare de cuatro vías","Esperar hasta que el semáforo funcione"],"h1":"Piense en cómo se turnan los conductores cuando no hay semáforo.","h2":"En Florida, un semáforo apagado funciona como un pare de cuatro vías, así que debe parar por completo y turnarse con los otros conductores.","p":"Correcto. Un semáforo apagado funciona como un pare de cuatro vías."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-031","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"At night, a car coming toward you has very bright headlights. Where should you look?","o":["Toward the right edge of your lane","Straight into the other car's lights","At the center line","Down at your dashboard"],"h1":"Think about a guide that keeps you in your lane without looking at the glare.","h2":"Looking toward the right edge of your lane keeps you on the road while you avoid looking straight into the glare.","p":"Right. Look toward the right edge of your lane to avoid glare."},"es":{"q":"De noche, un carro que viene hacia usted tiene las luces muy fuertes. ¿Hacia dónde debe mirar?","o":["Hacia la orilla derecha de su carril","Directo a las luces del otro carro","A la línea del centro","Hacia abajo, al tablero"],"h1":"Piense en una guía que lo mantenga en su carril sin mirar el resplandor.","h2":"Mirar hacia la orilla derecha de su carril lo mantiene en la vía mientras evita mirar directo al resplandor.","p":"Correcto. Mire hacia la orilla derecha de su carril para evitar el resplandor."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-032","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you are using high beams at night. When must you switch to low beams for a car coming toward you?","o":["Within 100 feet of it","Within 200 feet of it","Only when it flashes its lights","Within 500 feet of it"],"h1":"Think about a long distance, because bright lights reach far.","h2":"In Florida you must dim your high beams when an oncoming car is within 500 feet, so its driver is not blinded.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, usted usa las luces altas de noche. ¿Cuándo debe cambiar a luces bajas por un carro que viene de frente?","o":["A 100 pies de él","A 200 pies de él","Solo cuando le haga cambio de luces","A 500 pies de él"],"h1":"Piense en una distancia larga, porque las luces altas llegan lejos.","h2":"En Florida debe bajar las luces altas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Baje las luces altas a 500 pies de un carro que viene de frente."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-033","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are following another car at night. When must you use low beams?","o":["Within 100 feet of it","Within 300 feet of it","Within 1,000 feet of it","Only in the city"],"h1":"Think about your lights shining into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet behind another car, so your lights do not blind its driver in the mirrors.","p":"Right. Use low beams within 300 feet of the car ahead."},"es":{"q":"En Florida, usted va detrás de otro carro de noche. ¿Cuándo debe usar luces bajas?","o":["A 100 pies de él","A 300 pies de él","A 1,000 pies de él","Solo en la ciudad"],"h1":"Piense en sus luces brillando en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos detrás de otro carro, para que sus luces no encandilen al conductor en los espejos.","p":"Correcto. Use luces bajas a 300 pies del carro de adelante."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-034","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"What does it mean to \"overdrive your headlights\" at night?","o":["Using high beams in the city","Driving with only parking lights on","Driving too fast to stop within the area your lights show","Leaving your lights on after you park"],"h1":"Think about how far ahead you can see at night.","h2":"If you drive so fast that you cannot stop within the distance your headlights light up, you are overdriving them, so slow down at night.","p":"Right. Drive slow enough to stop within what your headlights show."},"es":{"q":"¿Qué significa manejar más rápido de lo que alcanzan sus luces de noche?","o":["Usar luces altas en la ciudad","Manejar solo con luces de estacionamiento","Ir tan rápido que no puede parar dentro de lo que alumbran sus luces","Dejar las luces encendidas al estacionar"],"h1":"Piense en qué tan lejos puede ver de noche.","h2":"Si maneja tan rápido que no puede parar dentro de la distancia que alumbran sus faros, va más rápido de lo que alcanzan sus luces, así que baje la velocidad de noche.","p":"Correcto. Maneje a una velocidad que le permita parar dentro de lo que alumbran sus luces."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-035","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["Low beams","High beams","Parking lights only","No lights"],"h1":"Think about how bright light bounces back off fog.","h2":"High beams reflect off the fog and make it harder to see, so you should use low beams and slow down.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces bajas","Luces altas","Solo luces de estacionamiento","Ninguna luz"],"h1":"Piense en cómo la luz fuerte rebota en la neblina.","h2":"Las luces altas rebotan en la neblina y hacen más difícil ver, así que debe usar luces bajas y bajar la velocidad.","p":"Correcto. Use luces bajas con neblina."},"ref":{"doc":"FL","page":71}},{"id":"safe-driving-036","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, it is raining and your wipers are on. What must you also turn on?","o":["Your hazard lights","Your high beams","Your inside dome light","Your headlights"],"h1":"Think about helping other drivers see your car in the rain.","h2":"In Florida you must turn on your headlights when you drive in rain, smoke or fog, so other drivers can see you.","p":"Right. In the rain, turn on your headlights."},"es":{"q":"En Florida, está lloviendo y tiene los limpiaparabrisas encendidos. ¿Qué más debe encender?","o":["Las luces de emergencia","Las luces altas","La luz interior del techo","Los faros delanteros"],"h1":"Piense en ayudar a otros conductores a ver su carro en la lluvia.","h2":"En Florida debe encender los faros delanteros cuando maneja con lluvia, humo o neblina, para que otros conductores lo vean.","p":"Correcto. Con lluvia, encienda los faros delanteros."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-037","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"When is a road often most slippery during a rain?","o":["After it has rained for hours","In the first few minutes of rain","Only at night","Only when the sun comes out"],"h1":"Think about oil on the road mixing with the first water.","h2":"At the start of a rain, water mixes with oil on the road and makes it very slippery, so slow down as soon as it starts to rain.","p":"Right. Roads are often most slippery in the first minutes of rain."},"es":{"q":"¿Cuándo está la vía a menudo más resbalosa durante la lluvia?","o":["Después de horas de lluvia","En los primeros minutos de lluvia","Solo de noche","Solo cuando sale el sol"],"h1":"Piense en el aceite de la vía mezclándose con la primera agua.","h2":"Al comenzar la lluvia, el agua se mezcla con el aceite de la vía y la pone muy resbalosa, así que baje la velocidad en cuanto empiece a llover.","p":"Correcto. La vía suele estar más resbalosa en los primeros minutos de lluvia."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-038","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You feel very sleepy while driving. What is the best thing to do?","o":["Open the window and keep going","Turn the radio up loud","Pull off safely and rest","Drink coffee and drive faster"],"h1":"Think about what really fixes being tired.","h2":"Cold air, loud music or coffee do not cure sleepiness, so the safe choice is to pull off the road safely and rest or sleep.","p":"Right. When you are sleepy, pull off safely and rest."},"es":{"q":"Siente mucho sueño mientras maneja. ¿Qué es lo mejor que puede hacer?","o":["Abrir la ventana y seguir","Subir el volumen de la radio","Salir de la vía con seguridad y descansar","Tomar café y manejar más rápido"],"h1":"Piense en lo que de verdad quita el cansancio.","h2":"El aire frío, la música fuerte o el café no quitan el sueño, así que lo seguro es salir de la vía con cuidado y descansar o dormir.","p":"Correcto. Si tiene sueño, salga de la vía con seguridad y descanse."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-039","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what is the legal blood alcohol limit for drivers age 21 and older?","o":["0.08 percent","0.10 percent","0.05 percent","0.15 percent"],"h1":"Think about the limit used for adult drivers in Florida.","h2":"In Florida an adult driver with a blood alcohol level of 0.08 percent or more is driving under the influence.","p":"Right. For drivers 21 and older, the limit is 0.08 percent."},"es":{"q":"En Florida, ¿cuál es el límite legal de alcohol en la sangre para conductores de 21 años o más?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.15 por ciento"],"h1":"Piense en el límite que se usa para conductores adultos en Florida.","h2":"En Florida un conductor adulto con 0.08 por ciento o más de alcohol en la sangre está manejando bajo la influencia.","p":"Correcto. Para conductores de 21 años o más, el límite es 0.08 por ciento."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-040","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a driver under age 21 has a blood alcohol level of 0.02 percent. What happens?","o":["Nothing, it is below the adult limit","Only a warning is given","The car is taken away","The driver's license is suspended"],"h1":"Think about the stricter rule for young drivers.","h2":"Florida has a zero tolerance rule for drivers under 21, so a level of 0.02 percent or more leads to a license suspension.","p":"Right. Under 21, a 0.02 percent level means a license suspension."},"es":{"q":"En Florida, un conductor menor de 21 años tiene 0.02 por ciento de alcohol en la sangre. ¿Qué pasa?","o":["Nada, está por debajo del límite de adultos","Solo recibe una advertencia","Le quitan el carro","Le suspenden la licencia de conducir"],"h1":"Piense en la regla más estricta para conductores jóvenes.","h2":"Florida tiene una regla de cero tolerancia para menores de 21 años, así que un nivel de 0.02 por ciento o más lleva a la suspensión de la licencia.","p":"Correcto. Menor de 21, un nivel de 0.02 por ciento significa suspensión de la licencia."},"ref":{"doc":"FL","page":26}},{"id":"safe-driving-041","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are lawfully arrested for DUI and refuse a breath test for the first time. What happens to your license?","o":["Nothing happens to it","It is suspended for one year","It is suspended for one week","You get a warning letter only"],"h1":"Think about what you agreed to when you got a Florida license.","h2":"By driving in Florida you agree to be tested, so a first refusal after a lawful DUI arrest suspends your license for one year.","p":"Right. A first refusal suspends your license for one year."},"es":{"q":"En Florida, usted es arrestado legalmente por DUI y se niega por primera vez a una prueba de aliento. ¿Qué pasa con su licencia?","o":["No le pasa nada","La suspenden por un año","La suspenden por una semana","Solo recibe una carta de advertencia"],"h1":"Piense en lo que aceptó cuando recibió una licencia de Florida.","h2":"Al manejar en Florida usted acepta hacerse la prueba, así que negarse por primera vez después de un arresto legal por DUI suspende su licencia por un año.","p":"Correcto. Negarse la primera vez suspende su licencia por un año."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-042","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Which is the first thing alcohol harms in a driver?","o":["Hearing","Hand strength","Judgment","Eyesight in daylight"],"h1":"Think about making good choices, like deciding whether to drive.","h2":"Alcohol affects judgment first, so a driver may feel fine and still make bad choices, like speeding or deciding to drive at all.","p":"Right. Alcohol harms judgment first."},"es":{"q":"¿Qué es lo primero que el alcohol afecta en un conductor?","o":["El oído","La fuerza de las manos","El juicio","La vista de día"],"h1":"Piense en tomar buenas decisiones, como decidir si manejar.","h2":"El alcohol afecta primero el juicio, así que un conductor puede sentirse bien y aun así tomar malas decisiones, como ir rápido o decidir manejar.","p":"Correcto. El alcohol afecta primero el juicio."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-043","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"After drinking, what is the only thing that makes you sober?","o":["Time","Black coffee","A cold shower","Fresh air"],"h1":"Think about how the body gets rid of alcohol.","h2":"Your body removes alcohol slowly on its own, so only time makes you sober; coffee, showers and fresh air do not.","p":"Right. Only time makes you sober."},"es":{"q":"Después de tomar alcohol, ¿qué es lo único que le quita la borrachera?","o":["El tiempo","El café negro","Una ducha fría","El aire fresco"],"h1":"Piense en cómo el cuerpo elimina el alcohol.","h2":"Su cuerpo elimina el alcohol poco a poco por sí solo, así que solo el tiempo le quita la borrachera; el café, la ducha y el aire fresco no.","p":"Correcto. Solo el tiempo le quita la borrachera."}},{"id":"safe-driving-044","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"You took a cold medicine you bought at the store. What should you do before you drive?","o":["Nothing, store medicines are always safe","Drive only on small streets","Drink coffee to stay awake","Read the label for warnings about drowsiness"],"h1":"Think about side effects that can make you sleepy.","h2":"Many medicines you buy without a prescription can make you sleepy or slow, so read the label and do not drive if it warns about drowsiness.","p":"Right. Read the label and do not drive if the medicine makes you drowsy."},"es":{"q":"Usted tomó una medicina para el resfriado que compró en la tienda. ¿Qué debe hacer antes de manejar?","o":["Nada, las medicinas de tienda siempre son seguras","Manejar solo por calles pequeñas","Tomar café para no dormirse","Leer la etiqueta por advertencias de sueño"],"h1":"Piense en efectos que le pueden dar sueño.","h2":"Muchas medicinas que se compran sin receta pueden darle sueño o hacerlo más lento, así que lea la etiqueta y no maneje si advierte que causa sueño.","p":"Correcto. Lea la etiqueta y no maneje si la medicina le da sueño."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-045","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"An angry driver is tailgating you and making rude gestures. What should you do?","o":["Brake suddenly to teach a lesson","Avoid eye contact and let the driver pass","Make the same gestures back","Speed up to get away"],"h1":"Think about how to calm the situation, not make it bigger.","h2":"Reacting can make an angry driver more dangerous, so stay calm, avoid eye contact, and let the driver go by when it is safe.","p":"Right. Stay calm, avoid eye contact and let the driver pass."},"es":{"q":"Un conductor enojado lo sigue muy de cerca y le hace gestos groseros. ¿Qué debe hacer?","o":["Frenar de repente para darle una lección","Evitar mirarlo a los ojos y dejarlo pasar","Hacerle los mismos gestos","Acelerar para alejarse"],"h1":"Piense en cómo calmar la situación, no en hacerla más grande.","h2":"Responder puede hacer más peligroso a un conductor enojado, así que mantenga la calma, evite mirarlo a los ojos y déjelo pasar cuando sea seguro.","p":"Correcto. Mantenga la calma, no lo mire a los ojos y déjelo pasar."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-046","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"An angry driver keeps following you. Where should you drive?","o":["Straight to your home","To a quiet dead-end street","To a police station or busy public place","Onto the shoulder to stop and talk"],"h1":"Think about a place where people can help you.","h2":"You should not lead an angry driver to your home, so drive to a police station or a busy public place and call 911 if needed.","p":"Right. Drive to a police station or a busy public place."},"es":{"q":"Un conductor enojado lo sigue y no lo deja. ¿Hacia dónde debe manejar?","o":["Directo a su casa","A una calle sin salida y tranquila","A una estación de policía o un lugar público con gente","Al acotamiento para parar y hablar"],"h1":"Piense en un lugar donde la gente pueda ayudarle.","h2":"No debe llevar a un conductor enojado hasta su casa, así que maneje a una estación de policía o a un lugar público con gente y llame al 911 si hace falta.","p":"Correcto. Maneje a una estación de policía o a un lugar público con gente."}},{"id":"safe-driving-047","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Why is carbon monoxide from a car's exhaust so dangerous?","o":["You cannot see it or smell it","It always makes a loud sound","It only harms the engine","It turns the air black"],"h1":"Think about how you would notice a gas in the car.","h2":"Carbon monoxide has no color and no smell, so it can make you sleepy or sick without warning; never run the engine in a closed garage.","p":"Right. Carbon monoxide cannot be seen or smelled."},"es":{"q":"¿Por qué es tan peligroso el monóxido de carbono del escape del carro?","o":["No se puede ver ni oler","Siempre hace un ruido fuerte","Solo daña el motor","Pone el aire negro"],"h1":"Piense en cómo notaría un gas dentro del carro.","h2":"El monóxido de carbono no tiene color ni olor, así que puede darle sueño o enfermarlo sin aviso; nunca deje el motor encendido en un garaje cerrado.","p":"Correcto. El monóxido de carbono no se puede ver ni oler."}},{"id":"safe-driving-048","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"While driving, you get a headache and feel sleepy. You think it may be exhaust fumes. What should you do?","o":["Close all windows to stay warm","Turn the heater up high","Keep driving to get home fast","Open the windows and pull off safely"],"h1":"Think about getting fresh air right away.","h2":"A headache and sleepiness can be signs of carbon monoxide, so open the windows for fresh air, pull off safely, and have the exhaust checked.","p":"Right. Open the windows and pull off safely."},"es":{"q":"Mientras maneja, le da dolor de cabeza y sueño. Cree que pueden ser gases del escape. ¿Qué debe hacer?","o":["Cerrar todas las ventanas para no tener frío","Subir la calefacción al máximo","Seguir manejando para llegar rápido","Abrir las ventanas y salir de la vía con seguridad"],"h1":"Piense en conseguir aire fresco de inmediato.","h2":"El dolor de cabeza y el sueño pueden ser señales de monóxido de carbono, así que abra las ventanas, salga de la vía con seguridad y haga revisar el escape.","p":"Correcto. Abra las ventanas y salga de la vía con seguridad."}},{"id":"safe-driving-049","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why are worn tires with little tread dangerous?","o":["They make the radio louder","They grip the road poorly, mostly when wet","They use less gas","They make the steering heavier"],"h1":"Think about what the grooves in a tire do with water.","h2":"Tire tread moves water away so the tire can grip, so worn tires slip more and are more likely to hydroplane on wet roads.","p":"Right. Worn tires grip poorly, mostly on wet roads."},"es":{"q":"¿Por qué son peligrosas las llantas gastadas con poco dibujo?","o":["Hacen que la radio suene más fuerte","Agarran mal la vía, sobre todo mojada","Gastan menos gasolina","Hacen el volante más pesado"],"h1":"Piense en lo que hacen las ranuras de la llanta con el agua.","h2":"El dibujo de la llanta saca el agua para que la llanta agarre, así que las llantas gastadas resbalan más y es más fácil que hidroplaneen en vías mojadas.","p":"Correcto. Las llantas gastadas agarran mal, sobre todo en vías mojadas."},"ref":{"doc":"FL","page":39}},{"id":"safe-driving-050","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"When should you adjust your seat and mirrors?","o":["While driving on the highway","At the first red light","Before you start driving","Only when someone else drove your car"],"h1":"Think about when your hands and eyes are free to do it safely.","h2":"Adjusting mirrors while moving takes your attention off the road, so you should set your seat and mirrors before you start driving.","p":"Right. Adjust your seat and mirrors before you start driving."},"es":{"q":"¿Cuándo debe ajustar el asiento y los espejos?","o":["Mientras maneja en la autopista","En el primer semáforo en rojo","Antes de empezar a manejar","Solo si otra persona usó su carro"],"h1":"Piense en cuándo tiene las manos y los ojos libres para hacerlo con seguridad.","h2":"Ajustar los espejos en movimiento le quita la atención de la vía, así que debe ajustar el asiento y los espejos antes de empezar a manejar.","p":"Correcto. Ajuste el asiento y los espejos antes de empezar a manejar."},"ref":{"doc":"FL","page":59}},{"id":"safe-driving-051","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"What is the right way to use your car horn?","o":["To warn others of danger","To show you are angry","To greet friends you pass","To make slow drivers hurry"],"h1":"Think about safety, not feelings.","h2":"The horn is a safety tool, so use it to warn others of danger and not to show anger or rush people.","p":"Right. Use the horn to warn others of danger."},"es":{"q":"¿Cuál es la forma correcta de usar la bocina?","o":["Para avisar a otros de un peligro","Para mostrar que está enojado","Para saludar a amigos que pasa","Para que los lentos se apuren"],"h1":"Piense en la seguridad, no en los sentimientos.","h2":"La bocina es una herramienta de seguridad, así que úsela para avisar a otros de un peligro y no para mostrar enojo ni apurar a la gente.","p":"Correcto. Use la bocina para avisar a otros de un peligro."}},{"id":"safe-driving-052","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your wiper blades leave streaks and you cannot see well in the rain. What should you do?","o":["Drive with your head out the window","Use them only on the highway","Turn on your high beams","Replace the wiper blades soon"],"h1":"Think about what you need to see clearly in the rain.","h2":"Worn wiper blades do not clear the glass, so you should replace them soon to see the road clearly in the rain.","p":"Right. Replace worn wiper blades so you can see in the rain."},"es":{"q":"Sus limpiaparabrisas dejan rayas y no ve bien en la lluvia. ¿Qué debe hacer?","o":["Manejar con la cabeza afuera de la ventana","Usarlos solo en la autopista","Encender las luces altas","Cambiar las plumas del limpiaparabrisas pronto"],"h1":"Piense en lo que necesita para ver bien en la lluvia.","h2":"Las plumas gastadas no limpian bien el vidrio, así que debe cambiarlas pronto para ver la vía con claridad en la lluvia.","p":"Correcto. Cambie las plumas gastadas para ver bien en la lluvia."}},{"id":"safe-driving-053","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your brake pedal feels soft and sinks close to the floor. What should you do?","o":["Keep driving and press harder","Have the brakes checked right away","Wait until the next oil change","Use only the parking brake from now on"],"h1":"Think about what a soft pedal can say about your brakes.","h2":"A soft or sinking brake pedal is a warning sign of a brake problem, so you should have the brakes checked right away.","p":"Right. A soft brake pedal means get the brakes checked now."},"es":{"q":"El pedal del freno se siente blando y baja casi hasta el piso. ¿Qué debe hacer?","o":["Seguir manejando y pisar más fuerte","Hacer revisar los frenos de inmediato","Esperar hasta el próximo cambio de aceite","Usar solo el freno de mano desde ahora"],"h1":"Piense en lo que un pedal blando puede decir de sus frenos.","h2":"Un pedal de freno blando o que se hunde es una señal de un problema en los frenos, así que debe hacerlos revisar de inmediato.","p":"Correcto. Un pedal blando significa revisar los frenos ya."}},{"id":"safe-driving-054","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You are stopped behind a large truck on an uphill road. Why should you leave extra space?","o":["So you can read its license plate","So other cars can pass you","The truck may roll back a little when it starts","So the truck driver can see your lights"],"h1":"Think about what a heavy vehicle can do on a hill when it starts to move.","h2":"A heavy truck can roll back a little on a hill before it moves forward, so leave extra space in front of you.","p":"Right. Leave extra space because a truck may roll back on a hill."},"es":{"q":"Usted está parado detrás de un camión grande en una subida. ¿Por qué debe dejar más espacio?","o":["Para poder leer su placa","Para que otros carros lo rebasen","El camión puede rodar un poco hacia atrás al arrancar","Para que el chofer vea sus luces"],"h1":"Piense en lo que puede hacer un vehículo pesado en una subida al empezar a moverse.","h2":"Un camión pesado puede rodar un poco hacia atrás en una subida antes de avanzar, así que deje más espacio delante de usted.","p":"Correcto. Deje más espacio porque el camión puede rodar hacia atrás."},"ref":{"doc":"FL","page":82}},{"id":"signals-001","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What does a steady red traffic light mean?","o":["Slow down and go if no one is coming","Stop only if a police officer is there","Stop and stay stopped until it is safe and legal to go","Speed up to clear the intersection"],"h1":"Think about the strongest color on a traffic light.","h2":"A steady red light means you must stop and stay stopped, because cross traffic has the right to go.","p":"Right. A steady red light means stop and wait."},"es":{"q":"¿Qué significa una luz roja fija en el semáforo?","o":["Baje la velocidad y siga si no viene nadie","Pare solo si hay un policía","Pare y quédese parado hasta que sea seguro y legal seguir","Acelere para salir de la intersección"],"h1":"Piense en el color más fuerte del semáforo.","h2":"Una luz roja fija significa que usted debe parar y quedarse parado, porque el tráfico que cruza tiene el derecho a pasar.","p":"Correcto. Una luz roja fija significa pare y espere."},"ref":{"doc":"FL","page":51}},{"id":"signals-002","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"The light turns steady yellow as you come near. What should you do?","o":["Stop if you can do it safely","Speed up to beat the red light","Stop suddenly, no matter what","Keep going at the same speed always"],"h1":"Yellow is a warning. Think about what color comes next.","h2":"A steady yellow light warns that the light will soon turn red, so you should stop if you can do it safely.","p":"Right. Steady yellow means red is coming, so stop if it is safe."},"es":{"q":"La luz cambia a amarillo fijo cuando usted se acerca. ¿Qué debe hacer?","o":["Parar si lo puede hacer con seguridad","Acelerar para pasar antes de la roja","Frenar de golpe, pase lo que pase","Seguir siempre a la misma velocidad"],"h1":"El amarillo es una advertencia. Piense qué color viene después.","h2":"Una luz amarilla fija avisa que pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Amarillo fijo significa que viene la roja, así que pare si es seguro."},"ref":{"doc":"FL","page":51}},{"id":"signals-003","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You are already in the intersection when the light turns yellow. What should you do?","o":["Stop in the middle of the intersection","Back up to the stop line","Turn around in the intersection","Carefully finish going through the intersection"],"h1":"Think about where it is safest for your car to be when the light turns red.","h2":"If you are already in the intersection when the light turns yellow, you should carefully keep going, because stopping there would block traffic.","p":"Right. If you are already in the intersection, carefully clear it."},"es":{"q":"Usted ya está dentro de la intersección cuando la luz cambia a amarillo. ¿Qué debe hacer?","o":["Parar en medio de la intersección","Dar marcha atrás hasta la línea de pare","Dar la vuelta dentro de la intersección","Terminar de cruzar la intersección con cuidado"],"h1":"Piense dónde es más seguro estar cuando la luz cambie a roja.","h2":"Si usted ya está dentro de la intersección cuando la luz cambia a amarillo, debe seguir con cuidado, porque parar ahí bloquearía el tráfico.","p":"Correcto. Si ya está dentro de la intersección, termine de cruzar con cuidado."},"ref":{"doc":"FL","page":51}},{"id":"signals-004","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing red light mean?","o":["Slow down, but you do not need to stop","Stop fully, then go when the way is clear","The light is about to turn green","Only trucks must stop"],"h1":"A flashing red light works like a sign you already know.","h2":"A flashing red light works like a stop sign, so you must stop fully and then go when the way is clear.","p":"Right. A flashing red light means stop, then go when safe."},"es":{"q":"¿Qué significa una luz roja intermitente?","o":["Baje la velocidad, pero no tiene que parar","Pare por completo y luego siga cuando el camino esté libre","La luz está por cambiar a verde","Solo los camiones deben parar"],"h1":"Una luz roja intermitente funciona como una señal que usted ya conoce.","h2":"Una luz roja intermitente funciona como una señal de pare, así que usted debe parar por completo y luego seguir cuando el camino esté libre.","p":"Correcto. Luz roja intermitente significa pare y luego siga cuando sea seguro."},"ref":{"doc":"FL","page":52}},{"id":"signals-005","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a flashing yellow light mean?","o":["Slow down and go ahead with care","Stop fully and wait for green","The road is closed ahead","You must turn right"],"h1":"A flashing yellow light is a warning, not an order to stop.","h2":"A flashing yellow light means you should slow down and go ahead with care, because there may be danger ahead.","p":"Right. A flashing yellow light means slow down and be careful."},"es":{"q":"¿Qué significa una luz amarilla intermitente?","o":["Baje la velocidad y siga con cuidado","Pare por completo y espere la verde","La calle está cerrada más adelante","Usted debe girar a la derecha"],"h1":"Una luz amarilla intermitente es una advertencia, no una orden de parar.","h2":"Una luz amarilla intermitente significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber peligro más adelante.","p":"Correcto. Luz amarilla intermitente significa baje la velocidad y tenga cuidado."},"ref":{"doc":"FL","page":52}},{"id":"signals-006","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"The light is steady green. A person is still crossing in the crosswalk. What should you do?","o":["Go, because green gives you the right of way","Honk so the person moves faster","Wait and let the person finish crossing","Drive around the person"],"h1":"A green light lets you go, but think about who was there first.","h2":"A green light lets you go only when the way is clear, so you must wait for people and cars that are already in the intersection.","p":"Right. On green, you still let people finish crossing."},"es":{"q":"La luz está en verde fijo. Una persona todavía está cruzando por el paso peatonal. ¿Qué debe hacer?","o":["Seguir, porque la verde le da el derecho de paso","Tocar la bocina para que la persona se apure","Esperar y dejar que la persona termine de cruzar","Pasar por un lado de la persona"],"h1":"La luz verde le permite seguir, pero piense en quién estaba ahí primero.","h2":"La luz verde le permite seguir solo cuando el camino está libre, así que usted debe esperar a las personas y los carros que ya están en la intersección.","p":"Correcto. Con luz verde, igual deje que las personas terminen de cruzar."},"ref":{"doc":"FL","page":51}},{"id":"signals-007","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You see a steady green arrow pointing left. What does it mean?","o":["You may not turn left","You must yield to all oncoming cars first","Only buses may turn left","You may turn left, and oncoming traffic should be stopped"],"h1":"A green arrow gives a special turn. Think about what the other traffic sees.","h2":"A steady green arrow means you may turn in the direction of the arrow, because oncoming traffic should be facing a red light.","p":"Right. A green arrow means you may make that turn."},"es":{"q":"Usted ve una flecha verde fija que apunta a la izquierda. ¿Qué significa?","o":["No puede girar a la izquierda","Debe ceder el paso primero a todos los carros de frente","Solo los autobuses pueden girar a la izquierda","Puede girar a la izquierda, y el tráfico de frente debe estar parado"],"h1":"Una flecha verde da un giro especial. Piense qué ve el otro tráfico.","h2":"Una flecha verde fija significa que usted puede girar en la dirección de la flecha, porque el tráfico de frente debe tener luz roja.","p":"Correcto. Una flecha verde significa que puede hacer ese giro."},"ref":{"doc":"FL","page":52}},{"id":"signals-008","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing yellow arrow pointing left mean?","o":["You may turn left, and oncoming traffic is stopped","You may turn left, but you must yield to oncoming traffic and people walking","You must stop and wait for a green arrow","Left turns are not allowed here"],"h1":"Flashing yellow is a warning. Think about whether oncoming cars can still come.","h2":"A flashing yellow arrow means you may turn left, but you must first yield to oncoming traffic and to people walking, because they may still have a green light.","p":"Right. A flashing yellow arrow means turn only after you yield."},"es":{"q":"¿Qué significa una flecha amarilla intermitente que apunta a la izquierda?","o":["Puede girar a la izquierda, y el tráfico de frente está parado","Puede girar a la izquierda, pero debe ceder el paso al tráfico de frente y a los peatones","Debe parar y esperar una flecha verde","No se permite girar a la izquierda aquí"],"h1":"El amarillo intermitente es una advertencia. Piense si los carros de frente todavía pueden venir.","h2":"Una flecha amarilla intermitente significa que usted puede girar a la izquierda, pero primero debe ceder el paso al tráfico de frente y a los peatones, porque ellos pueden tener luz verde.","p":"Correcto. Flecha amarilla intermitente significa gire solo después de ceder el paso."},"ref":{"doc":"FL","page":52}},{"id":"signals-009","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a steady yellow arrow mean?","o":["The protected turn is ending, so stop if you can do it safely","You may now turn without looking","Wait for the cars behind you","The turn lane is closed for the day"],"h1":"A steady yellow arrow works like a steady yellow light, but for a turn.","h2":"A steady yellow arrow means the arrow will soon turn red, so you should stop if you can do it safely.","p":"Right. A steady yellow arrow means the turn time is ending."},"es":{"q":"¿Qué significa una flecha amarilla fija?","o":["El giro protegido está terminando, así que pare si lo puede hacer con seguridad","Ahora puede girar sin mirar","Espere a los carros que vienen detrás","El carril de giro está cerrado todo el día"],"h1":"Una flecha amarilla fija funciona como una luz amarilla fija, pero para un giro.","h2":"Una flecha amarilla fija significa que la flecha pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Una flecha amarilla fija significa que el tiempo del giro se acaba."},"ref":{"doc":"FL","page":52}},{"id":"signals-010","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, you are on a two-way street. A steady red arrow points left. What must you do?","o":["Turn left after a full stop if no one is coming","Turn left slowly without stopping","Stop and do not turn left until the signal allows it","Use the next lane to turn left instead"],"h1":"Think about what a red signal means, even when it is shaped like an arrow.","h2":"In Florida, on a two-way street, a steady red arrow pointing left means you must stop and must not turn left until a green arrow or green light lets you.","p":"Right. A red left arrow means no left turn yet."},"es":{"q":"En Florida, usted está en una calle de doble sentido. Una flecha roja fija apunta a la izquierda. ¿Qué debe hacer?","o":["Girar a la izquierda después de parar por completo si no viene nadie","Girar a la izquierda despacio sin parar","Parar y no girar a la izquierda hasta que la señal lo permita","Usar el otro carril para girar a la izquierda"],"h1":"Piense qué significa una señal roja, aunque tenga forma de flecha.","h2":"En Florida, en una calle de doble sentido, una flecha roja fija que apunta a la izquierda significa que usted debe parar y no puede girar a la izquierda hasta que una flecha verde o luz verde se lo permita.","p":"Correcto. Una flecha roja a la izquierda significa que todavía no puede girar."},"ref":{"doc":"FL","page":52}},{"id":"signals-011","scope":"FL","cat":"signals","sign":null,"c":1,"en":{"q":"In Florida, may you turn right on a steady red light?","o":["Yes, without stopping, if no one is coming","Yes, after a full stop, if no sign forbids it and the way is clear","No, never","Only between midnight and 6 a.m."],"h1":"Think about two things: a full stop, and any sign at the corner.","h2":"In Florida, you may turn right on a red light after you stop fully and yield, unless a sign says no turn on red.","p":"Right. Stop fully, yield, and then you may turn right on red unless a sign forbids it."},"es":{"q":"En Florida, ¿puede girar a la derecha con luz roja fija?","o":["Sí, sin parar, si no viene nadie","Sí, después de parar por completo, si ninguna señal lo prohíbe y el camino está libre","No, nunca","Solo entre la medianoche y las 6 a.m."],"h1":"Piense en dos cosas: parar por completo y cualquier señal en la esquina.","h2":"En Florida, usted puede girar a la derecha con luz roja después de parar por completo y ceder el paso, a menos que una señal prohíba girar con luz roja.","p":"Correcto. Pare por completo, ceda el paso, y luego puede girar a la derecha con roja si ninguna señal lo prohíbe."},"ref":{"doc":"FL","page":51}},{"id":"signals-012","scope":"FL","cat":"signals","sign":null,"c":3,"en":{"q":"In Florida, when may you turn left on a red light?","o":["From any street, if no one is coming","Never, under any condition","Only when you are in a hurry","From a one-way street onto another one-way street going left, after a full stop"],"h1":"Think about which streets have no oncoming traffic.","h2":"In Florida, you may turn left on red only from a one-way street onto a one-way street that goes left, and only after a full stop when the way is clear and no sign forbids it.","p":"Right. Left on red is only from one-way to one-way, after a full stop."},"es":{"q":"En Florida, ¿cuándo puede girar a la izquierda con luz roja?","o":["Desde cualquier calle, si no viene nadie","Nunca, en ningún caso","Solo cuando tiene prisa","De una calle de un solo sentido a otra calle de un solo sentido que va a la izquierda, después de parar por completo"],"h1":"Piense en qué calles no tienen tráfico de frente.","h2":"En Florida, usted puede girar a la izquierda con luz roja solo de una calle de un solo sentido a otra de un solo sentido que va a la izquierda, y solo después de parar por completo, con el camino libre y sin una señal que lo prohíba.","p":"Correcto. Izquierda con roja solo de un solo sentido a un solo sentido, después de parar."},"ref":{"doc":"FL","page":51}},{"id":"signals-013","scope":"FL","cat":"signals","sign":null,"c":0,"en":{"q":"In Florida, the traffic lights at an intersection are dark because the power is out. What should you do?","o":["Treat it as an all-way stop","Go through without stopping","Honk and go first","Treat it as a yield for you only"],"h1":"With no signal working, think about which sign makes every driver take turns.","h2":"In Florida, when traffic lights are not working, you treat the intersection as an all-way stop, so every driver stops and then goes in turn.","p":"Right. A dark signal means an all-way stop."},"es":{"q":"En Florida, los semáforos de una intersección están apagados porque no hay electricidad. ¿Qué debe hacer?","o":["Tratarla como una parada en todas las direcciones","Pasar sin parar","Tocar la bocina y pasar primero","Tratarla como un ceda el paso solo para usted"],"h1":"Si ninguna señal funciona, piense qué señal hace que todos los conductores tomen turnos.","h2":"En Florida, cuando los semáforos no funcionan, usted trata la intersección como una parada en todas las direcciones, así que cada conductor para y luego sigue por turno.","p":"Correcto. Un semáforo apagado significa parada en todas las direcciones."},"ref":{"doc":"FL","page":51}},{"id":"signals-014","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, your light is green, but the traffic ahead is backed up into the intersection. What should you do?","o":["Go in anyway, because the light is green","Drive into the intersection and wait there","Wait before the intersection until there is room on the other side","Drive on the shoulder around the line"],"h1":"Think about what happens to cross traffic if your car is stuck in the middle.","h2":"In Florida, you must not enter an intersection unless there is room for your car on the other side, even on green, because a stuck car blocks cross traffic.","p":"Right. Do not enter unless you can get all the way through."},"es":{"q":"En Florida, su luz está en verde, pero el tráfico de adelante está detenido hasta la intersección. ¿Qué debe hacer?","o":["Entrar de todos modos, porque la luz está en verde","Entrar a la intersección y esperar ahí","Esperar antes de la intersección hasta que haya espacio del otro lado","Manejar por el paseo para pasar la fila"],"h1":"Piense qué le pasa al tráfico que cruza si su carro queda atrapado en el medio.","h2":"En Florida, usted no debe entrar a una intersección si no hay espacio para su carro del otro lado, aunque tenga verde, porque un carro atrapado bloquea el tráfico que cruza.","p":"Correcto. No entre si no puede pasar por completo."},"ref":{"doc":"FL","page":51}},{"id":"signals-015","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A pedestrian signal shows a walking person. What does it mean for people on foot?","o":["They must not start crossing","They may start crossing the street","Only bicycles may cross","Cars may turn without looking"],"h1":"The walking person is a picture of what people may do.","h2":"A walking person signal means people on foot may start crossing, so drivers who turn must yield to them.","p":"Right. The walking person means people may cross."},"es":{"q":"Una señal para peatones muestra una persona caminando. ¿Qué significa para las personas a pie?","o":["No deben empezar a cruzar","Pueden empezar a cruzar la calle","Solo las bicicletas pueden cruzar","Los carros pueden girar sin mirar"],"h1":"La persona caminando es un dibujo de lo que la gente puede hacer.","h2":"La señal de la persona caminando significa que las personas a pie pueden empezar a cruzar, así que los conductores que giran deben cederles el paso.","p":"Correcto. La persona caminando significa que pueden cruzar."},"ref":{"doc":"FL","page":55}},{"id":"signals-016","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A pedestrian signal shows a flashing raised hand. What does it mean?","o":["Anyone may start crossing now","People must run back to the curb","Drivers must stop for the whole cycle","Do not start crossing, but people already crossing may finish"],"h1":"Think about the difference between starting to cross and finishing.","h2":"A flashing hand means people should not start crossing, but anyone already in the street may finish crossing.","p":"Right. A flashing hand means do not start, but finish if you already started."},"es":{"q":"Una señal para peatones muestra una mano levantada intermitente. ¿Qué significa?","o":["Cualquiera puede empezar a cruzar ahora","Las personas deben correr de vuelta a la acera","Los conductores deben parar todo el ciclo","No empiece a cruzar, pero quien ya está cruzando puede terminar"],"h1":"Piense en la diferencia entre empezar a cruzar y terminar de cruzar.","h2":"Una mano intermitente significa que las personas no deben empezar a cruzar, pero quien ya está en la calle puede terminar de cruzar.","p":"Correcto. Mano intermitente significa no empiece, pero termine si ya empezó."},"ref":{"doc":"FL","page":55}},{"id":"signals-017","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A pedestrian signal shows a number counting down next to a hand. What does the number show?","o":["How many seconds are left to finish crossing","How many people may cross","The speed limit for the street","How many cars may turn"],"h1":"The number gets smaller every second.","h2":"The countdown number shows how many seconds are left for people to finish crossing before the signal changes.","p":"Right. The countdown shows the seconds left to cross."},"es":{"q":"Una señal para peatones muestra un número que baja al lado de una mano. ¿Qué indica el número?","o":["Cuántos segundos quedan para terminar de cruzar","Cuántas personas pueden cruzar","El límite de velocidad de la calle","Cuántos carros pueden girar"],"h1":"El número se hace más pequeño cada segundo.","h2":"El número de cuenta regresiva muestra cuántos segundos les quedan a las personas para terminar de cruzar antes de que cambie la señal.","p":"Correcto. La cuenta regresiva muestra los segundos que quedan para cruzar."},"ref":{"doc":"FL","page":55}},{"id":"signals-018","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do yellow center lines on a road tell you?","o":["All lanes go the same direction","The road is a school zone","Traffic on each side of the line moves in opposite directions","Parking is allowed on the line"],"h1":"Think about where yellow lines usually are: between the two sides of the road.","h2":"Yellow center lines separate traffic moving in opposite directions, so cars on the other side come toward you.","p":"Right. Yellow lines separate traffic going opposite ways."},"es":{"q":"¿Qué le indican las líneas amarillas en el centro de la calle?","o":["Todos los carriles van en la misma dirección","La calle es una zona escolar","El tráfico de cada lado de la línea va en direcciones opuestas","Se permite estacionar sobre la línea"],"h1":"Piense dónde suelen estar las líneas amarillas: entre los dos lados de la calle.","h2":"Las líneas amarillas del centro separan el tráfico que va en direcciones opuestas, así que los carros del otro lado vienen hacia usted.","p":"Correcto. Las líneas amarillas separan el tráfico que va en sentidos opuestos."},"ref":{"doc":"FL","page":43}},{"id":"signals-019","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What do white lines between lanes tell you?","o":["The lanes carry traffic going opposite directions","The lanes carry traffic going the same direction","The lane is only for buses","You are near a railroad crossing"],"h1":"Compare white lines with yellow lines.","h2":"White lines between lanes show that the traffic in those lanes moves in the same direction.","p":"Right. White lines separate lanes going the same way."},"es":{"q":"¿Qué le indican las líneas blancas entre los carriles?","o":["Los carriles llevan tráfico en direcciones opuestas","Los carriles llevan tráfico en la misma dirección","El carril es solo para autobuses","Usted está cerca de un cruce de tren"],"h1":"Compare las líneas blancas con las amarillas.","h2":"Las líneas blancas entre carriles muestran que el tráfico de esos carriles va en la misma dirección.","p":"Correcto. Las líneas blancas separan carriles que van en el mismo sentido."},"ref":{"doc":"FL","page":43}},{"id":"signals-020","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"The yellow center line on your side is broken (dashed). What does that allow?","o":["You may never pass","You may park on the line","You may drive on the line for a long time","You may pass when it is safe"],"h1":"A broken line has gaps. Think about what gaps let you do.","h2":"A broken yellow line on your side means you may pass another car, but only when the way ahead is clear and safe.","p":"Right. A broken yellow line on your side means you may pass when safe."},"es":{"q":"La línea amarilla del centro de su lado es discontinua (con espacios). ¿Qué le permite?","o":["No puede rebasar nunca","Puede estacionar sobre la línea","Puede manejar sobre la línea por mucho rato","Puede rebasar cuando sea seguro"],"h1":"Una línea discontinua tiene espacios. Piense qué le permiten esos espacios.","h2":"Una línea amarilla discontinua de su lado significa que usted puede rebasar a otro carro, pero solo cuando el camino adelante esté libre y sea seguro.","p":"Correcto. Línea amarilla discontinua de su lado significa que puede rebasar si es seguro."},"ref":{"doc":"FL","page":44}},{"id":"signals-021","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"You see a solid yellow line on your side and a broken yellow line on the other side. Who may pass?","o":["Only drivers on the side with the broken line","Only drivers on your side","Drivers on both sides","No one, at any time"],"h1":"Look at the line closest to your car. It is the one that counts for you.","h2":"The line closest to you is the one you follow, so a solid yellow line on your side means you may not pass, while drivers next to the broken line may pass when safe.","p":"Right. A solid line on your side means you may not pass."},"es":{"q":"Usted ve una línea amarilla continua de su lado y una línea amarilla discontinua del otro lado. ¿Quién puede rebasar?","o":["Solo los conductores del lado de la línea discontinua","Solo los conductores de su lado","Los conductores de los dos lados","Nadie, en ningún momento"],"h1":"Mire la línea más cerca de su carro. Esa es la que cuenta para usted.","h2":"Usted sigue la línea más cerca de su carro, así que una línea amarilla continua de su lado significa que no puede rebasar, mientras que los conductores junto a la línea discontinua pueden rebasar si es seguro.","p":"Correcto. Una línea continua de su lado significa que no puede rebasar."},"ref":{"doc":"FL","page":44}},{"id":"signals-022","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do two solid yellow lines in the center of the road mean?","o":["Passing is allowed in both directions","Only trucks may pass","No one may cross them to pass, in either direction","The road ends ahead"],"h1":"Two solid lines are stronger than one. Think about both sides.","h2":"Two solid yellow lines mean drivers on both sides may not cross them to pass another car.","p":"Right. Double solid yellow means no passing for anyone."},"es":{"q":"¿Qué significan dos líneas amarillas continuas en el centro de la calle?","o":["Se permite rebasar en las dos direcciones","Solo los camiones pueden rebasar","Nadie puede cruzarlas para rebasar, en ninguna dirección","La calle se termina más adelante"],"h1":"Dos líneas continuas son más fuertes que una. Piense en los dos lados.","h2":"Dos líneas amarillas continuas significan que los conductores de los dos lados no pueden cruzarlas para rebasar a otro carro.","p":"Correcto. Doble línea amarilla continua significa que nadie puede rebasar."},"ref":{"doc":"FL","page":44}},{"id":"signals-023","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a solid white line between two lanes going the same way mean?","o":["You must change lanes now","Stay in your lane; changing lanes is discouraged there","Traffic in the next lane comes toward you","You may park along the line"],"h1":"A solid line asks you to stay where you are.","h2":"A solid white line between lanes means you should stay in your lane and change lanes only if you really must and it is safe.","p":"Right. A solid white line means stay in your lane."},"es":{"q":"¿Qué significa una línea blanca continua entre dos carriles que van en el mismo sentido?","o":["Usted debe cambiar de carril ahora","Quédese en su carril; no se recomienda cambiar de carril ahí","El tráfico del otro carril viene hacia usted","Puede estacionar junto a la línea"],"h1":"Una línea continua le pide quedarse donde está.","h2":"Una línea blanca continua entre carriles significa que usted debe quedarse en su carril y cambiar solo si de verdad lo necesita y es seguro.","p":"Correcto. Una línea blanca continua significa quédese en su carril."},"ref":{"doc":"FL","page":43}},{"id":"signals-024","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A center lane has a solid yellow line and a broken yellow line on each side. What is this lane for?","o":["Passing slow cars","Driving long distances","Parking and loading","Left turns by drivers from both directions"],"h1":"Cars from both directions can use this lane, but only for one kind of move.","h2":"A center lane marked with solid and broken yellow lines on both sides is a two-way left-turn lane, so drivers from either direction use it only to turn left.","p":"Right. That center lane is only for left turns from both directions."},"es":{"q":"Un carril del centro tiene una línea amarilla continua y una línea amarilla discontinua en cada lado. ¿Para qué es este carril?","o":["Para rebasar a carros lentos","Para manejar distancias largas","Para estacionar y cargar","Para girar a la izquierda, para conductores de las dos direcciones"],"h1":"Carros de las dos direcciones pueden usar este carril, pero solo para un tipo de maniobra.","h2":"Un carril del centro con líneas amarillas continuas y discontinuas en los dos lados es un carril de giro a la izquierda en ambos sentidos, así que los conductores de cualquier dirección lo usan solo para girar a la izquierda.","p":"Correcto. Ese carril del centro es solo para girar a la izquierda, desde las dos direcciones."},"ref":{"doc":"FL","page":45}},{"id":"signals-025","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Where should you stop when there is a wide white line painted across your lane at a red light?","o":["Before the white line","On top of the white line","Past the white line, at the corner","Anywhere in the intersection"],"h1":"This line shows the place where your front bumper should stop.","h2":"A wide white line across your lane is a stop line, so you must stop before it when you need to stop.","p":"Right. Stop before the white stop line."},"es":{"q":"¿Dónde debe parar cuando hay una línea blanca ancha pintada a lo ancho de su carril en una luz roja?","o":["Antes de la línea blanca","Encima de la línea blanca","Después de la línea blanca, en la esquina","En cualquier parte de la intersección"],"h1":"Esta línea muestra el lugar donde debe quedar el frente de su carro.","h2":"Una línea blanca ancha a lo ancho de su carril es la línea de pare, así que usted debe parar antes de ella cuando tiene que parar.","p":"Correcto. Pare antes de la línea blanca de pare."},"ref":{"doc":"FL","page":45}},{"id":"signals-026","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"You must stop at an intersection. There is a marked crosswalk but no stop line. Where do you stop?","o":["In the middle of the crosswalk","Past the crosswalk, in the intersection","Before the crosswalk","Only if a person is in the crosswalk"],"h1":"Think about keeping the path clear for people walking.","h2":"When there is no stop line, you stop before the crosswalk, so people on foot have a clear path.","p":"Right. With no stop line, stop before the crosswalk."},"es":{"q":"Usted debe parar en una intersección. Hay un paso peatonal marcado, pero no hay línea de pare. ¿Dónde para?","o":["En medio del paso peatonal","Después del paso peatonal, dentro de la intersección","Antes del paso peatonal","Solo si hay una persona en el paso peatonal"],"h1":"Piense en dejar libre el camino de las personas que caminan.","h2":"Cuando no hay línea de pare, usted para antes del paso peatonal, para que las personas a pie tengan el camino libre.","p":"Correcto. Sin línea de pare, pare antes del paso peatonal."},"ref":{"doc":"FL","page":45}},{"id":"signals-027","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"You see a bicycle symbol with two arrow shapes (chevrons) painted in your lane. What does it mean?","o":["Only bicycles may use this lane","Bicycles and cars share this lane","Bicycles are not allowed here","This lane is for parking bicycles"],"h1":"The marking is in a regular traffic lane, not in a separate bike lane.","h2":"A bicycle with chevrons is a shared lane marking, which means bicycles and cars share the lane, so watch for riders and give them room.","p":"Right. That marking means bikes and cars share the lane."},"es":{"q":"Usted ve un dibujo de bicicleta con dos flechas en forma de ángulo pintado en su carril. ¿Qué significa?","o":["Solo las bicicletas pueden usar este carril","Las bicicletas y los carros comparten este carril","No se permiten bicicletas aquí","Este carril es para estacionar bicicletas"],"h1":"La marca está en un carril normal de tráfico, no en un carril aparte para bicicletas.","h2":"Una bicicleta con flechas en ángulo es una marca de carril compartido, lo que significa que bicicletas y carros comparten el carril, así que fíjese en los ciclistas y deles espacio.","p":"Correcto. Esa marca significa que bicicletas y carros comparten el carril."},"ref":{"doc":"FL","page":45}},{"id":"signals-028","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A white diamond is painted in a lane. What does it usually mean?","o":["The lane is a school zone","The lane ends soon","The lane is for slow trucks only","The lane is reserved for certain vehicles, like carpools or buses, at posted times"],"h1":"Look for a sign near the lane that tells who may use it.","h2":"A white diamond marks a reserved lane, such as a high-occupancy (HOV) lane for carpools, so you may use it only if you meet the rules posted on the signs.","p":"Right. The diamond marks a reserved lane, like a carpool lane."},"es":{"q":"Hay un diamante blanco pintado en un carril. ¿Qué suele significar?","o":["El carril es una zona escolar","El carril se termina pronto","El carril es solo para camiones lentos","El carril está reservado para ciertos vehículos, como carros compartidos o autobuses, en los horarios indicados"],"h1":"Busque una señal cerca del carril que diga quién puede usarlo.","h2":"Un diamante blanco marca un carril reservado, como un carril para vehículos con varios ocupantes (HOV), así que usted solo puede usarlo si cumple las reglas de las señales.","p":"Correcto. El diamante marca un carril reservado, como el de carros compartidos."},"ref":{"doc":"FL","page":69}},{"id":"signals-029","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A white arrow painted in your lane points only to the right. What should you do?","o":["Turn right from this lane","Go straight from this lane","Turn left from this lane","Make a U-turn from this lane"],"h1":"Arrows in a lane show which way that lane must go.","h2":"A lane arrow that points only to the right means drivers in that lane must turn right.","p":"Right. A right arrow in your lane means turn right."},"es":{"q":"Una flecha blanca pintada en su carril apunta solo a la derecha. ¿Qué debe hacer?","o":["Girar a la derecha desde este carril","Seguir derecho desde este carril","Girar a la izquierda desde este carril","Dar una vuelta en U desde este carril"],"h1":"Las flechas en un carril muestran hacia dónde debe ir ese carril.","h2":"Una flecha en el carril que apunta solo a la derecha significa que los conductores en ese carril deben girar a la derecha.","p":"Correcto. Una flecha a la derecha en su carril significa gire a la derecha."},"ref":{"doc":"FL","page":45}},{"id":"signals-030","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A row of white triangles is painted across your lane, pointing at you. What does it mean?","o":["Speed up to merge","The lane is for bicycles only","Yield here to traffic and people walking","You are on a one-way street the wrong way"],"h1":"The triangles look like a sign with the same shape.","h2":"A row of white triangles pointing toward you is a yield line, so you must slow down and be ready to stop there for other traffic and people walking.","p":"Right. The row of triangles is a yield line."},"es":{"q":"Una fila de triángulos blancos está pintada a lo ancho de su carril, apuntando hacia usted. ¿Qué significa?","o":["Acelere para incorporarse","El carril es solo para bicicletas","Ceda el paso aquí al tráfico y a los peatones","Usted va en contra en una calle de un solo sentido"],"h1":"Los triángulos se parecen a una señal que tiene la misma forma.","h2":"Una fila de triángulos blancos que apuntan hacia usted es una línea de ceda el paso, así que usted debe bajar la velocidad y estar listo para parar ahí por otro tráfico y por los peatones.","p":"Correcto. La fila de triángulos es una línea de ceda el paso."}},{"id":"signals-031","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"Over a reversible lane, you see a green arrow pointing down. What does it mean?","o":["You must leave this lane","You may drive in this lane","You may not drive in this lane","The lane is only for left turns"],"h1":"Green on a lane signal means the same thing as green on a traffic light.","h2":"A green arrow pointing down over a lane means you may drive in that lane.","p":"Right. A green arrow over the lane means you may use it."},"es":{"q":"Sobre un carril reversible, usted ve una flecha verde que apunta hacia abajo. ¿Qué significa?","o":["Debe salir de este carril","Puede manejar en este carril","No puede manejar en este carril","El carril es solo para girar a la izquierda"],"h1":"El verde en una señal de carril significa lo mismo que en un semáforo.","h2":"Una flecha verde que apunta hacia abajo sobre un carril significa que usted puede manejar en ese carril.","p":"Correcto. Una flecha verde sobre el carril significa que puede usarlo."},"ref":{"doc":"FL","page":53}},{"id":"signals-032","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Over a reversible lane, you see a red X. What does it mean?","o":["You may drive in this lane","You may pass in this lane","The lane is for buses only","Do not drive in this lane"],"h1":"Think about what a red X means anywhere.","h2":"A red X over a lane means you must not drive in that lane, because traffic may be coming the other way.","p":"Right. A red X means do not use that lane."},"es":{"q":"Sobre un carril reversible, usted ve una X roja. ¿Qué significa?","o":["Puede manejar en este carril","Puede rebasar en este carril","El carril es solo para autobuses","No maneje en este carril"],"h1":"Piense qué significa una X roja en cualquier lugar.","h2":"Una X roja sobre un carril significa que usted no debe manejar en ese carril, porque el tráfico puede venir en el otro sentido.","p":"Correcto. Una X roja significa no use ese carril."},"ref":{"doc":"FL","page":53}},{"id":"signals-033","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Over a reversible lane, you see a steady yellow X. What should you do?","o":["Move out of this lane safely, because it is about to change","Stay in the lane as long as you like","Speed up in this lane","Stop in the lane and wait"],"h1":"A steady yellow X works like a steady yellow light: something is about to change.","h2":"A steady yellow X over a lane means the lane is about to close to your direction, so you should safely move out of it.","p":"Right. A steady yellow X means leave the lane safely."},"es":{"q":"Sobre un carril reversible, usted ve una X amarilla fija. ¿Qué debe hacer?","o":["Salir del carril con seguridad, porque está por cambiar","Quedarse en el carril todo el tiempo que quiera","Acelerar en este carril","Parar en el carril y esperar"],"h1":"Una X amarilla fija funciona como una luz amarilla fija: algo está por cambiar.","h2":"Una X amarilla fija sobre un carril significa que el carril se va a cerrar para su dirección, así que usted debe salir de él con seguridad.","p":"Correcto. Una X amarilla fija significa salga del carril con seguridad."},"ref":{"doc":"FL","page":53}},{"id":"signals-034","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A police officer is directing traffic at an intersection. The light is green, but the officer signals you to stop. What do you do?","o":["Go, because the light is green","Honk to get the officer to move","Stop and follow the officer","Turn right to go around the officer"],"h1":"Think about who sees the real situation at that moment.","h2":"You must follow the directions of a police officer directing traffic, even when they are different from the traffic light.","p":"Right. A police officer’s directions come before the traffic light."},"es":{"q":"Un policía está dirigiendo el tráfico en una intersección. La luz está en verde, pero el policía le indica que pare. ¿Qué hace?","o":["Seguir, porque la luz está en verde","Tocar la bocina para que el policía se mueva","Parar y seguir las indicaciones del policía","Girar a la derecha para pasar al policía"],"h1":"Piense quién ve la situación real en ese momento.","h2":"Usted debe seguir las indicaciones de un policía que dirige el tráfico, aunque sean diferentes a las del semáforo.","p":"Correcto. Las indicaciones del policía van antes que el semáforo."},"ref":{"doc":"FL","page":51}},{"id":"signals-035","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"In a work zone, a flagger holds up a sign that says SLOW. What should you do?","o":["Stop and wait for a police officer","Slow down and go ahead with care, watching for workers","Keep your normal speed","Turn around and find another road"],"h1":"Think about who may be working close to the road.","h2":"A flagger showing a SLOW sign means you should slow down and go ahead with care, because workers and equipment may be near the road.","p":"Right. A SLOW paddle means slow down and drive with care."},"es":{"q":"En una zona de trabajo, un abanderado levanta un letrero que dice SLOW (despacio). ¿Qué debe hacer?","o":["Parar y esperar a un policía","Bajar la velocidad y seguir con cuidado, fijándose en los trabajadores","Mantener su velocidad normal","Dar la vuelta y buscar otra calle"],"h1":"Piense en quién puede estar trabajando cerca de la calle.","h2":"Un abanderado que muestra el letrero SLOW significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber trabajadores y máquinas cerca de la calle.","p":"Correcto. El letrero SLOW significa baje la velocidad y maneje con cuidado."},"ref":{"doc":"FL","page":54}},{"id":"signals-036","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A flagger in a work zone holds up a STOP sign, but the traffic light ahead is green. What should you do?","o":["Follow the green light and go","Slow down but keep moving","Pass the flagger on the shoulder","Stop and wait until the flagger lets you go"],"h1":"Think about who is in charge of traffic in a work zone.","h2":"You must obey a flagger in a work zone, so you stop when the flagger shows STOP, even if a traffic light is green.","p":"Right. A flagger’s STOP sign comes before a green light."},"es":{"q":"Un abanderado en una zona de trabajo levanta un letrero de STOP (pare), pero el semáforo de adelante está en verde. ¿Qué debe hacer?","o":["Seguir la luz verde y pasar","Bajar la velocidad pero seguir","Pasar al abanderado por el paseo","Parar y esperar hasta que el abanderado le deje pasar"],"h1":"Piense quién dirige el tráfico en una zona de trabajo.","h2":"Usted debe obedecer al abanderado en una zona de trabajo, así que para cuando el abanderado muestra STOP, aunque el semáforo esté en verde.","p":"Correcto. El letrero STOP del abanderado va antes que la luz verde."},"ref":{"doc":"FL","page":54}},{"id":"signals-037","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Which should you obey first: a traffic light, a stop sign, or a police officer directing traffic?","o":["The police officer","The traffic light","The stop sign","Whichever is closest to you"],"h1":"Signs and lights are set ahead of time. Think about who can react to what is happening now.","h2":"A police officer directing traffic comes first, before any traffic light or sign, because the officer is handling what is happening right now.","p":"Right. An officer directing traffic comes before lights and signs."},"es":{"q":"¿A quién debe obedecer primero: a un semáforo, a una señal de pare o a un policía que dirige el tráfico?","o":["Al policía","Al semáforo","A la señal de pare","Al que esté más cerca de usted"],"h1":"Las señales y los semáforos se ponen con anticipación. Piense quién puede reaccionar a lo que pasa ahora.","h2":"Un policía que dirige el tráfico va primero, antes que cualquier semáforo o señal, porque el policía maneja lo que está pasando en ese momento.","p":"Correcto. Un policía que dirige el tráfico va antes que los semáforos y las señales."},"ref":{"doc":"FL","page":51}},{"id":"signals-038","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"On a divided highway, what color is the solid line along the left edge of your lanes?","o":["White","Blue","Yellow","Red"],"h1":"Think about which color is used for the side closest to traffic going the other way.","h2":"On a divided highway, the left edge line is yellow and the right edge line is white, which helps you see the side toward opposite traffic.","p":"Right. The left edge line is yellow; the right edge line is white."},"es":{"q":"En una autopista dividida, ¿de qué color es la línea continua del borde izquierdo de sus carriles?","o":["Blanca","Azul","Amarilla","Roja"],"h1":"Piense qué color se usa para el lado más cerca del tráfico que va en sentido contrario.","h2":"En una autopista dividida, la línea del borde izquierdo es amarilla y la del borde derecho es blanca, lo que le ayuda a ver el lado del tráfico contrario.","p":"Correcto. La línea del borde izquierdo es amarilla; la del derecho es blanca."},"ref":{"doc":"FL","page":43}},{"id":"signs-001","scope":"US","cat":"signs","sign":{"shape":"stop","text":"STOP"},"c":0,"en":{"q":"A red sign has eight sides. What must you do?","o":["Stop fully, then go when it is safe","Slow down, and stop only if cars come","Get ready for road work ahead","Watch for a school zone ahead"],"h1":"Think about the only sign with eight sides.","h2":"An eight-sided red sign is a stop sign, so you must come to a full stop and go only when the way is clear.","p":"Right. Eight sides means stop fully, then go when safe."},"es":{"q":"Una señal roja tiene ocho lados. ¿Qué debe hacer?","o":["Pararse por completo y seguir cuando sea seguro","Bajar la velocidad y pararse solo si vienen carros","Prepararse para obras en la vía","Estar atento a una zona escolar"],"h1":"Piense en la única señal que tiene ocho lados.","h2":"Una señal roja de ocho lados es la señal de pare, así que usted debe pararse por completo y seguir solo cuando el camino esté libre.","p":"Correcto. Ocho lados significa pararse por completo y seguir cuando sea seguro."},"ref":{"doc":"FL","page":47}},{"id":"signs-002","scope":"US","cat":"signs","sign":{"shape":"yield","text":"YIELD"},"c":1,"en":{"q":"What does a red and white triangle pointing down mean?","o":["Stop every time, even if the road is clear","Slow down, let others go first, stop if needed","Speed up so you can merge quickly","The road ends just ahead"],"h1":"This sign is about who goes first.","h2":"The upside-down triangle is a yield sign, so you slow down, let other traffic go first, and stop if you need to.","p":"Right. Yield means slow down and let others go first."},"es":{"q":"¿Qué significa un triángulo rojo y blanco con la punta hacia abajo?","o":["Pararse siempre, aunque la vía esté libre","Bajar la velocidad, dejar pasar a otros y parar si hace falta","Acelerar para entrar rápido al tráfico","La vía se termina más adelante"],"h1":"Esta señal trata de quién pasa primero.","h2":"El triángulo con la punta hacia abajo es la señal de ceda el paso, así que usted baja la velocidad, deja pasar a los demás y se para si hace falta.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a otros."},"ref":{"doc":"FL","page":47}},{"id":"signs-003","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":2,"en":{"q":"What does a sign with five sides warn you about?","o":["A railroad crossing ahead","A hospital nearby","A school zone or school crossing","A no-passing zone"],"h1":"Think about who you may see walking near this sign.","h2":"A five-sided sign marks a school zone or a school crossing, so you should slow down and watch for children.","p":"Right. Five sides means a school is near."},"es":{"q":"¿Sobre qué le avisa una señal de cinco lados?","o":["Un cruce de tren más adelante","Un hospital cerca","Una zona escolar o un cruce escolar","Una zona donde no se puede rebasar"],"h1":"Piense en quiénes podrían caminar cerca de esta señal.","h2":"Una señal de cinco lados marca una zona escolar o un cruce escolar, así que usted debe bajar la velocidad y estar atento a los niños.","p":"Correcto. Cinco lados significa que hay una escuela cerca."},"ref":{"doc":"FL","page":57}},{"id":"signs-004","scope":"US","cat":"signs","sign":{"shape":"rr-advance","text":"RR"},"c":3,"en":{"q":"What does a round yellow sign with an X and two R letters mean?","o":["A traffic circle is ahead","A bus stop is ahead","A rest area is ahead","A railroad crossing is ahead"],"h1":"The two letters stand for a kind of track.","h2":"The round yellow sign warns that a railroad crossing is ahead, so you should slow down, look, listen, and be ready to stop.","p":"Right. The round yellow sign warns of a railroad crossing ahead."},"es":{"q":"¿Qué significa una señal amarilla y redonda con una X y dos letras R?","o":["Hay una rotonda más adelante","Hay una parada de autobús más adelante","Hay un área de descanso más adelante","Hay un cruce de tren más adelante"],"h1":"Las dos letras se refieren a un tipo de vía.","h2":"La señal amarilla y redonda avisa que hay un cruce de tren más adelante, así que usted debe bajar la velocidad, mirar, escuchar y estar listo para parar.","p":"Correcto. La señal amarilla y redonda avisa de un cruce de tren."},"ref":{"doc":"FL","page":56}},{"id":"signs-005","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"At the tracks you see a white X-shaped sign. What should you do?","o":["Treat it like a yield sign and look for trains","Speed up to get across the tracks fast","Change lanes before you reach the tracks","Ignore it unless it is dark outside"],"h1":"Think about what could be coming down the tracks.","h2":"The white X sign is a railroad crossbuck, and it works like a yield sign, so you slow down, look both ways, and stop if a train is coming.","p":"Right. The crossbuck means yield to trains."},"es":{"q":"En la vía del tren ve una señal blanca en forma de X. ¿Qué debe hacer?","o":["Tratarla como un ceda el paso y buscar trenes","Acelerar para cruzar la vía rápido","Cambiar de carril antes de la vía","No hacerle caso a menos que sea de noche"],"h1":"Piense en lo que podría venir por la vía.","h2":"La señal blanca en forma de X es la cruz de ferrocarril, y funciona como un ceda el paso, así que usted baja la velocidad, mira a ambos lados y se para si viene un tren.","p":"Correcto. La cruz de ferrocarril significa ceder el paso a los trenes."},"ref":{"doc":"FL","page":56}},{"id":"signs-006","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow"},"c":1,"en":{"q":"What does a yellow diamond-shaped sign usually do?","o":["Gives you directions to a city","Warns you about a hazard or change ahead","Tells you the speed limit","Shows you a place to eat"],"h1":"Think about why a sign would use a bright yellow color.","h2":"A yellow diamond is a warning sign, so it tells you about a hazard or a change in the road ahead.","p":"Right. A yellow diamond warns you about something ahead."},"es":{"q":"¿Qué hace normalmente una señal amarilla en forma de rombo?","o":["Le da direcciones hacia una ciudad","Le avisa de un peligro o un cambio más adelante","Le dice el límite de velocidad","Le muestra un lugar para comer"],"h1":"Piense en por qué una señal usaría un amarillo fuerte.","h2":"Un rombo amarillo es una señal de advertencia, así que le avisa de un peligro o de un cambio en la vía más adelante.","p":"Correcto. Un rombo amarillo le avisa de algo más adelante."},"ref":{"doc":"FL","page":49}},{"id":"signs-007","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"Orange signs tell you about what?","o":["School zones","Parks and campgrounds","Road work and work zones","Gas and food"],"h1":"Think about where you see orange cones and workers.","h2":"Orange signs are used for road work and work zones, so you should slow down and watch for workers and changes.","p":"Right. Orange signs mean road work."},"es":{"q":"¿De qué le avisan las señales anaranjadas?","o":["De zonas escolares","De parques y campamentos","De obras y zonas de trabajo en la vía","De gasolina y comida"],"h1":"Piense en dónde ve conos anaranjados y trabajadores.","h2":"Las señales anaranjadas se usan para obras y zonas de trabajo en la vía, así que usted debe bajar la velocidad y estar atento a los trabajadores y a los cambios.","p":"Correcto. Las señales anaranjadas significan obras en la vía."},"ref":{"doc":"FL","page":46}},{"id":"signs-008","scope":"US","cat":"signs","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":3,"en":{"q":"What does a yellow sign shaped like a long, sideways triangle mean?","o":["A merge is ahead on the right","Trucks have the right of way","The road gets narrow ahead","A no-passing zone begins here"],"h1":"This is the only sign with this flag-like shape.","h2":"The sideways yellow triangle, called a pennant, means a no-passing zone begins, so you must not pass other cars here.","p":"Right. The pennant means no passing."},"es":{"q":"¿Qué significa una señal amarilla en forma de triángulo largo y acostado?","o":["Hay una incorporación más adelante a la derecha","Los camiones tienen el derecho de paso","La vía se hace angosta más adelante","Aquí empieza una zona donde no se puede rebasar"],"h1":"Es la única señal con esta forma de banderín.","h2":"El triángulo amarillo acostado, llamado banderín, significa que empieza una zona donde no se puede rebasar, así que usted no debe rebasar a otros carros aquí.","p":"Correcto. El banderín significa que no se puede rebasar."},"ref":{"doc":"FL","page":48}},{"id":"signs-009","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"On which side of the road is the no-passing pennant sign placed?","o":["The left side","The right side","Over the middle lane","Painted on the road"],"h1":"Think about where your eyes look when you plan to pass.","h2":"The no-passing pennant is placed on the left side of the road, because that is the side you look at when you think about passing.","p":"Right. The pennant is on the left side of the road."},"es":{"q":"¿En qué lado de la vía se pone la señal de banderín de no rebasar?","o":["En el lado izquierdo","En el lado derecho","Encima del carril del medio","Pintada en el pavimento"],"h1":"Piense hacia dónde mira cuando planea rebasar.","h2":"El banderín de no rebasar se pone en el lado izquierdo de la vía, porque ese es el lado que usted mira cuando piensa rebasar.","p":"Correcto. El banderín está en el lado izquierdo de la vía."}},{"id":"signs-010","scope":"US","cat":"signs","sign":{"shape":"rect-white"},"c":1,"en":{"q":"A white rectangle sign with black letters usually shows what?","o":["A warning about a curve","A traffic law you must obey","Directions to a city","A place to camp"],"h1":"Think about signs like the speed limit sign.","h2":"White rectangle signs with black letters are regulatory signs, so they show a traffic law that you must obey.","p":"Right. White rectangle signs show rules you must follow."},"es":{"q":"¿Qué muestra normalmente una señal blanca y rectangular con letras negras?","o":["Un aviso de una curva","Una ley de tránsito que debe obedecer","Direcciones hacia una ciudad","Un lugar para acampar"],"h1":"Piense en señales como la del límite de velocidad.","h2":"Las señales blancas y rectangulares con letras negras son señales reglamentarias, así que muestran una ley de tránsito que usted debe obedecer.","p":"Correcto. Las señales blancas rectangulares muestran reglas que debe seguir."},"ref":{"doc":"FL","page":46}},{"id":"signs-011","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"Orlando 25"},"c":2,"en":{"q":"What do green signs show you?","o":["Where the hospital is","Where road work starts","Directions and distances","Where a school zone is"],"h1":"Think about signs that help you find your way.","h2":"Green signs are guide signs, so they show directions, exits, and how far it is to places.","p":"Right. Green signs show directions and distances."},"es":{"q":"¿Qué le muestran las señales verdes?","o":["Dónde está el hospital","Dónde empiezan las obras","Direcciones y distancias","Dónde hay una zona escolar"],"h1":"Piense en señales que le ayudan a encontrar el camino.","h2":"Las señales verdes son señales de guía, así que muestran direcciones, salidas y qué tan lejos están los lugares.","p":"Correcto. Las señales verdes muestran direcciones y distancias."},"ref":{"doc":"FL","page":46}},{"id":"signs-012","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"GAS FOOD LODGING"},"c":3,"en":{"q":"What do blue signs along the road show?","o":["Speed laws","Road work","Parks and lakes","Services like gas, food, and lodging"],"h1":"Think about what you need on a long trip.","h2":"Blue signs show motorist services, so they point you to things like gas, food, lodging, and hospitals.","p":"Right. Blue signs show services like gas and food."},"es":{"q":"¿Qué muestran las señales azules en la carretera?","o":["Leyes de velocidad","Obras en la vía","Parques y lagos","Servicios como gasolina, comida y hospedaje"],"h1":"Piense en lo que necesita en un viaje largo.","h2":"Las señales azules muestran servicios para conductores, así que le indican lugares como gasolineras, comida, hospedaje y hospitales.","p":"Correcto. Las señales azules muestran servicios como gasolina y comida."},"ref":{"doc":"FL","page":46}},{"id":"signs-013","scope":"US","cat":"signs","sign":{"shape":"rect-brown","text":"STATE PARK"},"c":0,"en":{"q":"What do brown signs point you to?","o":["Parks, campgrounds, and places to visit","Gas stations and hotels","Exits and city names","Road work zones"],"h1":"Think about places you go for fun or nature.","h2":"Brown signs point to recreation and cultural places, such as parks, campgrounds, and historic sites.","p":"Right. Brown signs point to parks and places to visit."},"es":{"q":"¿Hacia dónde le indican las señales color café?","o":["Parques, campamentos y lugares para visitar","Gasolineras y hoteles","Salidas y nombres de ciudades","Zonas de obras"],"h1":"Piense en lugares a los que va para divertirse o estar en la naturaleza.","h2":"Las señales color café indican lugares de recreación y cultura, como parques, campamentos y sitios históricos.","p":"Correcto. Las señales color café indican parques y lugares para visitar."},"ref":{"doc":"FL","page":46}},{"id":"signs-014","scope":"US","cat":"signs","sign":{"shape":"do-not-enter","text":"DO NOT ENTER"},"c":1,"en":{"q":"What does a red circle with a white bar across it mean?","o":["Stop, then go when clear","Do not enter this road","Hospital ahead","Two-way traffic ahead"],"h1":"Think about a road where all the cars come toward you.","h2":"The red circle with a white bar means do not enter, because traffic on that road comes toward you.","p":"Right. The red circle with a white bar means do not enter."},"es":{"q":"¿Qué significa un círculo rojo con una barra blanca en el medio?","o":["Pararse y seguir cuando esté libre","No entre a esta vía","Hospital más adelante","Tráfico en dos sentidos más adelante"],"h1":"Piense en una vía donde todos los carros vienen hacia usted.","h2":"El círculo rojo con una barra blanca significa no entre, porque el tráfico en esa vía viene hacia usted.","p":"Correcto. El círculo rojo con barra blanca significa no entre."},"ref":{"doc":"FL","page":47}},{"id":"signs-015","scope":"US","cat":"signs","sign":{"shape":"wrong-way","text":"WRONG WAY"},"c":2,"en":{"q":"A red sign facing you says WRONG WAY. What should you do?","o":["Keep going with your hazard lights on","Speed up to reach the next exit","Pull over safely and turn around","Keep driving on the shoulder"],"h1":"The sign means you are going against traffic.","h2":"A WRONG WAY sign means you are driving against traffic, so you should pull over safely and turn around as soon as you can.","p":"Right. WRONG WAY means pull over safely and turn around."},"es":{"q":"Una señal roja frente a usted dice WRONG WAY (sentido contrario). ¿Qué debe hacer?","o":["Seguir con las luces de emergencia prendidas","Acelerar para llegar a la próxima salida","Orillarse con cuidado y dar la vuelta","Seguir manejando por el acotamiento"],"h1":"La señal quiere decir que usted va contra el tráfico.","h2":"Una señal de sentido contrario quiere decir que usted maneja contra el tráfico, así que debe orillarse con cuidado y dar la vuelta lo antes posible.","p":"Correcto. Sentido contrario significa orillarse con cuidado y dar la vuelta."},"ref":{"doc":"FL","page":47}},{"id":"signs-016","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":3,"en":{"q":"What does this sign tell you?","o":["The lowest speed you may drive","The speed you must always drive","A suggested speed for curves","The top legal speed in good conditions"],"h1":"Think about whether you may go faster, or slower.","h2":"A speed limit sign shows the highest legal speed when conditions are good, so you may need to drive slower in rain, fog, or heavy traffic.","p":"Right. The speed limit is the top speed in good conditions."},"es":{"q":"¿Qué le dice esta señal?","o":["La velocidad más baja permitida","La velocidad a la que siempre debe ir","Una velocidad sugerida para curvas","La velocidad máxima legal en buenas condiciones"],"h1":"Piense si puede ir más rápido o más despacio.","h2":"Una señal de límite de velocidad muestra la velocidad máxima legal cuando las condiciones son buenas, así que puede tener que ir más despacio con lluvia, neblina o mucho tráfico.","p":"Correcto. El límite es la velocidad máxima en buenas condiciones."},"ref":{"doc":"FL","page":47}},{"id":"signs-017","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONE WAY"},"c":1,"en":{"q":"What does a ONE WAY sign with an arrow mean?","o":["Only one lane is open ahead","Traffic moves only in the arrow's direction","Only one car may pass at a time","You may make only one turn"],"h1":"Look at where the arrow points.","h2":"A ONE WAY sign means all traffic on that street moves only in the direction of the arrow.","p":"Right. One way means drive only in the arrow's direction."},"es":{"q":"¿Qué significa una señal ONE WAY (un solo sentido) con una flecha?","o":["Solo hay un carril abierto más adelante","El tráfico va solo en la dirección de la flecha","Solo puede pasar un carro a la vez","Solo puede dar una vuelta"],"h1":"Mire hacia dónde apunta la flecha.","h2":"Una señal de un solo sentido quiere decir que todo el tráfico en esa calle va solo en la dirección de la flecha.","p":"Correcto. Un solo sentido significa manejar solo hacia donde apunta la flecha."},"ref":{"doc":"FL","page":48}},{"id":"signs-018","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO U-TURN"},"c":2,"en":{"q":"What does a NO U-TURN sign mean?","o":["You may not turn left here","You may not turn right here","You may not turn around here","You may not change lanes here"],"h1":"A U-turn makes the shape of the letter U.","h2":"A NO U-TURN sign means you may not turn your car around to go back the other way at that place.","p":"Right. No U-turn means you may not turn around here."},"es":{"q":"¿Qué significa una señal de NO U-TURN (prohibido dar vuelta en U)?","o":["No puede doblar a la izquierda aquí","No puede doblar a la derecha aquí","No puede dar la vuelta para regresar aquí","No puede cambiar de carril aquí"],"h1":"Una vuelta en U tiene la forma de la letra U.","h2":"Una señal de prohibido dar vuelta en U quiere decir que usted no puede dar la vuelta con su carro para regresar en ese lugar.","p":"Correcto. Prohibido vuelta en U significa que no puede dar la vuelta aquí."},"ref":{"doc":"FL","page":48}},{"id":"signs-019","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO TURN ON RED"},"c":3,"en":{"q":"What does a NO TURN ON RED sign mean?","o":["Turn right only after a full stop","Turn only when no cars are coming","Turn on red only at night","Wait for the green light before you turn"],"h1":"The sign changes what you may do while the light is red.","h2":"A NO TURN ON RED sign means you may not turn while the light is red, so you must wait for the green light.","p":"Right. No turn on red means wait for green."},"es":{"q":"¿Qué significa una señal de NO TURN ON RED (no doblar con luz roja)?","o":["Doblar a la derecha solo después de parar por completo","Doblar solo cuando no vengan carros","Doblar con luz roja solo de noche","Esperar la luz verde antes de doblar"],"h1":"La señal cambia lo que puede hacer mientras la luz está en rojo.","h2":"Una señal de no doblar con luz roja quiere decir que usted no puede doblar mientras la luz está en rojo, así que debe esperar la luz verde.","p":"Correcto. No doblar con luz roja significa esperar la luz verde."},"ref":{"doc":"FL","page":51}},{"id":"signs-020","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"KEEP RIGHT"},"c":0,"en":{"q":"A KEEP RIGHT sign stands at the front of a median. What does it mean?","o":["Stay to the right of the median or island","Move to the right lane to exit","The right lane ends ahead","Use the right lane only to pass"],"h1":"Think about which side of the median your car should go.","h2":"A KEEP RIGHT sign means you must drive on the right side of the median or island ahead.","p":"Right. Keep right means pass the median on its right side."},"es":{"q":"Una señal KEEP RIGHT (manténgase a la derecha) está al inicio de una isla. ¿Qué significa?","o":["Pasar por la derecha de la isla o el divisor","Cambiarse al carril derecho para salir","El carril derecho se termina más adelante","Usar el carril derecho solo para rebasar"],"h1":"Piense por qué lado de la isla debe pasar su carro.","h2":"Una señal de manténgase a la derecha quiere decir que usted debe pasar por el lado derecho de la isla o el divisor que está adelante.","p":"Correcto. Manténgase a la derecha significa pasar la isla por su lado derecho."},"ref":{"doc":"FL","page":48}},{"id":"signs-021","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONLY"},"c":1,"en":{"q":"A sign over your lane shows only a left arrow. What must you do?","o":["You may go straight or turn left","You must turn left from this lane","You may turn left or right","You must change lanes at the light"],"h1":"The arrows show what each lane is allowed to do.","h2":"When the sign over your lane shows only a left arrow, that lane is for left turns, so you must turn left.","p":"Right. A left-only arrow means you must turn left."},"es":{"q":"Una señal encima de su carril muestra solo una flecha a la izquierda. ¿Qué debe hacer?","o":["Puede seguir derecho o doblar a la izquierda","Debe doblar a la izquierda desde este carril","Puede doblar a la izquierda o a la derecha","Debe cambiar de carril en el semáforo"],"h1":"Las flechas muestran lo que se permite en cada carril.","h2":"Cuando la señal encima de su carril muestra solo una flecha a la izquierda, ese carril es para doblar a la izquierda, así que usted debe doblar a la izquierda.","p":"Correcto. Una flecha solo a la izquierda significa que debe doblar a la izquierda."},"ref":{"doc":"FL","page":47}},{"id":"signs-022","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"35 MPH"},"c":2,"en":{"q":"A curve warning sign has a small yellow sign below it with a speed. What is that speed?","o":["The lowest speed you may drive","The new speed limit for the road","A safe speed for the curve","A speed for trucks only"],"h1":"It is a yellow sign, not a white one.","h2":"The small yellow speed sign under a curve sign gives a safe speed for the curve in good conditions, so slow down to that speed or less.","p":"Right. The yellow speed plate gives a safe speed for the curve."},"es":{"q":"Una señal de curva tiene abajo una señal amarilla pequeña con una velocidad. ¿Qué es esa velocidad?","o":["La velocidad más baja permitida","El nuevo límite de velocidad de la vía","Una velocidad segura para la curva","Una velocidad solo para camiones"],"h1":"Es una señal amarilla, no blanca.","h2":"La señal amarilla pequeña debajo de una señal de curva le da una velocidad segura para la curva en buenas condiciones, así que baje a esa velocidad o menos.","p":"Correcto. La placa amarilla le da una velocidad segura para la curva."},"ref":{"doc":"FL","page":49}},{"id":"signs-023","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"MERGE"},"c":3,"en":{"q":"A yellow sign shows a side line joining the main road. What should you expect?","o":["A railroad crossing","A dead end","A stop sign ahead","Cars entering your road from the side"],"h1":"Think about two roads becoming one.","h2":"This merge sign warns that cars will enter your road from the side, so be ready to adjust your speed or make room.","p":"Right. The merge sign means cars will join your road."},"es":{"q":"Una señal amarilla muestra una línea lateral que se une a la vía principal. ¿Qué debe esperar?","o":["Un cruce de tren","Una calle sin salida","Una señal de pare más adelante","Carros que entran a su vía desde un lado"],"h1":"Piense en dos vías que se vuelven una.","h2":"Esta señal de incorporación avisa que entrarán carros a su vía desde un lado, así que esté listo para ajustar su velocidad o darles espacio.","p":"Correcto. La señal de incorporación significa que entrarán carros a su vía."},"ref":{"doc":"FL","page":49}},{"id":"signs-024","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"RIGHT LANE ENDS"},"c":0,"en":{"q":"You are in the right lane. A sign says RIGHT LANE ENDS. What should you do?","o":["Move left when it is safe","Speed up to stay ahead of others","Stop at the end of the lane","Drive on the shoulder"],"h1":"Your lane will soon be gone.","h2":"When the sign says your lane ends, you should signal and move into the next lane when it is safe.","p":"Right. When your lane ends, move over safely."},"es":{"q":"Usted va en el carril derecho. Una señal dice RIGHT LANE ENDS (el carril derecho termina). ¿Qué debe hacer?","o":["Pasarse a la izquierda cuando sea seguro","Acelerar para quedar delante de los demás","Pararse al final del carril","Manejar por el acotamiento"],"h1":"Su carril pronto desaparece.","h2":"Cuando la señal dice que su carril termina, usted debe poner la direccional y pasarse al otro carril cuando sea seguro.","p":"Correcto. Cuando su carril termina, cámbiese con cuidado."},"ref":{"doc":"FL","page":49}},{"id":"signs-025","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY"},"c":1,"en":{"q":"A warning sign says a divided highway begins. What changes ahead?","o":["The road comes to an end","A median will separate the two directions","The speed limit goes up","Two lanes become one lane"],"h1":"Think about what divides the road.","h2":"A divided highway begins sign means a median will soon separate traffic going each way, so keep to the right of it.","p":"Right. A median will separate the two directions."},"es":{"q":"Una señal de advertencia dice que empieza una carretera dividida. ¿Qué cambia más adelante?","o":["La vía se termina","Una isla o divisor va a separar los dos sentidos","El límite de velocidad sube","Dos carriles se vuelven uno"],"h1":"Piense en qué divide la vía.","h2":"La señal de que empieza una carretera dividida significa que pronto un divisor va a separar el tráfico de cada sentido, así que manténgase a la derecha de él.","p":"Correcto. Un divisor va a separar los dos sentidos."},"ref":{"doc":"FL","page":49}},{"id":"signs-026","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY ENDS"},"c":2,"en":{"q":"A sign says the divided highway ends. What should you expect?","o":["You may now pass on the right","The road becomes one-way","Cars coming toward you with no divider","A bridge is just ahead"],"h1":"Think about what happens when the median is gone.","h2":"When the divided highway ends, there is no median anymore, so cars going the other way will be right beside you and you must keep right.","p":"Right. With no divider, oncoming cars share the road with you."},"es":{"q":"Una señal dice que termina la carretera dividida. ¿Qué debe esperar?","o":["Ahora puede rebasar por la derecha","La vía se vuelve de un solo sentido","Carros que vienen de frente sin divisor","Un puente justo adelante"],"h1":"Piense en lo que pasa cuando ya no hay divisor.","h2":"Cuando termina la carretera dividida, ya no hay divisor, así que los carros que van en el otro sentido pasarán a su lado y usted debe mantenerse a la derecha.","p":"Correcto. Sin divisor, los carros de frente comparten la vía con usted."},"ref":{"doc":"FL","page":49}},{"id":"signs-027","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SLIPPERY WHEN WET"},"c":0,"en":{"q":"A sign says SLIPPERY WHEN WET. It is raining. What should you do?","o":["Slow down and avoid sudden moves","Turn on cruise control","Speed up to get past the area","Brake hard if the car slides"],"h1":"Think about how tires grip a wet road.","h2":"A wet road can be slick, so you should slow down and avoid quick turns or hard braking.","p":"Right. On a slippery road, slow down and move smoothly."},"es":{"q":"Una señal dice SLIPPERY WHEN WET (resbaloso cuando está mojado). Está lloviendo. ¿Qué debe hacer?","o":["Bajar la velocidad y evitar movimientos bruscos","Prender el control de velocidad","Acelerar para pasar rápido esa zona","Frenar fuerte si el carro resbala"],"h1":"Piense en cómo agarran las llantas en una vía mojada.","h2":"Una vía mojada puede estar resbalosa, así que usted debe bajar la velocidad y evitar vueltas rápidas o frenazos.","p":"Correcto. En una vía resbalosa, baje la velocidad y maneje con suavidad."},"ref":{"doc":"FL","page":50}},{"id":"signs-028","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SIGNAL AHEAD"},"c":1,"en":{"q":"A yellow sign shows a traffic light. What does it warn you about?","o":["A stop sign is ahead","A traffic signal is ahead","A railroad is ahead","A police checkpoint is ahead"],"h1":"Look at the picture on the sign.","h2":"This sign warns that a traffic signal is ahead, so be ready to slow down or stop.","p":"Right. The sign warns that a traffic light is ahead."},"es":{"q":"Una señal amarilla muestra un semáforo. ¿De qué le avisa?","o":["Hay una señal de pare más adelante","Hay un semáforo más adelante","Hay un tren más adelante","Hay un retén de policía más adelante"],"h1":"Mire el dibujo en la señal.","h2":"Esta señal avisa que hay un semáforo más adelante, así que esté listo para bajar la velocidad o pararse.","p":"Correcto. La señal avisa que hay un semáforo más adelante."},"ref":{"doc":"FL","page":49}},{"id":"signs-029","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DEER CROSSING"},"c":2,"en":{"q":"A yellow sign shows a deer. What should you do?","o":["Look for a nearby zoo","Pull over and wait","Watch for deer near or on the road","Speed up through the area"],"h1":"Animals may run onto the road with no warning.","h2":"A deer crossing sign means deer often cross there, so you should slow down and watch the sides of the road, especially at dawn and dusk.","p":"Right. Watch for deer near the road."},"es":{"q":"Una señal amarilla muestra un venado. ¿Qué debe hacer?","o":["Buscar un zoológico cerca","Orillarse y esperar","Estar atento a venados cerca o en la vía","Acelerar para pasar la zona"],"h1":"Los animales pueden salir a la vía sin aviso.","h2":"Una señal de cruce de venados quiere decir que los venados cruzan seguido por ahí, así que usted debe bajar la velocidad y mirar los lados de la vía, sobre todo al amanecer y al anochecer.","p":"Correcto. Esté atento a los venados cerca de la vía."},"ref":{"doc":"FL","page":50}},{"id":"signs-030","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"LOW CLEARANCE"},"c":3,"en":{"q":"A sign warns of LOW CLEARANCE ahead. What does it mean?","o":["The road gets narrow","The shoulder is soft","A steep hill is ahead","A low bridge or overpass is ahead"],"h1":"Clearance is the space above your vehicle.","h2":"A low clearance sign means a bridge or overpass ahead is low, so tall vehicles may not fit under it.","p":"Right. Low clearance means a low bridge or overpass is ahead."},"es":{"q":"Una señal avisa LOW CLEARANCE (altura baja) más adelante. ¿Qué significa?","o":["La vía se hace angosta","El acotamiento está blando","Hay una cuesta empinada","Hay un puente o paso elevado bajo"],"h1":"Piense en el espacio que hay encima de su vehículo.","h2":"Una señal de altura baja quiere decir que un puente o paso elevado más adelante es bajo, así que los vehículos altos podrían no caber.","p":"Correcto. Altura baja significa que hay un puente o paso elevado bajo."},"ref":{"doc":"FL","page":50}},{"id":"signs-031","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":0,"en":{"q":"You see a school crossing sign. What should you do?","o":["Slow down and watch for children","Honk to warn the children","Speed up to clear the area","Change lanes to go around"],"h1":"Children can be hard to see and may move fast.","h2":"A school crossing sign means children may be crossing, so you should slow down and be ready to stop.","p":"Right. At a school crossing, slow down and watch for children."},"es":{"q":"Usted ve una señal de cruce escolar. ¿Qué debe hacer?","o":["Bajar la velocidad y estar atento a los niños","Tocar la bocina para avisar a los niños","Acelerar para pasar la zona","Cambiar de carril para rodear"],"h1":"Los niños pueden ser difíciles de ver y moverse rápido.","h2":"Una señal de cruce escolar quiere decir que puede haber niños cruzando, así que usted debe bajar la velocidad y estar listo para parar.","p":"Correcto. En un cruce escolar, baje la velocidad y esté atento a los niños."},"ref":{"doc":"FL","page":57}},{"id":"signs-032","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT WHEN FLASHING"},"c":1,"en":{"q":"A school zone speed sign has yellow lights that are flashing. What does that mean?","o":["The lower speed is only a suggestion","The lower school speed limit is in effect now","School is closed today","Only school buses must slow down"],"h1":"The lights tell you when the sign applies.","h2":"When the lights on a school zone sign are flashing, the lower school speed limit is the law right now, so you must slow down to it.","p":"Right. Flashing lights mean the school speed limit applies now."},"es":{"q":"Una señal de velocidad en zona escolar tiene luces amarillas intermitentes. ¿Qué significa?","o":["La velocidad baja es solo una sugerencia","El límite escolar más bajo está vigente ahora","Hoy no hay clases","Solo los autobuses escolares deben ir más despacio"],"h1":"Las luces le dicen cuándo aplica la señal.","h2":"Cuando las luces de una señal de zona escolar están intermitentes, el límite escolar más bajo es la ley en ese momento, así que usted debe bajar a esa velocidad.","p":"Correcto. Las luces intermitentes significan que el límite escolar aplica ahora."},"ref":{"doc":"FL","page":57}},{"id":"signs-033","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":2,"en":{"q":"At a railroad crossing, the red lights are flashing. What must you do?","o":["Slow down and cross with care","Go if you do not see a train","Stop and wait until the lights stop","Drive around the gate"],"h1":"Flashing red lights at the tracks mean a train is coming.","h2":"Flashing red lights at a railroad crossing mean a train is near, so you must stop and wait until the lights stop flashing.","p":"Right. Flashing red lights at the tracks mean stop and wait."},"es":{"q":"En un cruce de tren, las luces rojas están intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y cruzar con cuidado","Seguir si no ve un tren","Pararse y esperar hasta que las luces se apaguen","Rodear la barrera"],"h1":"Las luces rojas intermitentes en la vía del tren significan que viene un tren.","h2":"Las luces rojas intermitentes en un cruce de tren quieren decir que un tren está cerca, así que usted debe pararse y esperar hasta que las luces dejen de parpadear.","p":"Correcto. Luces rojas intermitentes en la vía significan parar y esperar."},"ref":{"doc":"FL","page":56}},{"id":"signs-034","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"The railroad gates are down, but you do not see a train. What should you do?","o":["Drive around the gates if it looks clear","Cross slowly with hazard lights on","Use the other lane to get past","Stay stopped until the gates go up"],"h1":"A train can be closer and faster than it looks.","h2":"When the gates are down, a train is coming even if you cannot see it, so you must stay stopped until the gates go all the way up.","p":"Right. Never go around the gates. Wait until they go up."},"es":{"q":"Las barreras del tren están abajo, pero usted no ve ningún tren. ¿Qué debe hacer?","o":["Rodear las barreras si parece libre","Cruzar despacio con las luces de emergencia","Usar el otro carril para pasar","Quedarse parado hasta que suban las barreras"],"h1":"Un tren puede estar más cerca y venir más rápido de lo que parece.","h2":"Cuando las barreras están abajo, viene un tren aunque usted no lo vea, así que debe quedarse parado hasta que las barreras suban por completo.","p":"Correcto. Nunca rodee las barreras. Espere a que suban."},"ref":{"doc":"FL","page":56}},{"id":"signs-035","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"2 TRACKS"},"c":0,"en":{"q":"A small sign under the crossbuck says 2 TRACKS. What does it warn you about?","o":["After one train passes, another may come","Trains pass only two times a day","Two lanes of cars cross the tracks","You must wait two minutes to cross"],"h1":"Think about what could hide behind the first train.","h2":"The tracks sign tells you there is more than one track, so after one train passes you must look again, because a second train may be coming.","p":"Right. More than one track means another train may come."},"es":{"q":"Una señal pequeña debajo de la cruz de ferrocarril dice 2 TRACKS (2 vías). ¿De qué le avisa?","o":["Después de que pase un tren, puede venir otro","Los trenes pasan solo dos veces al día","Dos carriles de carros cruzan la vía","Debe esperar dos minutos para cruzar"],"h1":"Piense en lo que podría estar escondido detrás del primer tren.","h2":"La señal de vías le dice que hay más de una vía, así que después de que pase un tren usted debe volver a mirar, porque puede venir un segundo tren.","p":"Correcto. Más de una vía significa que puede venir otro tren."},"ref":{"doc":"FL","page":56}},{"id":"signs-036","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, when you must stop for a train, where should you stop?","o":["Right on top of the first rail","Between 15 and 50 feet from the nearest rail","At least 100 feet from the tracks","Anywhere you like before the crossing"],"h1":"You need space between you and the train, but not too much.","h2":"In Florida, you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail, so the train has room and you can still see it.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, cuando debe pararse por un tren, ¿dónde debe pararse?","o":["Justo encima del primer riel","Entre 15 y 50 pies del riel más cercano","Por lo menos a 100 pies de la vía","Donde quiera antes del cruce"],"h1":"Necesita espacio entre usted y el tren, pero no demasiado.","h2":"En Florida, usted debe pararse a no menos de 15 pies y no más de 50 pies del riel más cercano, para que el tren tenga espacio y usted todavía pueda verlo.","p":"Correcto. Párese entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"FL","page":56}},{"id":"signs-037","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"An orange sign says ROAD WORK AHEAD. What should you do?","o":["Find another road, this one is closed","Keep your speed, workers are done","Slow down and be ready for workers and changes","Speed up to get through the work fast"],"h1":"Think about people working near moving cars.","h2":"A road work sign means workers, equipment, or lane changes may be ahead, so you should slow down and pay close attention.","p":"Right. In road work, slow down and stay alert."},"es":{"q":"Una señal anaranjada dice ROAD WORK AHEAD (obras más adelante). ¿Qué debe hacer?","o":["Buscar otra vía, esta está cerrada","Mantener su velocidad, los trabajadores ya terminaron","Bajar la velocidad y estar listo para trabajadores y cambios","Acelerar para pasar las obras rápido"],"h1":"Piense en personas trabajando cerca de carros en movimiento.","h2":"Una señal de obras quiere decir que puede haber trabajadores, máquinas o cambios de carril más adelante, así que usted debe bajar la velocidad y poner mucha atención.","p":"Correcto. En zona de obras, baje la velocidad y esté alerta."},"ref":{"doc":"FL","page":54}},{"id":"signs-038","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds a STOP paddle toward you. What should you do?","o":["Slow down and drive around the flagger","Honk and keep going slowly","Stop only if workers are close to you","Stop and wait until the flagger lets you go"],"h1":"The flagger is directing traffic like a signal.","h2":"A flagger's STOP paddle has the same force as a stop sign, so you must stop and wait until the flagger signals you to go.","p":"Right. Obey the flagger and wait for the signal to go."},"es":{"q":"En una zona de obras, un banderero le muestra un letrero de STOP (pare). ¿Qué debe hacer?","o":["Bajar la velocidad y rodear al banderero","Tocar la bocina y seguir despacio","Pararse solo si hay trabajadores cerca","Pararse y esperar hasta que el banderero le deje pasar"],"h1":"El banderero dirige el tráfico como un semáforo.","h2":"El letrero de pare del banderero vale igual que una señal de pare, así que usted debe pararse y esperar hasta que el banderero le indique que siga.","p":"Correcto. Obedezca al banderero y espere su señal para seguir."},"ref":{"doc":"FL","page":54}},{"id":"signs-039","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"An orange sign says DETOUR. What does it mean?","o":["Follow the signs on a different route","The road is closed forever","Only trucks must leave the road","Park and wait for the road to open"],"h1":"A detour is a way around something.","h2":"A detour sign means the normal road is closed for now, so you follow the detour signs on another route.","p":"Right. Detour means follow the signs on another route."},"es":{"q":"Una señal anaranjada dice DETOUR (desvío). ¿Qué significa?","o":["Seguir las señales por otra ruta","La vía está cerrada para siempre","Solo los camiones deben salir de la vía","Estacionarse y esperar a que abran la vía"],"h1":"Un desvío es un camino para rodear algo.","h2":"Una señal de desvío quiere decir que la vía normal está cerrada por ahora, así que usted sigue las señales de desvío por otra ruta.","p":"Correcto. Desvío significa seguir las señales por otra ruta."}},{"id":"signs-040","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are there?","o":["It is cut in half","It is doubled","It stays the same","It becomes only a warning"],"h1":"Florida wants to protect the people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, because workers near traffic are at great risk.","p":"Right. Speeding fines double in a work zone with workers present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de obras cuando hay trabajadores?","o":["Se reduce a la mitad","Se duplica","Se queda igual","Se vuelve solo una advertencia"],"h1":"Florida quiere proteger a las personas que trabajan en la vía.","h2":"En Florida, la multa por exceso de velocidad en una zona de obras se duplica cuando hay trabajadores presentes, porque los trabajadores cerca del tráfico corren mucho peligro.","p":"Correcto. La multa por velocidad se duplica en zona de obras con trabajadores."},"ref":{"doc":"FL","page":29}},{"id":"signs-041","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":2,"en":{"q":"What kind of road does a blue and red shield with a number mark?","o":["A state park road","A private toll road","An Interstate highway","A county road"],"h1":"This shield is used across the whole country.","h2":"The blue and red shield marks an Interstate highway, which is part of the national highway system.","p":"Right. The blue and red shield marks an Interstate."},"es":{"q":"¿Qué tipo de vía marca un escudo azul y rojo con un número?","o":["Una vía de parque estatal","Una vía privada de peaje","Una autopista interestatal","Una vía del condado"],"h1":"Este escudo se usa en todo el país.","h2":"El escudo azul y rojo marca una autopista interestatal, que es parte del sistema nacional de carreteras.","p":"Correcto. El escudo azul y rojo marca una interestatal."}},{"id":"signs-042","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":3,"en":{"q":"Interstates with odd numbers, like I-95, usually run which way?","o":["East and west","In a loop around a city","Only inside one state","North and south"],"h1":"Odd and even numbers are used for two different directions.","h2":"Interstates with odd numbers usually run north and south, like I-95 along the east coast.","p":"Right. Odd numbers usually run north and south."},"es":{"q":"Las interestatales con número impar, como la I-95, ¿hacia dónde van normalmente?","o":["De este a oeste","En círculo alrededor de una ciudad","Solo dentro de un estado","De norte a sur"],"h1":"Los números pares e impares se usan para dos direcciones diferentes.","h2":"Las interestatales con número impar normalmente van de norte a sur, como la I-95 por la costa este.","p":"Correcto. Los números impares normalmente van de norte a sur."},"ref":{"doc":"FL","page":46}},{"id":"signs-043","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"10"},"c":0,"en":{"q":"I-10 has an even number. Which way does it usually run?","o":["East and west","North and south","Around a city","Along the coast only"],"h1":"Even and odd numbers go in different directions.","h2":"Interstates with even numbers usually run east and west, like I-10 across north Florida.","p":"Right. Even numbers usually run east and west."},"es":{"q":"La I-10 tiene un número par. ¿Hacia dónde va normalmente?","o":["De este a oeste","De norte a sur","Alrededor de una ciudad","Solo por la costa"],"h1":"Los números pares e impares van en direcciones distintas.","h2":"Las interestatales con número par normalmente van de este a oeste, como la I-10 por el norte de Florida.","p":"Correcto. Los números pares normalmente van de este a oeste."},"ref":{"doc":"FL","page":46}},{"id":"signs-045","scope":"FL","cat":"signs","sign":{"shape":"rect-green","text":"EXIT"},"c":2,"en":{"q":"In Florida, how are exit numbers on Interstates chosen?","o":["In order, 1, 2, 3, from the state line","By the name of the nearest city","By the nearest mile marker","By the number of the crossing road"],"h1":"Think about the small green signs that count the miles.","h2":"In Florida, Interstate exit numbers match the nearest mile marker, so the exit number also tells you about how far you are along the road.","p":"Right. Florida exit numbers follow the mile markers."},"es":{"q":"En Florida, ¿cómo se escogen los números de salida en las interestatales?","o":["En orden, 1, 2, 3, desde la frontera del estado","Por el nombre de la ciudad más cercana","Por el marcador de milla más cercano","Por el número de la vía que cruza"],"h1":"Piense en las señales verdes pequeñas que cuentan las millas.","h2":"En Florida, los números de salida en las interestatales corresponden al marcador de milla más cercano, así que el número de salida también le dice más o menos qué tan lejos va en la vía.","p":"Correcto. En Florida, los números de salida siguen los marcadores de milla."},"ref":{"doc":"FL","page":46}},{"id":"signs-046","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"MILE 120"},"c":3,"en":{"q":"How do small green mile marker signs help you?","o":["They show the speed limit","They point to gas stations","They tell you where to pay tolls","They tell your location in an emergency"],"h1":"Think about what you would tell a 911 operator.","h2":"Mile markers show where you are on the highway, so you can tell emergency helpers your exact location.","p":"Right. Mile markers help you tell where you are."},"es":{"q":"¿Cómo le ayudan las señales verdes pequeñas de marcador de milla?","o":["Muestran el límite de velocidad","Indican dónde hay gasolineras","Le dicen dónde pagar el peaje","Le ayudan a decir dónde está en una emergencia"],"h1":"Piense en lo que le diría a la operadora del 911.","h2":"Los marcadores de milla muestran dónde está usted en la carretera, así que puede decirle a la ayuda de emergencia su ubicación exacta.","p":"Correcto. Los marcadores de milla le ayudan a decir dónde está."},"ref":{"doc":"FL","page":46}},{"id":"signs-047","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"H"},"c":0,"en":{"q":"A blue sign shows a big white letter H. What does it mean?","o":["A hospital is nearby","A hotel is nearby","A helicopter pad is nearby","The highway ends here"],"h1":"Blue signs show services you may need.","h2":"A blue sign with a white H points to a hospital, so you can find medical help nearby.","p":"Right. The blue H sign means a hospital is near."},"es":{"q":"Una señal azul muestra una letra H grande y blanca. ¿Qué significa?","o":["Hay un hospital cerca","Hay un hotel cerca","Hay un helipuerto cerca","La autopista termina aquí"],"h1":"Las señales azules muestran servicios que podría necesitar.","h2":"Una señal azul con una H blanca indica un hospital, así que usted puede encontrar ayuda médica cerca.","p":"Correcto. La señal azul con H significa que hay un hospital cerca."},"ref":{"doc":"FL","page":46}},{"id":"signs-048","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"On traffic signs, what does the color red usually mean?","o":["A warning about the road ahead","Stop, yield, or something is not allowed","Directions to a place","Services like gas and food"],"h1":"Think of the stop sign and the do not enter sign.","h2":"Red on a sign usually means stop, yield, or that something is not allowed, like on the stop sign and the do not enter sign.","p":"Right. Red means stop, yield, or not allowed."},"es":{"q":"En las señales de tránsito, ¿qué significa normalmente el color rojo?","o":["Un aviso sobre la vía más adelante","Pare, ceda el paso o algo no está permitido","Direcciones hacia un lugar","Servicios como gasolina y comida"],"h1":"Piense en la señal de pare y en la de no entre.","h2":"El rojo en una señal normalmente quiere decir pare, ceda el paso o que algo no está permitido, como en la señal de pare y la de no entre.","p":"Correcto. El rojo significa pare, ceda el paso o no está permitido."},"ref":{"doc":"FL","page":46}},{"id":"signs-049","scope":"US","cat":"signs","sign":null,"c":2,"en":{"q":"A bright yellow-green sign shows a person walking. What should you watch for?","o":["People on bicycles only","Animals crossing","People crossing the road","Road workers"],"h1":"Look at the picture on the sign.","h2":"A yellow-green sign with a walking person warns that people may be crossing the road, so slow down and be ready to stop for them.","p":"Right. Watch for people crossing the road."},"es":{"q":"Una señal verde amarillenta brillante muestra a una persona caminando. ¿A qué debe estar atento?","o":["Solo a personas en bicicleta","A animales cruzando","A personas cruzando la vía","A trabajadores de la vía"],"h1":"Mire el dibujo en la señal.","h2":"Una señal verde amarillenta con una persona caminando avisa que puede haber personas cruzando la vía, así que baje la velocidad y esté listo para pararse por ellas.","p":"Correcto. Esté atento a personas cruzando la vía."},"ref":{"doc":"FL","page":46}},{"id":"speed-lanes-001","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, what is the speed limit in a business or residential area when no sign says otherwise?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Think of streets with homes and shops, where people walk a lot.","h2":"The speed limit in a Florida business or residential area is 30 mph unless a sign shows a different limit.","p":"Right. Business and residential areas in Florida are 30 mph unless posted."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una zona comercial o residencial si no hay letrero que diga otra cosa?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Piense en calles con casas y tiendas, donde camina mucha gente.","h2":"El límite de velocidad en una zona comercial o residencial de Florida es 30 mph, a menos que un letrero indique otro límite.","p":"Correcto. En Florida, las zonas comerciales y residenciales son de 30 mph si no hay otro letrero."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-002","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, what is the highest speed limit allowed on a rural interstate highway?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"This is the fastest limit you will see on any Florida road.","h2":"The top speed limit on a Florida rural interstate is 70 mph, and you must still follow the posted sign.","p":"Right. Rural interstates in Florida can be posted up to 70 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad más alto permitido en una autopista interestatal rural?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Es el límite más alto que verá en cualquier carretera de Florida.","h2":"El límite más alto en una interestatal rural de Florida es 70 mph, y siempre debe seguir el letrero que esté puesto.","p":"Correcto. Las interestatales rurales de Florida pueden tener un límite de hasta 70 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-003","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, what is the speed limit on a highway outside a city when no sign is posted?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"It is lower than the interstate limit, but higher than city streets.","h2":"When no speed limit sign is posted on a Florida highway outside a city, the limit is 55 mph.","p":"Right. With no sign on other Florida highways, the limit is 55 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una carretera fuera de la ciudad cuando no hay letrero?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Es más bajo que en la interestatal, pero más alto que en las calles de la ciudad.","h2":"Cuando no hay letrero de límite en una carretera de Florida fuera de la ciudad, el límite es 55 mph.","p":"Correcto. Sin letrero en otras carreteras de Florida, el límite es 55 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-004","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, on an interstate where the speed limit is 70 mph, what is the lowest speed you may drive in good conditions?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Driving too slow on a fast road is also unsafe. There is a minimum.","h2":"On a Florida interstate posted at 70 mph, the minimum speed is 50 mph when the weather and traffic are normal.","p":"Right. The minimum speed on a 70 mph Florida interstate is 50 mph."},"es":{"q":"En Florida, en una interestatal con límite de 70 mph, ¿cuál es la velocidad más baja permitida con buenas condiciones?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Manejar muy despacio en una vía rápida también es peligroso. Hay un mínimo.","h2":"En una interestatal de Florida con límite de 70 mph, la velocidad mínima es 50 mph cuando el clima y el tráfico son normales.","p":"Correcto. La velocidad mínima en una interestatal de Florida de 70 mph es 50 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-005","scope":"FL","cat":"speed-lanes","sign":{"shape":"school","text":"SCHOOL"},"c":1,"en":{"q":"In Florida, when must you obey the lower speed limit in a school zone?","o":["Only when you see children on the road","When the lights flash or during the times shown on the sign","Only on Monday mornings","Only when a police car is nearby"],"h1":"Look at the sign. It tells you when the lower limit is active.","h2":"You must obey the school zone speed limit when its lights are flashing or during the hours shown on the sign, even if you do not see children.","p":"Right. Follow the school zone limit when the lights flash or during the posted times."},"es":{"q":"En Florida, ¿cuándo debe respetar el límite de velocidad más bajo en una zona escolar?","o":["Solo cuando ve niños en la calle","Cuando las luces parpadean o en las horas que indica el letrero","Solo los lunes por la mañana","Solo cuando hay un carro de policía cerca"],"h1":"Mire el letrero. Le dice cuándo aplica el límite más bajo.","h2":"Debe respetar el límite de la zona escolar cuando las luces parpadean o en las horas que indica el letrero, aunque no vea niños.","p":"Correcto. Respete el límite escolar cuando las luces parpadean o en las horas indicadas."},"ref":{"doc":"FL","page":57}},{"id":"speed-lanes-006","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is raining hard and you are on a road posted at 55 mph. How fast should you drive?","o":["Exactly 55 mph, because that is the limit","A little faster than 55 mph to get out of the rain","Any speed, because rain does not change the rules","Slower than 55 mph, at a speed that is safe for the rain"],"h1":"A speed limit is the most you may drive in good conditions.","h2":"You must never drive faster than is safe for the conditions, so in heavy rain you should drive slower than the posted 55 mph.","p":"Right. In bad weather, slow down below the limit to a safe speed."},"es":{"q":"En Florida, está lloviendo fuerte y usted va por una carretera con límite de 55 mph. ¿A qué velocidad debe manejar?","o":["Exactamente a 55 mph, porque ese es el límite","Un poco más rápido que 55 mph para salir de la lluvia","A cualquier velocidad, porque la lluvia no cambia las reglas","Más despacio que 55 mph, a una velocidad segura para la lluvia"],"h1":"El límite de velocidad es lo máximo que puede manejar con buenas condiciones.","h2":"Nunca debe manejar más rápido de lo que es seguro para las condiciones, así que con lluvia fuerte debe ir más despacio que 55 mph.","p":"Correcto. Con mal clima, baje la velocidad por debajo del límite a una velocidad segura."},"ref":{"doc":"FL","page":null}},{"id":"speed-lanes-007","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you get a ticket for driving too slowly?","o":["Yes, if you block the normal flow of traffic","No, driving slowly is always legal","Only if you drive slower than 10 mph","Only on dirt roads"],"h1":"Think about what happens to the cars behind a very slow driver.","h2":"Yes. In Florida you can get a ticket if you drive so slowly that you block the normal and safe flow of traffic.","p":"Right. Driving so slowly that you block traffic is against the law."},"es":{"q":"En Florida, ¿le pueden dar una multa por manejar demasiado despacio?","o":["Sí, si bloquea el flujo normal del tráfico","No, manejar despacio siempre es legal","Solo si maneja a menos de 10 mph","Solo en caminos de tierra"],"h1":"Piense en lo que les pasa a los carros que van detrás de alguien muy lento.","h2":"Sí. En Florida le pueden poner una multa si maneja tan despacio que bloquea el flujo normal y seguro del tráfico.","p":"Correcto. Manejar tan despacio que bloquea el tráfico va contra la ley."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-008","scope":"US","cat":"speed-lanes","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":2,"en":{"q":"What does this white sign tell you?","o":["You must drive exactly 55 mph","The slowest speed allowed is 55 mph","The fastest speed allowed in good conditions is 55 mph","The suggested speed for a curve is 55 mph"],"h1":"White signs with black letters are rules. Is this number a top or a bottom?","h2":"A white speed limit sign shows the highest legal speed when conditions are good, so you may not drive faster than 55 mph there.","p":"Right. The speed limit sign shows the top legal speed in good conditions."},"es":{"q":"¿Qué le indica este letrero blanco?","o":["Debe manejar exactamente a 55 mph","La velocidad más baja permitida es 55 mph","La velocidad más alta permitida con buenas condiciones es 55 mph","La velocidad sugerida para una curva es 55 mph"],"h1":"Los letreros blancos con letras negras son reglas. ¿Este número es un máximo o un mínimo?","h2":"Un letrero blanco de límite de velocidad muestra la velocidad legal más alta con buenas condiciones, así que no puede manejar a más de 55 mph allí.","p":"Correcto. El letrero de límite muestra la velocidad legal más alta con buenas condiciones."},"ref":{"doc":"FL","page":47}},{"id":"speed-lanes-009","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"What is a good way to check if you are following too closely?","o":["Count the car lengths in your mirror","Watch the speed of the car behind you","Count the seconds after the car ahead passes a fixed object","Check if you can read the license plate ahead"],"h1":"Pick something that does not move, like a sign or a pole.","h2":"When the car ahead passes a fixed object, count the seconds until you reach it, and if you reach it too soon, you are following too closely.","p":"Right. Counting seconds past a fixed object shows your following distance."},"es":{"q":"¿Cuál es una buena forma de saber si va demasiado cerca del carro de adelante?","o":["Contar los largos de carro en el espejo","Mirar la velocidad del carro que va detrás","Contar los segundos después de que el carro de adelante pasa un objeto fijo","Ver si puede leer la placa del carro de adelante"],"h1":"Escoja algo que no se mueva, como un letrero o un poste.","h2":"Cuando el carro de adelante pasa un objeto fijo, cuente los segundos hasta que usted llegue allí; si llega muy pronto, va demasiado cerca.","p":"Correcto. Contar segundos desde un objeto fijo muestra su distancia de seguimiento."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-010","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"When should you leave more space between you and the car ahead?","o":["When the road is wet or slippery","When the road is dry and clear","When you are driving slower than usual in town","When the car ahead is a small car"],"h1":"Think about when your car needs more distance to stop.","h2":"You should leave more space when the road is wet or slippery, because your car needs a longer distance to stop.","p":"Right. On wet or slippery roads, leave extra space ahead."},"es":{"q":"¿Cuándo debe dejar más espacio entre usted y el carro de adelante?","o":["Cuando la carretera está mojada o resbalosa","Cuando la carretera está seca y despejada","Cuando maneja más despacio de lo normal en la ciudad","Cuando el carro de adelante es pequeño"],"h1":"Piense en cuándo su carro necesita más distancia para frenar.","h2":"Debe dejar más espacio cuando la carretera está mojada o resbalosa, porque su carro necesita más distancia para detenerse.","p":"Correcto. En carretera mojada o resbalosa, deje más espacio adelante."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-011","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Your total stopping distance is made of which parts?","o":["Only the distance you travel while braking","Only the time it takes you to see the danger","The length of your car plus one car length","The distance you travel while you notice, react, and brake"],"h1":"Your car keeps moving before your foot even touches the brake.","h2":"Total stopping distance includes the distance you travel while you see the danger, while you move your foot, and while the brakes slow the car.","p":"Right. Stopping distance adds noticing, reacting, and braking."},"es":{"q":"¿De qué partes se forma la distancia total para detenerse?","o":["Solo la distancia que recorre mientras frena","Solo el tiempo que tarda en ver el peligro","El largo de su carro más el largo de otro carro","La distancia que recorre mientras nota el peligro, reacciona y frena"],"h1":"Su carro sigue avanzando antes de que su pie toque el freno.","h2":"La distancia total para detenerse incluye lo que recorre mientras ve el peligro, mientras mueve el pie y mientras los frenos paran el carro.","p":"Correcto. La distancia para detenerse suma notar, reaccionar y frenar."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-012","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"If you drive twice as fast, what happens to the distance your brakes need to stop the car?","o":["It stays the same","It becomes about four times longer","It becomes about two times longer","It becomes shorter"],"h1":"Speed makes stopping harder very quickly, not just a little.","h2":"When your speed doubles, your braking distance becomes about four times longer, because the car carries much more energy.","p":"Right. Double the speed means about four times the braking distance."},"es":{"q":"Si maneja al doble de velocidad, ¿qué pasa con la distancia que necesitan los frenos para parar el carro?","o":["Se queda igual","Se vuelve unas cuatro veces más larga","Se vuelve unas dos veces más larga","Se vuelve más corta"],"h1":"La velocidad hace que frenar sea mucho más difícil, no solo un poco.","h2":"Cuando su velocidad se duplica, la distancia de frenado se vuelve unas cuatro veces más larga, porque el carro lleva mucha más energía.","p":"Correcto. El doble de velocidad significa unas cuatro veces la distancia de frenado."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-013","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"A driver is following very close behind you. What is the safest thing to do?","o":["Tap your brakes hard to warn the driver","Leave more space ahead of you and let the driver pass","Speed up to get away from the driver","Stop in your lane until the driver goes around"],"h1":"If you must stop suddenly, the driver behind may hit you. How can you avoid sudden stops?","h2":"The safest choice is to leave extra space ahead of you, so you can slow down gently, and to let the close driver pass.","p":"Right. Give yourself more space ahead and let a tailgater pass."},"es":{"q":"Un conductor va muy pegado detrás de usted. ¿Qué es lo más seguro?","o":["Frenar fuerte para avisarle al conductor","Dejar más espacio adelante y dejar que el conductor lo rebase","Acelerar para alejarse del conductor","Detenerse en su carril hasta que el conductor lo rodee"],"h1":"Si tiene que frenar de golpe, el de atrás puede chocarlo. ¿Cómo puede evitar frenadas de golpe?","h2":"Lo más seguro es dejar más espacio adelante para poder frenar suavemente, y dejar que el conductor que va pegado lo rebase.","p":"Correcto. Deje más espacio adelante y deje que el conductor pegado lo rebase."}},{"id":"speed-lanes-014","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, on a two-lane road, how close to an intersection or railroad crossing may you pass another car?","o":["Not within 25 feet","Not within 50 feet","Passing is allowed right up to it","Not within 100 feet"],"h1":"Cars and trains may enter the road there. You need a clear stretch.","h2":"In Florida you may not pass on a two-lane road within 100 feet of an intersection or a railroad crossing, because traffic may enter or stop there.","p":"Right. Do not pass within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Florida, en una carretera de dos carriles, ¿qué tan cerca de una intersección o un cruce de tren puede rebasar a otro carro?","o":["No a menos de 25 pies","No a menos de 50 pies","Se puede rebasar hasta llegar allí","No a menos de 100 pies"],"h1":"Allí pueden entrar carros o trenes. Necesita un tramo despejado.","h2":"En Florida no puede rebasar en una carretera de dos carriles a menos de 100 pies de una intersección o de un cruce de tren, porque el tráfico puede entrar o detenerse allí.","p":"Correcto. No rebase a menos de 100 pies de una intersección o un cruce de tren."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-015","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, when may you pass another car on the right?","o":["When the car ahead is turning left and there is a lane to pass in","When the car ahead is going a little slow on a two-lane road","When you can use the paved shoulder","Whenever the left lane is busy"],"h1":"You must stay on the road itself, not on the shoulder.","h2":"You may pass on the right when the car ahead is turning left and there is a full lane for you, but you may never drive on the shoulder to pass.","p":"Right. Pass on the right only with a real lane, like when a car is turning left."},"es":{"q":"En Florida, ¿cuándo puede rebasar a otro carro por la derecha?","o":["Cuando el carro de adelante va a girar a la izquierda y hay un carril para rebasar","Cuando el carro de adelante va un poco lento en una carretera de dos carriles","Cuando puede usar el acotamiento pavimentado","Siempre que el carril izquierdo esté ocupado"],"h1":"Debe quedarse en la vía, no en el acotamiento.","h2":"Puede rebasar por la derecha cuando el carro de adelante va a girar a la izquierda y hay un carril completo para usted, pero nunca puede usar el acotamiento para rebasar.","p":"Correcto. Rebase por la derecha solo si hay un carril de verdad, como cuando un carro gira a la izquierda."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-016","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, another car is passing you. What should you do?","o":["Speed up so the other car cannot pass","Move to the left to block the other car","Stay in your lane and do not speed up","Brake hard to let the other car in"],"h1":"Make it easy and safe for the other driver to finish passing.","h2":"When another car passes you, you must stay in your lane and not speed up, so the other driver can finish passing safely.","p":"Right. When someone passes you, keep your lane and do not speed up."},"es":{"q":"En Florida, otro carro lo está rebasando. ¿Qué debe hacer?","o":["Acelerar para que el otro carro no lo rebase","Moverse a la izquierda para bloquear al otro carro","Quedarse en su carril y no acelerar","Frenar fuerte para dejar entrar al otro carro"],"h1":"Hágale fácil y seguro al otro conductor terminar de rebasar.","h2":"Cuando otro carro lo rebasa, debe quedarse en su carril y no acelerar, para que el otro conductor termine de rebasar con seguridad.","p":"Correcto. Cuando alguien lo rebasa, quédese en su carril y no acelere."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-017","scope":"US","cat":"speed-lanes","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":2,"en":{"q":"What does this yellow pennant-shaped sign mean?","o":["A school zone starts here","The road ends ahead","A no-passing zone starts here","You may pass on the right"],"h1":"This sign is on the left side of the road, where drivers look before they pass.","h2":"The yellow pennant sign marks the start of a no-passing zone, so you may not pass other cars from that point.","p":"Right. The pennant sign shows where a no-passing zone begins."},"es":{"q":"¿Qué significa este letrero amarillo en forma de banderín?","o":["Aquí empieza una zona escolar","La carretera termina más adelante","Aquí empieza una zona donde no se puede rebasar","Puede rebasar por la derecha"],"h1":"Este letrero está al lado izquierdo de la carretera, donde miran los conductores antes de rebasar.","h2":"El letrero amarillo en forma de banderín marca el inicio de una zona donde no se puede rebasar, así que desde allí no puede rebasar a otros carros.","p":"Correcto. El banderín muestra dónde empieza la zona sin rebase."},"ref":{"doc":"FL","page":48}},{"id":"speed-lanes-018","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"There is a solid yellow line on your side of the center line. What does it mean?","o":["You may not pass","You may pass when it is safe","The road is one-way","You must stop ahead"],"h1":"Look closely: is the line on your side broken or solid?","h2":"A solid yellow line on your side of the center means you may not cross it to pass other cars.","p":"Right. A solid yellow line on your side means no passing."},"es":{"q":"Hay una línea amarilla continua de su lado de la línea central. ¿Qué significa?","o":["No puede rebasar","Puede rebasar cuando sea seguro","La calle es de un solo sentido","Debe detenerse más adelante"],"h1":"Mire bien: ¿la línea de su lado es cortada o continua?","h2":"Una línea amarilla continua de su lado de la línea central significa que no puede cruzarla para rebasar a otros carros.","p":"Correcto. Una línea amarilla continua de su lado significa que no puede rebasar."},"ref":{"doc":"FL","page":44}},{"id":"speed-lanes-019","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn must you start using your turn signal?","o":["At least 25 feet","At least 50 feet","Only when you begin to turn","At least 100 feet"],"h1":"Give other drivers enough warning before you move.","h2":"In Florida you must turn on your signal at least 100 feet before you turn, so other drivers know what you plan to do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de girar?","o":["Al menos 25 pies antes","Al menos 50 pies antes","Solo cuando empieza a girar","Al menos 100 pies antes"],"h1":"Avise a los demás conductores con suficiente tiempo antes de moverse.","h2":"En Florida debe poner la direccional al menos 100 pies antes de girar, para que los demás sepan lo que va a hacer.","p":"Correcto. Ponga la direccional al menos 100 pies antes de girar."},"ref":{"doc":"FL","page":69}},{"id":"speed-lanes-020","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You want to change lanes. What should you do right after checking your mirrors?","o":["Change lanes right away","Turn your head and look over your shoulder","Honk your horn","Slow down to a stop"],"h1":"Your mirrors cannot show every place next to your car.","h2":"After you check your mirrors, turn your head and look over your shoulder, because a car may be hiding in your blind spot.","p":"Right. Look over your shoulder to check your blind spot."},"es":{"q":"Quiere cambiar de carril. ¿Qué debe hacer justo después de revisar los espejos?","o":["Cambiar de carril enseguida","Voltear la cabeza y mirar por encima del hombro","Tocar la bocina","Frenar hasta detenerse"],"h1":"Los espejos no muestran todos los lugares al lado de su carro.","h2":"Después de revisar los espejos, voltee la cabeza y mire por encima del hombro, porque puede haber un carro escondido en su punto ciego.","p":"Correcto. Mire por encima del hombro para revisar su punto ciego."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-021","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You need to move over three lanes to reach your exit. How should you do it?","o":["Cross all three lanes in one move","Move one lane at a time and signal each time","Signal once and then cross all lanes","Slow down in your lane and wait for a gap in all lanes"],"h1":"Each lane may have its own traffic and its own blind spot.","h2":"You should move one lane at a time, signaling and checking your blind spot before each move, because every lane can hide a car.","p":"Right. Change one lane at a time and signal each time."},"es":{"q":"Necesita pasar tres carriles para llegar a su salida. ¿Cómo debe hacerlo?","o":["Cruzar los tres carriles de una sola vez","Cambiar un carril a la vez y poner la direccional cada vez","Poner la direccional una vez y cruzar todos los carriles","Frenar en su carril y esperar un espacio en todos los carriles"],"h1":"Cada carril puede tener su propio tráfico y su propio punto ciego.","h2":"Debe cambiar un carril a la vez, poniendo la direccional y revisando el punto ciego antes de cada cambio, porque en cada carril puede haber un carro.","p":"Correcto. Cambie un carril a la vez y ponga la direccional cada vez."}},{"id":"speed-lanes-022","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"What do broken white lines between lanes mean?","o":["They separate traffic going in opposite directions","You may never cross them","They mark the edge of the road","They separate lanes going the same way, and you may change lanes when safe"],"h1":"Broken lines allow you to do something, but only when it is safe.","h2":"Broken white lines separate lanes that go the same way, and you may cross them to change lanes when it is safe.","p":"Right. Broken white lines let you change lanes when it is safe."},"es":{"q":"¿Qué significan las líneas blancas cortadas entre carriles?","o":["Separan el tráfico que va en sentidos opuestos","Nunca las puede cruzar","Marcan la orilla de la carretera","Separan carriles que van en el mismo sentido, y puede cambiar de carril cuando sea seguro"],"h1":"Las líneas cortadas le permiten hacer algo, pero solo cuando es seguro.","h2":"Las líneas blancas cortadas separan carriles que van en el mismo sentido, y puede cruzarlas para cambiar de carril cuando sea seguro.","p":"Correcto. Las líneas blancas cortadas le permiten cambiar de carril cuando es seguro."},"ref":{"doc":"FL","page":43}},{"id":"speed-lanes-023","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you are on the ramp to enter an expressway. What should you do?","o":["Speed up in the merge lane to match traffic and yield to cars on the expressway","Stop at the end of the ramp and wait","Drive slowly so cars on the expressway can see you","Enter right away, because cars on the expressway must let you in"],"h1":"The merge lane is there to help you reach the speed of traffic.","h2":"Use the merge lane to speed up to the speed of traffic, and yield to the cars already on the expressway before you move in.","p":"Right. Match the traffic speed and yield to cars already on the expressway."},"es":{"q":"En Florida, usted va por la rampa para entrar a una autopista. ¿Qué debe hacer?","o":["Acelerar en el carril de incorporación hasta la velocidad del tráfico y ceder el paso a los carros de la autopista","Detenerse al final de la rampa y esperar","Manejar despacio para que los carros de la autopista lo vean","Entrar enseguida, porque los carros de la autopista deben dejarlo pasar"],"h1":"El carril de incorporación sirve para que alcance la velocidad del tráfico.","h2":"Use el carril de incorporación para acelerar hasta la velocidad del tráfico, y ceda el paso a los carros que ya van por la autopista antes de entrar.","p":"Correcto. Iguale la velocidad del tráfico y ceda el paso a los carros de la autopista."},"ref":{"doc":"FL","page":63}},{"id":"speed-lanes-024","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, where should you slow down when you leave an expressway?","o":["In the main lane, before the exit","On the shoulder next to the exit","In the exit lane, after you leave the main lanes","Only after you reach the end of the ramp"],"h1":"Slowing down in the main lanes can surprise the drivers behind you.","h2":"You should move into the exit lane first and then slow down there, so you do not block fast traffic in the main lanes.","p":"Right. Slow down in the exit lane, not on the main road."},"es":{"q":"En Florida, ¿dónde debe bajar la velocidad al salir de una autopista?","o":["En el carril principal, antes de la salida","En el acotamiento junto a la salida","En el carril de salida, después de dejar los carriles principales","Solo al llegar al final de la rampa"],"h1":"Frenar en los carriles principales puede sorprender a los conductores de atrás.","h2":"Primero debe pasarse al carril de salida y luego bajar la velocidad allí, para no frenar al tráfico rápido en los carriles principales.","p":"Correcto. Baje la velocidad en el carril de salida, no en la vía principal."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-025","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You missed your exit on the expressway. What should you do?","o":["Back up on the shoulder to the exit","Make a U-turn across the median","Keep going to the next exit","Stop and wait for traffic to clear"],"h1":"Backing up or turning around on a fast road is very dangerous.","h2":"If you miss your exit, keep driving to the next exit, because backing up or turning around on an expressway can cause a serious crash.","p":"Right. Missed your exit? Just go on to the next one."},"es":{"q":"Se le pasó la salida en la autopista. ¿Qué debe hacer?","o":["Dar reversa por el acotamiento hasta la salida","Dar vuelta en U por la división central","Seguir hasta la próxima salida","Detenerse y esperar a que pase el tráfico"],"h1":"Dar reversa o dar la vuelta en una vía rápida es muy peligroso.","h2":"Si se le pasa la salida, siga hasta la próxima salida, porque dar reversa o dar la vuelta en una autopista puede causar un choque grave.","p":"Correcto. ¿Se le pasó la salida? Siga hasta la próxima."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-026","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a ramp has a traffic signal (ramp meter) before the expressway. How do you use it?","o":["Wait for green, then one car goes on each green light","All cars in line go on one green light","Ignore it if the expressway looks empty","Go on yellow, stop on green"],"h1":"The signal lets cars onto the expressway a little at a time.","h2":"At a ramp meter, wait for the green light, and then only one car goes for each green unless a sign says otherwise.","p":"Right. At a ramp meter, one car goes on each green light."},"es":{"q":"En Florida, una rampa tiene un semáforo (medidor de rampa) antes de la autopista. ¿Cómo se usa?","o":["Espere la luz verde; pasa un carro con cada luz verde","Todos los carros de la fila pasan con una sola luz verde","Ignórelo si la autopista se ve vacía","Pase con luz amarilla y deténgase con luz verde"],"h1":"El semáforo deja entrar los carros a la autopista poco a poco.","h2":"En un medidor de rampa, espere la luz verde, y luego pasa solo un carro con cada luz verde, a menos que un letrero diga otra cosa.","p":"Correcto. En el medidor de rampa, pasa un carro con cada luz verde."},"ref":{"doc":"FL","page":53}},{"id":"speed-lanes-027","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you are in the left lane of a multi-lane highway. A faster car comes up behind you. What must you do?","o":["Stay in the left lane at the speed limit","Speed up to stay ahead of it","Tap your brakes to slow it down","Move to the right when it is safe and let it pass"],"h1":"On a highway with several lanes, the left lane is mainly for passing.","h2":"Florida law says that if a faster car is coming up behind you in the left lane, you must move right when it is safe and let it pass.","p":"Right. In the left lane, move right for faster traffic behind you."},"es":{"q":"En Florida, usted va por el carril izquierdo de una carretera de varios carriles. Un carro más rápido se acerca por detrás. ¿Qué debe hacer?","o":["Quedarse en el carril izquierdo al límite de velocidad","Acelerar para seguir delante de él","Frenar un poco para que baje la velocidad","Pasarse a la derecha cuando sea seguro y dejarlo pasar"],"h1":"En una carretera de varios carriles, el carril izquierdo es sobre todo para rebasar.","h2":"La ley de Florida dice que si un carro más rápido se acerca por detrás en el carril izquierdo, debe pasarse a la derecha cuando sea seguro y dejarlo pasar.","p":"Correcto. En el carril izquierdo, muévase a la derecha si viene alguien más rápido."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-029","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, when must your headlights be on?","o":["Only after midnight","From sunset to sunrise","Only on unlit country roads","Only when another car flashes its lights"],"h1":"Think about the hours when it gets dark outside.","h2":"In Florida your headlights must be on from sunset to sunrise, so you can see and others can see you.","p":"Right. Headlights go on from sunset to sunrise."},"es":{"q":"En Florida, ¿cuándo deben estar encendidas las luces delanteras?","o":["Solo después de la medianoche","Desde la puesta del sol hasta la salida del sol","Solo en caminos rurales sin luz","Solo cuando otro carro le hace cambio de luces"],"h1":"Piense en las horas en que oscurece afuera.","h2":"En Florida sus luces delanteras deben estar encendidas desde la puesta del sol hasta la salida del sol, para que usted vea y lo vean.","p":"Correcto. Las luces van encendidas desde la puesta hasta la salida del sol."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-030","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is daytime but rain, smoke, or fog makes it hard to see. What must you do with your headlights?","o":["Leave them off because it is daytime","Turn on only your parking lights","Turn on your hazard lights and keep driving","Turn them on"],"h1":"Lights help other drivers see you, not only help you see.","h2":"In Florida you must turn on your headlights during rain, smoke, or fog, even in the daytime, so other drivers can see you.","p":"Right. Rain, smoke, or fog means headlights on, even by day."},"es":{"q":"En Florida, es de día pero la lluvia, el humo o la neblina hacen difícil ver. ¿Qué debe hacer con las luces delanteras?","o":["Dejarlas apagadas porque es de día","Encender solo las luces de estacionamiento","Encender las luces intermitentes y seguir manejando","Encenderlas"],"h1":"Las luces ayudan a que otros lo vean, no solo a que usted vea.","h2":"En Florida debe encender las luces delanteras con lluvia, humo o neblina, aunque sea de día, para que los demás conductores lo vean.","p":"Correcto. Con lluvia, humo o neblina, encienda las luces, aunque sea de día."},"ref":{"doc":"FL","page":71}},{"id":"speed-lanes-031","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a car is coming toward you at night. How close can it get before you must dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Bright lights can blind the other driver from far away.","h2":"In Florida you must switch to low beams when an oncoming car is within 500 feet, so you do not blind its driver.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, de noche viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Las luces altas pueden encandilar al otro conductor desde lejos.","h2":"En Florida debe cambiar a luces bajas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Cambie a luces bajas a 500 pies de un carro que viene de frente."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-032","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind another car at night. How close can you get before you must dim your high beams?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Your bright lights shine into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet of a car ahead of you, so your lights do not blind the driver through the mirrors.","p":"Right. Dim your lights within 300 feet of a car you are following."},"es":{"q":"En Florida, de noche usted va detrás de otro carro. ¿A qué distancia debe cambiar a luces bajas?","o":["50 pies","100 pies","300 pies","700 pies"],"h1":"Sus luces altas se reflejan en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos del carro de adelante, para no encandilar al conductor por los espejos.","p":"Correcto. Cambie a luces bajas a 300 pies del carro que va adelante."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-033","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["High beams","Parking lights only","Low beams","No lights"],"h1":"Fog reflects strong light back into your eyes.","h2":"In fog you should use low beams, because high beams bounce off the fog and make it harder to see.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces altas","Solo luces de estacionamiento","Luces bajas","Ninguna luz"],"h1":"La neblina refleja la luz fuerte hacia sus ojos.","h2":"Con neblina debe usar luces bajas, porque las luces altas rebotan en la neblina y hacen más difícil ver.","p":"Correcto. Use luces bajas con neblina."},"ref":{"doc":"FL","page":72}},{"id":"speed-lanes-034","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 30 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Florida you may not park within 15 feet of a fire hydrant, so firefighters can reach it quickly.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Florida, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies"],"h1":"Los bomberos necesitan espacio para conectar las mangueras.","h2":"En Florida no puede estacionarse a menos de 15 pies de un hidrante, para que los bomberos lleguen rápido a él.","p":"Correcto. Estaciónese al menos a 15 pies de un hidrante."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-035","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"Drivers must be able to see people who are walking across.","h2":"In Florida you may not park within 20 feet of a crosswalk at an intersection, so drivers can see people crossing.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Florida, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies"],"h1":"Los conductores deben poder ver a las personas que cruzan caminando.","h2":"En Florida no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección, para que los conductores vean a quienes cruzan.","p":"Correcto. Estaciónese al menos a 20 pies de un cruce peatonal en una intersección."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-036","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to a stop sign may you park?","o":["No closer than 10 feet","No closer than 30 feet","No closer than 15 feet","No closer than 100 feet"],"h1":"A parked car could hide the sign from other drivers.","h2":"In Florida you may not park within 30 feet of a stop sign, so other drivers can see the sign clearly.","p":"Right. Park at least 30 feet from a stop sign."},"es":{"q":"En Florida, ¿qué tan cerca de un letrero de PARE puede estacionarse?","o":["No a menos de 10 pies","No a menos de 30 pies","No a menos de 15 pies","No a menos de 100 pies"],"h1":"Un carro estacionado podría tapar el letrero para otros conductores.","h2":"En Florida no puede estacionarse a menos de 30 pies de un letrero de PARE, para que los demás conductores lo vean bien.","p":"Correcto. Estaciónese al menos a 30 pies de un letrero de PARE."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-037","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 10 feet"],"h1":"Trains are wide and drivers need a clear view of the tracks.","h2":"In Florida you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Florida, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 15 pies","No a menos de 50 pies","No a menos de 25 pies","No a menos de 10 pies"],"h1":"Los trenes son anchos y los conductores necesitan ver bien las vías.","h2":"En Florida no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de tren.","p":"Correcto. Estaciónese al menos a 50 pies de un cruce de tren."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-038","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Straight ahead","It does not matter","Toward the curb"],"h1":"Think about where the car would roll if the brakes failed.","h2":"When you park downhill next to a curb, turn your front wheels toward the curb, so the car rolls into the curb if it moves.","p":"Right. Downhill with a curb, turn your wheels toward the curb."},"es":{"q":"En Florida, se estaciona en bajada junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Rectas hacia adelante","No importa","Hacia la acera"],"h1":"Piense hacia dónde rodaría el carro si fallaran los frenos.","h2":"Cuando se estaciona en bajada junto a la acera, gire las ruedas delanteras hacia la acera, para que el carro choque con ella si se mueve.","p":"Correcto. En bajada con acera, gire las ruedas hacia la acera."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-039","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"h1":"If the car rolls back, you want the back of the front tire to touch the curb.","h2":"When you park uphill next to a curb, turn your front wheels away from the curb, so the tire catches the curb if the car rolls back.","p":"Right. Uphill with a curb, turn your wheels away from the curb."},"es":{"q":"En Florida, se estaciona en subida junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Hacia la acera","Rectas hacia adelante","No importa"],"h1":"Si el carro rueda hacia atrás, quiere que la llanta delantera toque la acera.","h2":"Cuando se estaciona en subida junto a la acera, gire las ruedas delanteras lejos de la acera, para que la llanta se apoye en ella si el carro rueda hacia atrás.","p":"Correcto. En subida con acera, gire las ruedas lejos de la acera."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-040","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, when you parallel park next to a curb, how close to the curb must your wheels be?","o":["Within 24 inches","Within 36 inches","Within 12 inches","Within 6 feet"],"h1":"Your car should be close enough that it does not stick out into traffic.","h2":"In Florida your wheels must be within 12 inches of the curb when you parallel park, so your car does not block the lane.","p":"Right. Park with your wheels within 12 inches of the curb."},"es":{"q":"En Florida, al estacionarse en paralelo junto a la acera, ¿qué tan cerca de la acera deben quedar las ruedas?","o":["A 24 pulgadas o menos","A 36 pulgadas o menos","A 12 pulgadas o menos","A 6 pies o menos"],"h1":"Su carro debe quedar lo bastante cerca para no salirse hacia el tráfico.","h2":"En Florida las ruedas deben quedar a 12 pulgadas o menos de la acera al estacionarse en paralelo, para que su carro no tape el carril.","p":"Correcto. Estaciónese con las ruedas a 12 pulgadas o menos de la acera."},"ref":{"doc":"FL","page":65}},{"id":"speed-lanes-041","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, who may park in a space marked for people with disabilities?","o":["Anyone, if it is only for a few minutes","Anyone, if the lot is full","A driver with a valid disabled parking permit or plate shown","Any driver over 65 years old"],"h1":"These spaces are saved for people who have official proof.","h2":"Only a vehicle showing a valid disabled parking permit or license plate may park in a disabled space, even for a short time.","p":"Right. Disabled spaces are only for vehicles with a valid permit or plate."},"es":{"q":"En Florida, ¿quién puede estacionarse en un espacio para personas con discapacidad?","o":["Cualquiera, si es solo por unos minutos","Cualquiera, si el estacionamiento está lleno","Un conductor que muestre un permiso o placa válida de discapacidad","Cualquier conductor mayor de 65 años"],"h1":"Estos espacios son para personas que tienen un comprobante oficial.","h2":"Solo un vehículo que muestre un permiso o una placa válida de discapacidad puede estacionarse en ese espacio, aunque sea por poco tiempo.","p":"Correcto. Los espacios para personas con discapacidad son solo para vehículos con permiso o placa válida."},"ref":{"doc":"FL","page":25}},{"id":"speed-lanes-042","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you park on the striped lines next to a disabled parking space?","o":["No, that area must stay clear for wheelchairs and lifts","Yes, if you have a permit","Yes, for up to 15 minutes","Yes, if you stay in the car"],"h1":"Think about what a person in a wheelchair needs to get out of a van.","h2":"You may not park on the striped area next to a disabled space, because it must stay clear for wheelchairs and lifts.","p":"Right. Never park on the striped access aisle."},"es":{"q":"En Florida, ¿puede estacionarse sobre las rayas al lado de un espacio para personas con discapacidad?","o":["No, esa área debe quedar libre para sillas de ruedas y plataformas elevadoras","Sí, si tiene permiso","Sí, hasta 15 minutos","Sí, si se queda dentro del carro"],"h1":"Piense en lo que necesita una persona en silla de ruedas para bajar de una camioneta.","h2":"No puede estacionarse en el área con rayas junto a un espacio para personas con discapacidad, porque debe quedar libre para sillas de ruedas y plataformas elevadoras.","p":"Correcto. Nunca se estacione en el pasillo con rayas."},"ref":{"doc":"FL","page":null}}];
